fn configure_login_path() {
    #[cfg(unix)]
    {
        use std::os::unix::ffi::OsStringExt;

        let shell = std::env::var_os("SHELL").unwrap_or_else(|| {
            if cfg!(target_os = "macos") { "/bin/zsh".into() } else { "/bin/sh".into() }
        });
        let output = Command::new(shell)
            .args(["-l", "-c", "printf '\\n__GITCITO_LOGIN_PATH__%s\\n' \"$PATH\""])
            .output();
        let Ok(output) = output else { return };
        if !output.status.success() { return; }
        let marker = b"__GITCITO_LOGIN_PATH__";
        let Some(start) = output.stdout.windows(marker.len()).rposition(|window| window == marker) else { return };
        let path = output.stdout[start + marker.len()..]
            .split(|byte| *byte == b'\n' || *byte == b'\r')
            .next().unwrap_or_default();
        if path.is_empty() { return; }

        // This runs before eframe or any worker threads start, so no concurrent
        // environment reads can race with the process-wide PATH update.
        unsafe { std::env::set_var("PATH", std::ffi::OsString::from_vec(path.to_vec())); }
    }
}

fn credential_helper_or_github(
    config: &git2::Config,
    url: &str,
    username: Option<&str>,
    allowed: git2::CredentialType,
) -> Result<Cred, git2::Error> {
    if let Some(credential) = keychain::github_credential(url, allowed) {
        Ok(credential)
    } else {
        Cred::credential_helper(config, url, username)
    }
}

fn main() -> eframe::Result {
    let args = std::env::args_os().skip(1).collect::<Vec<_>>();
    if args.first().is_some_and(|arg| arg == "--gitcito-noop-editor") {
        return Ok(());
    }
    if args.first().is_some_and(|arg| arg == "--gitcito-sequence-editor") {
        let result = args.get(1).zip(args.get(2))
            .ok_or_else(|| std::io::Error::other("Missing sequence editor paths"))
            .and_then(|(source, target)| std::fs::copy(source, target).map(|_| ()));
        if let Err(error) = result {
            eprintln!("Gitcito sequence editor failed: {error}");
            std::process::exit(1);
        }
        return Ok(());
    }
    configure_login_path();
    let preferences = Preferences::load();
    let repo_path = args.first().cloned()
        .map(PathBuf::from)
        .or_else(|| preferences.active_repository.clone())
        .or_else(|| preferences.recent_repositories.first().cloned())
        .or_else(|| std::env::current_dir().ok());

    eframe::run_native(
        "Gitcito",
        eframe::NativeOptions {
            viewport: eframe::egui::ViewportBuilder::default()
                .with_inner_size([1440.0, 900.0])
                .with_min_inner_size([1120.0, 720.0]),
            ..Default::default()
        },
        Box::new(move |creation_context| {
            let mut fonts = eframe::egui::FontDefinitions::default();
            let sans = "ibm-plex-sans";
            let mono = "ibm-plex-mono";
            let icon_family = "phosphor";
            fonts.font_data.insert(
                sans.to_owned(),
                std::sync::Arc::new(eframe::egui::FontData::from_static(
                    include_bytes!("../assets/IBMPlexSans-Regular.ttf"),
                )),
            );
            fonts.font_data.insert(
                mono.to_owned(),
                std::sync::Arc::new(eframe::egui::FontData::from_static(
                    include_bytes!("../assets/IBMPlexMono-Regular.ttf"),
                )),
            );
            fonts.font_data.insert(
                icon_family.to_owned(),
                std::sync::Arc::new(eframe::egui::FontData::from_static(
                    include_bytes!("../assets/Phosphor-Regular.ttf"),
                )),
            );
            fonts.families.insert(
                eframe::egui::FontFamily::Proportional,
                vec![
                    sans.to_owned(),
                    "Ubuntu-Light".to_owned(),
                    "NotoEmoji-Regular".to_owned(),
                    "emoji-icon-font".to_owned(),
                ],
            );
            fonts.families.insert(
                eframe::egui::FontFamily::Monospace,
                vec![
                    mono.to_owned(),
                    "Hack".to_owned(),
                    "Ubuntu-Light".to_owned(),
                    "NotoEmoji-Regular".to_owned(),
                    "emoji-icon-font".to_owned(),
                ],
            );
            fonts.families.insert(
                eframe::egui::FontFamily::Name(icon_family.into()),
                vec![icon_family.to_owned()],
            );
            creation_context.egui_ctx.set_fonts(fonts);
            Ok(Box::new(GitcitoApp::new(repo_path, preferences)))
        }),
    )
}

fn scan_repository_root(root: &Path, max_depth: u8) -> Vec<PathBuf> {
    const SKIP: [&str; 7] = ["node_modules", "vendor", "Pods", "target", "dist", "build", "out"];
    fn walk(path: &Path, depth: u8, found: &mut Vec<PathBuf>) {
        if std::fs::symlink_metadata(path.join(".git")).is_ok() {
            found.push(path.to_path_buf());
            return;
        }
        if depth == 0 { return; }
        let Ok(entries) = std::fs::read_dir(path) else { return; };
        let mut directories = entries.flatten().filter_map(|entry| {
            let name = entry.file_name();
            let name = name.to_string_lossy();
            if name.starts_with('.') || SKIP.contains(&name.as_ref()) { return None; }
            entry.file_type().ok().filter(|kind| kind.is_dir()).map(|_| entry.path())
        }).collect::<Vec<_>>();
        directories.sort();
        for directory in directories {
            walk(&directory, depth - 1, found);
        }
    }
    let mut found = Vec::new();
    walk(root, max_depth.clamp(1, 10), &mut found);
    found
}

fn repository_owner(url: &str) -> Option<String> {
    let remote_path = if let Some((_, authority_and_path)) = url.split_once("://") {
        authority_and_path.split_once('/')?.1
    } else if url.contains('@') {
        url.split_once(':')?.1
    } else {
        return None;
    };
    let segments = remote_path.split('/').filter(|part| !part.is_empty()).collect::<Vec<_>>();
    (segments.len() >= 2).then(|| segments[0].to_owned())
}

fn branch_pattern_matches(pattern: &str, branch: &str) -> bool {
    if !pattern.contains('*') { return pattern == branch; }
    let mut remainder = branch;
    let mut first = true;
    for part in pattern.split('*') {
        if part.is_empty() { continue; }
        let Some(index) = remainder.find(part) else { return false; };
        if first && !pattern.starts_with('*') && index != 0 { return false; }
        remainder = &remainder[index + part.len()..];
        first = false;
    }
    pattern.ends_with('*') || remainder.is_empty()
}

fn repo_config_protected_branches(repo: &Repository) -> Vec<String> {
    let Some(value) = repo_config_json(repo) else { return Vec::new(); };
    value.get("protect").and_then(serde_json::Value::as_array)
        .into_iter().flatten().filter_map(serde_json::Value::as_str)
        .map(str::trim).filter(|pattern| !pattern.is_empty() && pattern.chars().count() <= 200)
        .take(50).map(str::to_owned).collect()
}

fn repo_config_json(repo: &Repository) -> Option<serde_json::Value> {
    let path = repo.workdir()?.join(".gitcito.json");
    let metadata = std::fs::metadata(&path).ok()?;
    if !metadata.is_file() || metadata.len() > 1024 * 1024 { return None; }
    let value = serde_json::from_slice::<serde_json::Value>(&std::fs::read(path).ok()?).ok()?;
    (value.get("version").and_then(serde_json::Value::as_u64) == Some(1)).then_some(value)
}

fn repo_config_commit_rules(repo: &Repository) -> (bool, Vec<String>, Vec<String>) {
    let Some(config) = repo_config_json(repo) else { return (false, Vec::new(), Vec::new()); };
    let Some(commit) = config.get("commit").and_then(serde_json::Value::as_object) else {
        return (false, Vec::new(), Vec::new());
    };
    let ticket = commit.get("ticketFromBranch").and_then(serde_json::Value::as_bool).unwrap_or(false);
    let trailers = commit.get("trailers").and_then(serde_json::Value::as_array)
        .into_iter().flatten().filter_map(serde_json::Value::as_str).map(str::trim)
        .filter(|line| !line.is_empty() && line.chars().count() <= 200)
        .take(10).map(str::to_owned).collect();
    let scopes = commit.get("scopes").and_then(serde_json::Value::as_array)
        .into_iter().flatten().filter_map(serde_json::Value::as_str).map(str::trim)
        .filter(|scope| !scope.is_empty() && scope.chars().count() <= 200)
        .take(100).map(str::to_owned).collect();
    (ticket, trailers, scopes)
}

fn repo_config_push_checklist(repo: &Repository) -> Vec<String> {
    let Some(config) = repo_config_json(repo) else { return Vec::new(); };
    config.get("checklist").and_then(serde_json::Value::as_object)
        .and_then(|checklist| checklist.get("push")).and_then(serde_json::Value::as_array)
        .into_iter().flatten().filter_map(serde_json::Value::as_str).map(str::trim)
        .filter(|line| !line.is_empty() && line.chars().count() <= 200)
        .take(20).map(str::to_owned).collect()
}

#[derive(Clone)]
struct TicketLinkRule {
    matcher: regex::Regex,
    url: String,
    label: Option<String>,
}

struct TicketTextSegment {
    text: String,
    url: Option<String>,
    label: Option<String>,
}

fn safe_http_url(url: &str) -> bool {
    url.len() <= 200 && !url.chars().any(char::is_whitespace)
        && (url.get(..7).is_some_and(|scheme| scheme.eq_ignore_ascii_case("http://"))
            || url.get(..8).is_some_and(|scheme| scheme.eq_ignore_ascii_case("https://")))
}

fn repo_config_ticket_links(repo: &Repository) -> Vec<TicketLinkRule> {
    let Some(config) = repo_config_json(repo) else { return Vec::new(); };
    config.get("links").and_then(serde_json::Value::as_object)
        .and_then(|links| links.get("tickets")).and_then(serde_json::Value::as_array)
        .into_iter().flatten().take(10).filter_map(|entry| {
            let entry = entry.as_object()?;
            let pattern = entry.get("match")?.as_str()?.trim();
            let url = entry.get("url")?.as_str()?.trim();
            if pattern.is_empty() || pattern.chars().count() > 120 || !safe_http_url(url) { return None; }
            let matcher = RegexBuilder::new(pattern).build().ok()?;
            let label = entry.get("label").and_then(serde_json::Value::as_str)
                .map(str::trim).filter(|label| !label.is_empty() && label.chars().count() <= 200)
                .map(str::to_owned);
            Some(TicketLinkRule { matcher, url: url.to_owned(), label })
        }).collect()
}

#[derive(Clone)]
struct RepoFileRequirement {
    path: String,
    from: Option<String>,
    why: Option<String>,
}

fn safe_repo_relative_path(value: &str) -> bool {
    if value.is_empty() || value.chars().count() > 200 || value.contains('\0')
        || value.starts_with('/') || value.starts_with('\\') || value.starts_with('~')
        || value.as_bytes().get(1) == Some(&b':')
    { return false; }
    !value.split(['/', '\\']).any(|segment| segment == ".." || segment == ".git")
}

fn repo_config_file_requirements(repo: &Repository) -> Vec<RepoFileRequirement> {
    let Some(config) = repo_config_json(repo) else { return Vec::new(); };
    config.get("requires").and_then(serde_json::Value::as_object)
        .and_then(|requires| requires.get("files")).and_then(serde_json::Value::as_array)
        .into_iter().flatten().take(20).filter_map(|entry| {
            let (path, from, why) = match entry {
                serde_json::Value::String(path) => (path.as_str(), None, None),
                serde_json::Value::Object(entry) => (
                    entry.get("path")?.as_str()?,
                    entry.get("from").and_then(serde_json::Value::as_str),
                    entry.get("why").and_then(serde_json::Value::as_str),
                ),
                _ => return None,
            };
            let path = path.trim();
            if !safe_repo_relative_path(path) { return None; }
            let from = from.map(str::trim).filter(|path| safe_repo_relative_path(path)).map(str::to_owned);
            let why = why.map(str::trim).filter(|why| !why.is_empty() && why.chars().count() <= 200).map(str::to_owned);
            Some(RepoFileRequirement { path: path.to_owned(), from, why })
        }).collect()
}

fn repo_config_required_hooks_path(repo: &Repository) -> Option<String> {
    let config = repo_config_json(repo)?;
    let path = config.get("requires")?.get("hooksPath")?.as_str()?.trim();
    safe_repo_relative_path(path).then(|| path.to_owned())
}

fn repo_config_required_node(repo: &Repository) -> Option<String> {
    let config = repo_config_json(repo)?;
    let spec = config.get("requires")?.get("node")?.as_str()?.trim();
    (!spec.is_empty() && spec.chars().count() <= 200).then(|| spec.to_owned())
}

fn repo_config_required_git_features(repo: &Repository) -> (bool, bool) {
    let Some(config) = repo_config_json(repo) else { return (false, false); };
    let Some(requires) = config.get("requires").and_then(serde_json::Value::as_object) else {
        return (false, false);
    };
    (
        requires.get("submodules").and_then(serde_json::Value::as_bool).unwrap_or(false),
        requires.get("lfs").and_then(serde_json::Value::as_bool).unwrap_or(false),
    )
}

fn node_major(version: &str) -> Option<u64> {
    let digits = version.find(|ch: char| ch.is_ascii_digit())?;
    let end = version[digits..].find(|ch: char| !ch.is_ascii_digit()).map(|index| digits + index)
        .unwrap_or(version.len());
    version[digits..end].parse().ok()
}

fn node_version_satisfies(actual: &str, spec: &str) -> bool {
    let Some(actual) = node_major(actual) else { return false; };
    let spec = spec.trim();
    let Some(wanted) = node_major(spec) else { return true; };
    if spec.starts_with(">=") || spec.starts_with('^') || spec.starts_with('~') { actual >= wanted }
    else if spec.starts_with('>') { actual > wanted }
    else if spec.starts_with("<=") { actual <= wanted }
    else if spec.starts_with('<') { actual < wanted }
    else { actual == wanted }
}

fn installed_node_version(repo: &Repository) -> Option<String> {
    let workdir = repo.workdir()?;
    let output = Command::new("node").arg("--version").current_dir(workdir).output().ok()?;
    output.status.success().then(|| String::from_utf8_lossy(&output.stdout).trim().to_owned())
}

fn normalize_hooks_path(repo: &Repository, configured: Option<&str>) -> Option<String> {
    let configured = configured?.trim();
    let path = Path::new(configured);
    let relative = if path.is_absolute() {
        path.strip_prefix(repo.workdir()?).ok()?.to_path_buf()
    } else {
        path.to_path_buf()
    };
    Some(relative.to_string_lossy().replace('\\', "/"))
}

fn ticket_text_segments(text: &str, rules: &[TicketLinkRule]) -> Vec<TicketTextSegment> {
    let mut matches = Vec::<(usize, usize, String, Option<String>)>::new();
    for rule in rules {
        for captures in rule.matcher.captures_iter(text) {
            let Some(matched) = captures.get(0) else { continue; };
            if matched.start() == matched.end()
                || matches.iter().any(|(start, end, _, _)| matched.start() < *end && matched.end() > *start)
            { continue; }
            let mut url = String::new();
            captures.expand(&rule.url, &mut url);
            if safe_http_url(&url) {
                matches.push((matched.start(), matched.end(), url, rule.label.clone()));
            }
        }
    }
    matches.sort_by_key(|(start, _, _, _)| *start);
    let mut segments = Vec::new();
    let mut cursor = 0;
    for (start, end, url, label) in matches {
        if start > cursor {
            segments.push(TicketTextSegment { text: text[cursor..start].to_owned(), url: None, label: None });
        }
        segments.push(TicketTextSegment { text: text[start..end].to_owned(), url: Some(url), label });
        cursor = end;
    }
    if cursor < text.len() || segments.is_empty() {
        segments.push(TicketTextSegment { text: text[cursor..].to_owned(), url: None, label: None });
    }
    segments
}

fn show_ticket_linked_text(ui: &mut eframe::egui::Ui, text: &str, rules: &[TicketLinkRule]) {
    ui.horizontal_wrapped(|ui| {
        for segment in ticket_text_segments(text, rules) {
            if let Some(url) = segment.url {
                let response = ui.hyperlink_to(segment.text, url);
                if let Some(label) = segment.label { response.on_hover_text(label); }
            } else if !segment.text.is_empty() {
                ui.label(segment.text);
            }
        }
    });
}

