fn ticket_from_branch(branch: &str) -> Option<String> {
    RegexBuilder::new(r"([A-Z][A-Z0-9]+-\d+)").build().ok()?
        .find(branch).map(|ticket| ticket.as_str().to_owned())
}

fn append_configured_trailers(message: &str, trailers: &[String], branch: &str) -> String {
    let ticket = RegexBuilder::new(r"^([A-Z][A-Z0-9]+-\d+)").build().ok()
        .and_then(|regex| message.lines().next().and_then(|line| regex.captures(line)))
        .and_then(|captures| captures.get(1).map(|capture| capture.as_str().to_owned()))
        .or_else(|| ticket_from_branch(branch)).unwrap_or_default();
    let mut rendered = Vec::new();
    for template in trailers {
        let mut line = template.clone();
        let mut dropped = false;
        for (placeholder, value) in [("{ticket}", ticket.as_str()), ("{branch}", branch)] {
            if !value.trim().is_empty() {
                line = line.replace(placeholder, value.trim());
            } else if line.contains(placeholder) {
                line = line.replace(placeholder, "");
                dropped = true;
            }
        }
        if !dropped { rendered.push(line); }
    }
    let existing = message.lines().map(|line| line.trim().to_lowercase()).collect::<BTreeSet<_>>();
    let missing = rendered.into_iter().filter(|line| !existing.contains(&line.trim().to_lowercase()))
        .collect::<Vec<_>>();
    if missing.is_empty() { return message.to_owned(); }
    let body = message.trim_end();
    if body.is_empty() { missing.join("\n") } else { format!("{body}\n\n{}", missing.join("\n")) }
}

fn conventional_scope(message: &str) -> Option<(String, String, String, String)> {
    let subject = message.lines().next()?;
    let (prefix, rest) = subject.split_once(':')?;
    let rest = rest.trim_start();
    let bang = prefix.ends_with('!');
    let prefix = prefix.strip_suffix('!').unwrap_or(prefix);
    let (kind, scope) = match prefix.split_once('(') {
        Some((kind, scope)) if scope.ends_with(')') => (kind, &scope[..scope.len() - 1]),
        Some(_) => return None,
        None => (prefix, ""),
    };
    const TYPES: [&str; 11] = ["feat", "fix", "docs", "style", "refactor", "perf", "test", "build", "ci", "chore", "revert"];
    if !TYPES.contains(&kind) { return None; }
    Some((kind.to_owned(), scope.to_owned(), if bang { "!" } else { "" }.to_owned(), rest.to_owned()))
}

fn apply_commit_scope(message: &str, scope: &str) -> Option<String> {
    let (kind, _, bang, rest) = conventional_scope(message)?;
    let subject = format!("{kind}{}{bang}: {rest}", if scope.is_empty() { String::new() } else { format!("({scope})") });
    let mut lines = message.lines();
    lines.next()?;
    let body = lines.collect::<Vec<_>>().join("\n");
    Some(if body.is_empty() { subject } else { format!("{subject}\n{body}") })
}

fn repository_summary(path: &Path, include_wip: bool) -> RepositorySummary {
    let Ok(repo) = Repository::discover(path) else { return RepositorySummary::default(); };
    let branch = repo.head().ok().filter(|head| head.is_branch())
        .and_then(|head| head.shorthand().map(str::to_owned));
    let owner = repo.find_remote("origin").ok()
        .and_then(|remote| remote.url().and_then(repository_owner));
    let (changed, ahead, behind) = if include_wip {
        let mut options = git2::StatusOptions::new();
        options.include_untracked(true).recurse_untracked_dirs(true).include_ignored(false);
        let changed = repo.statuses(Some(&mut options)).map(|statuses| statuses.len()).ok();
        let tracking = repo.head().ok().and_then(|head| head.shorthand().map(str::to_owned))
            .and_then(|name| repo.find_branch(&name, git2::BranchType::Local).ok())
            .and_then(|branch| branch.upstream().ok());
        let (ahead, behind) = tracking.and_then(|upstream| {
            let local = repo.head().ok()?.target()?;
            let remote = upstream.get().target()?;
            repo.graph_ahead_behind(local, remote).ok()
        }).map(|(ahead, behind)| (Some(ahead), Some(behind))).unwrap_or((None, None));
        (changed, ahead, behind)
    } else { (None, None, None) };
    RepositorySummary { owner, branch, changed, ahead, behind }
}

