fn reset_preview(repo: &Repository, target: &str) -> Result<ResetPreview, git2::Error> {
    let current = repo.head()?.peel_to_commit()?;
    let target = repo.revparse_single(target)?.peel_to_commit()?;
    let mut walk = repo.revwalk()?;
    walk.push(current.id())?;
    walk.hide(target.id())?;
    let commits_moved = walk.filter_map(Result::ok).count();
    let mut options = DiffOptions::new();
    let diff = repo.diff_tree_to_tree(Some(&current.tree()?), Some(&target.tree()?), Some(&mut options))?;
    let stats = diff.stats()?;
    Ok(ResetPreview {
        current_oid: current.id(),
        target_oid: target.id(),
        commits_moved,
        files_changed: stats.files_changed(),
        insertions: stats.insertions(),
        deletions: stats.deletions(),
    })
}

fn single_commit_preview(
    repo: &Repository,
    operation: HistoryOperation,
    target: &str,
) -> Result<SingleCommitPreview, git2::Error> {
    let current_oid = repo.head()?.peel_to_commit()?.id();
    let commit = repo.find_commit(git2::Oid::from_str(target)?)?;
    let tree = commit.tree()?;
    let parent_tree = commit.parent(0).ok().map(|parent| parent.tree()).transpose()?;
    let diff = repo.diff_tree_to_tree(parent_tree.as_ref(), Some(&tree), None)?;
    let stats = diff.stats()?;
    let (insertions, deletions) = if operation == HistoryOperation::Revert {
        (stats.deletions(), stats.insertions())
    } else {
        (stats.insertions(), stats.deletions())
    };
    Ok(SingleCommitPreview {
        current_oid,
        target_oid: commit.id(),
        files_changed: stats.files_changed(),
        insertions,
        deletions,
    })
}

fn history_operation_preview(repo: &Repository, target: &str) -> Result<HistoryOperationPreview, git2::Error> {
    let current = repo.head()?.peel_to_commit()?;
    let target = repo.revparse_single(target)?.peel_to_commit()?;
    let base_id = repo.merge_base(current.id(), target.id())?;
    let base = repo.find_commit(base_id)?;

    let count_since = |tip: git2::Oid| -> Result<usize, git2::Error> {
        let mut walk = repo.revwalk()?;
        walk.push(tip)?;
        walk.hide(base_id)?;
        Ok(walk.filter_map(Result::ok).count())
    };
    let mut options = DiffOptions::new();
    let diff = repo.diff_tree_to_tree(Some(&base.tree()?), Some(&target.tree()?), Some(&mut options))?;
    let stats = diff.stats()?;

    Ok(HistoryOperationPreview {
        current_oid: current.id(),
        target_oid: target.id(),
        current_only_commits: count_since(current.id())?,
        target_only_commits: count_since(target.id())?,
        target_files_changed: stats.files_changed(),
        target_insertions: stats.insertions(),
        target_deletions: stats.deletions(),
    })
}

fn show_history_operation_preview(
    ui: &mut eframe::egui::Ui,
    language: &str,
    preview: Option<&HistoryOperationPreview>,
) {
    if let Some(preview) = preview {
        egui_components::Card::new()
            .outline()
            .padding(10.0)
            .show(ui, |ui| {
                ui.columns(2, |columns| {
                    columns[0].vertical_centered(|ui| {
                        ui.label(eframe::egui::RichText::new(preview.current_only_commits.to_string())
                            .strong()
                            .size(20.0)
                            .color(ui::palette(ui).accent));
                        ui.small(translate(language, "history.preview.currentOnly"));
                    });
                    columns[1].vertical_centered(|ui| {
                        ui.label(eframe::egui::RichText::new(preview.target_only_commits.to_string())
                            .strong()
                            .size(20.0)
                            .color(ui::palette(ui).accent));
                        ui.small(translate(language, "history.preview.targetOnly"));
                    });
                });
            });
        ui.add(egui_components::Alert::new(translate_interpolated(
            language,
            "history.preview.targetChanges",
            &[
                ("files", preview.target_files_changed.to_string()),
                ("insertions", preview.target_insertions.to_string()),
                ("deletions", preview.target_deletions.to_string()),
            ],
        )).info());
    }
}

fn rerere_replayed_paths(output: &str) -> Vec<String> {
    output.lines().filter_map(|line| {
        line.trim().strip_prefix("Resolved '")
            .and_then(|line| line.split_once("' using previous resolution"))
            .map(|(path, _)| path.to_owned())
    }).collect()
}

fn run_rerere(repo_path: &Path) -> Vec<String> {
    Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("rerere")
        .output()
        .ok()
        .map(|output| {
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);
            rerere_replayed_paths(&format!("{stdout}\n{stderr}"))
        })
        .unwrap_or_default()
}

fn commit_lane_color(lane: usize) -> eframe::egui::Color32 {
    const COLORS: [(u8, u8, u8); 8] = [
        (114, 172, 241), (230, 126, 112), (111, 190, 143), (198, 143, 225),
        (226, 183, 92), (84, 190, 194), (224, 127, 183), (160, 176, 100),
    ];
    let (red, green, blue) = COLORS[lane % COLORS.len()];
    eframe::egui::Color32::from_rgb(red, green, blue)
}

fn format_history_bytes(bytes: u64) -> String {
    if bytes >= 1024 * 1024 {
        format!("{:.1} MB", bytes as f64 / (1024.0 * 1024.0))
    } else if bytes >= 1024 {
        format!("{} KB", (bytes + 512) / 1024)
    } else {
        format!("{bytes} B")
    }
}

fn history_purge_error(language: &str, error: String) -> String {
    let key = if error.starts_with("Path must stay inside the repository:") {
        Some("repoConfig.issueUnsafe")
    } else if error.starts_with("Commit or stash your changes")
        || error.starts_with("Commit, stash, or abort operations")
    {
        Some("purge.blockedDirty")
    } else if error.starts_with("Finish or abort the operation") {
        Some("branch.operationInProgress")
    } else if error.starts_with("Existing filter-branch backups") {
        Some("purge.existingOriginals")
    } else if error.starts_with("No commit touches that path") {
        Some("purge.noCommits")
    } else {
        None
    };
    key.map_or(error, |key| translate(language, key).to_owned())
}

fn commit_graph_layout(commits: &[&CommitRow]) -> Vec<CommitGraphRow> {
    let mut active_lanes: Vec<String> = Vec::new();
    let mut node_lanes = HashMap::new();
    let mut rows = Vec::with_capacity(commits.len());

    for commit in commits {
        let lane = active_lanes
            .iter()
            .position(|oid| oid == &commit.oid)
            .unwrap_or_else(|| {
                active_lanes.insert(0, commit.oid.clone());
                0
            });
        node_lanes.insert(commit.oid.as_str(), lane);

        if let Some(first_parent) = commit.parents.first() {
            if let Some(parent_lane) = active_lanes.iter().position(|oid| oid == first_parent) {
                if parent_lane != lane {
                    active_lanes.remove(lane);
                }
            } else {
                active_lanes[lane] = first_parent.clone();
            }
            for parent in commit.parents.iter().skip(1) {
                if !active_lanes.iter().any(|oid| oid == parent) {
                    active_lanes.insert((lane + 1).min(active_lanes.len()), parent.clone());
                }
            }
        } else {
            active_lanes.remove(lane);
        }

        rows.push(CommitGraphRow { lane, parent_lanes: Vec::new() });
    }

    for (row, commit) in rows.iter_mut().zip(commits) {
        row.parent_lanes = commit.parents.iter()
            .filter_map(|parent| node_lanes.get(parent.as_str()).copied())
            .collect();
    }
    rows
}

