fn read_commit_note(repo: &Repository, commit: git2::Oid) -> Result<Option<String>, git2::Error> {
    match repo.find_note(Some(COMMIT_NOTES_REF), commit) {
        Ok(note) => Ok(note.message().map(|message| message.trim_end().to_owned())),
        Err(error) if error.code() == git2::ErrorCode::NotFound => Ok(None),
        Err(error) => Err(error),
    }
}

fn write_commit_note(repo: &Repository, commit: git2::Oid, note: Option<&str>) -> Result<(), git2::Error> {
    let signature = repo.signature()?;
    match note.filter(|message| !message.is_empty()) {
        Some(message) => repo.note(&signature, &signature, Some(COMMIT_NOTES_REF), commit, message, true).map(|_| ()),
        None => match repo.find_note(Some(COMMIT_NOTES_REF), commit) {
            Ok(_) => repo.note_delete(commit, Some(COMMIT_NOTES_REF), &signature, &signature),
            Err(error) if error.code() == git2::ErrorCode::NotFound => Ok(()),
            Err(error) => Err(error),
        },
    }
}

fn reference_target(repo: &Repository, name: &str) -> Result<Option<git2::Oid>, git2::Error> {
    match repo.find_reference(name) {
        Ok(reference) => Ok(reference.target()),
        Err(error) if error.code() == git2::ErrorCode::NotFound => Ok(None),
        Err(error) => Err(error),
    }
}

fn parse_worktrees(output: &str, current: &Path) -> Vec<WorktreeRow> {
    let mut rows = Vec::new();
    let mut path: Option<PathBuf> = None;
    let mut branch = None;
    let mut head = String::new();
    let mut locked = false;
    let mut detached = false;
    let flush = |rows: &mut Vec<WorktreeRow>, path: &mut Option<PathBuf>, branch: &mut Option<String>,
                 head: &mut String, locked: &mut bool, detached: &mut bool| {
        if let Some(path) = path.take() {
            rows.push(WorktreeRow {
                is_main: rows.is_empty(),
                is_current: path == current,
                path,
                branch: branch.take(),
                head: std::mem::take(head),
                locked: std::mem::replace(locked, false),
                detached: std::mem::replace(detached, false),
            });
        }
    };
    for line in output.lines() {
        if let Some(value) = line.strip_prefix("worktree ") {
            flush(&mut rows, &mut path, &mut branch, &mut head, &mut locked, &mut detached);
            path = Some(PathBuf::from(value));
        } else if let Some(value) = line.strip_prefix("HEAD ") {
            head = value.to_owned();
        } else if let Some(value) = line.strip_prefix("branch refs/heads/") {
            branch = Some(value.to_owned());
        } else if line == "detached" {
            detached = true;
        } else if line == "locked" || line.starts_with("locked ") {
            locked = true;
        }
    }
    flush(&mut rows, &mut path, &mut branch, &mut head, &mut locked, &mut detached);
    rows
}

fn worktree_lock_state(repo_path: &Path, worktree_path: &Path) -> Result<Option<bool>, String> {
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .args(["worktree", "list", "--porcelain"])
        .output()
        .map_err(|error| error.to_string())?;
    if !output.status.success() {
        return Err(String::from_utf8_lossy(&output.stderr).trim().to_owned());
    }
    Ok(parse_worktrees(&String::from_utf8_lossy(&output.stdout), repo_path)
        .into_iter()
        .find(|worktree| worktree.path == worktree_path)
        .map(|worktree| worktree.locked))
}

fn set_worktree_lock(repo_path: &Path, worktree_path: &Path, locked: bool) -> Result<(), String> {
    let operation = if locked { "lock" } else { "unlock" };
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .args(["worktree", operation])
        .arg(worktree_path)
        .output()
        .map_err(|error| error.to_string())?;
    if output.status.success() {
        Ok(())
    } else {
        Err(String::from_utf8_lossy(&output.stderr).trim().to_owned())
    }
}

fn parse_submodules(output: &str) -> Vec<SubmoduleRow> {
    output.lines().filter_map(|line| {
        let marker = line.chars().next()?;
        let rest = line[1..].trim_start();
        let (oid, rest) = rest.split_once(char::is_whitespace)?;
        let rest = rest.trim_start();
        let path = rest.rfind(" (").filter(|_| rest.ends_with(')'))
            .map(|index| &rest[..index]).unwrap_or(rest).trim_end();
        if path.is_empty() { return None; }
        let state = match marker {
            '-' => "uninitialized",
            '+' => "out of sync",
            'U' => "conflict",
            _ => "initialized",
        }.to_owned();
        Some(SubmoduleRow { path: path.to_owned(), oid: oid.to_owned(), state })
    }).collect()
}

fn system_prefers_dark() -> bool {
    #[cfg(target_os = "macos")]
    {
        return Command::new("defaults").args(["read", "-g", "AppleInterfaceStyle"]).output()
            .map(|output| output.status.success() && String::from_utf8_lossy(&output.stdout).trim().eq_ignore_ascii_case("dark"))
            .unwrap_or(false);
    }
    #[cfg(target_os = "windows")]
    {
        return Command::new("reg").args([
            "query", r"HKCU\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize",
            "/v", "AppsUseLightTheme",
        ]).output()
            .map(|output| output.status.success() && String::from_utf8_lossy(&output.stdout).contains("0x0"))
            .unwrap_or(true);
    }
    #[cfg(target_os = "linux")]
    {
        if let Ok(output) = Command::new("gsettings")
            .args(["get", "org.gnome.desktop.interface", "color-scheme"]).output()
            && output.status.success()
        {
            return String::from_utf8_lossy(&output.stdout).to_lowercase().contains("dark");
        }
        if let Ok(theme) = std::env::var("GTK_THEME") {
            return theme.to_lowercase().contains("dark");
        }
        return true;
    }
    #[allow(unreachable_code)]
    true
}

fn parse_patch_hunks(patch: &[u8]) -> Vec<Vec<u8>> {
    let mut header = Vec::new();
    let mut hunks = Vec::new();
    let mut current = Vec::new();
    for line in patch.split_inclusive(|byte| *byte == b'\n') {
        if line.starts_with(b"@@ ") {
            if !current.is_empty() {
                hunks.push(std::mem::take(&mut current));
            }
            current.extend_from_slice(&header);
            current.extend_from_slice(line);
        } else if current.is_empty() {
            header.extend_from_slice(line);
        } else {
            current.extend_from_slice(line);
        }
    }
    if !current.is_empty() {
        hunks.push(current);
    }
    hunks
}

fn patch_hunk_body(patch: &[u8]) -> Option<Vec<Vec<u8>>> {
    let mut in_body = false;
    let mut body = Vec::new();
    for line in patch.split_inclusive(|byte| *byte == b'\n') {
        if line.starts_with(b"@@ ") {
            in_body = true;
        } else if in_body {
            body.push(line.to_vec());
        }
    }
    in_body.then_some(body)
}

fn word_change_ranges(old: &str, new: &str) -> (std::ops::Range<usize>, std::ops::Range<usize>) {
    let mut prefix = 0;
    for (left, right) in old.chars().zip(new.chars()) {
        if left != right { break; }
        prefix += left.len_utf8();
    }
    let old_tail = &old[prefix..];
    let new_tail = &new[prefix..];
    let mut suffix = 0;
    for (left, right) in old_tail.chars().rev().zip(new_tail.chars().rev()) {
        if left != right { break; }
        suffix += left.len_utf8();
    }
    (prefix..old.len() - suffix, prefix..new.len() - suffix)
}

fn diff_word_ranges(lines: &[String]) -> HashMap<usize, std::ops::Range<usize>> {
    let mut ranges = HashMap::new();
    let mut index = 0;
    while index < lines.len() {
        if !lines[index].starts_with('-') || lines[index].starts_with("--- ") {
            index += 1;
            continue;
        }
        let mut removed = Vec::new();
        while index < lines.len() && lines[index].starts_with('-') && !lines[index].starts_with("--- ") {
            removed.push(index);
            index += 1;
        }
        let mut added = Vec::new();
        while index < lines.len() && lines[index].starts_with('+') && !lines[index].starts_with("+++ ") {
            added.push(index);
            index += 1;
        }
        for (old_index, new_index) in removed.into_iter().zip(added) {
            let (old_range, new_range) = word_change_ranges(&lines[old_index][1..], &lines[new_index][1..]);
            if !old_range.is_empty() {
                ranges.insert(old_index, old_range.start + 1..old_range.end + 1);
            }
            if !new_range.is_empty() {
                ranges.insert(new_index, new_range.start + 1..new_range.end + 1);
            }
        }
    }
    ranges
}

fn show_diff_line(
    ui: &mut eframe::egui::Ui,
    line: &str,
    color: eframe::egui::Color32,
    range: Option<&std::ops::Range<usize>>,
) {
    let Some(range) = range.filter(|range| range.start < range.end && range.end <= line.len()) else {
        ui.label(eframe::egui::RichText::new(line).monospace().color(color));
        return;
    };
    let mut job = eframe::egui::text::LayoutJob::default();
    let base = eframe::egui::TextFormat::simple(eframe::egui::FontId::monospace(13.0), color);
    let mut changed = base.clone();
    let palette = ui::palette(ui);
    changed.background = ui::tint(
        if line.starts_with('+') { palette.success } else { palette.danger },
        if ui.visuals().dark_mode { 72 } else { 40 },
    );
    job.append(&line[..range.start], 0.0, base.clone());
    job.append(&line[range.clone()], 0.0, changed);
    job.append(&line[range.end..], 0.0, base);
    ui.label(job);
}

fn diff_line_numbers(lines: &[String]) -> Vec<(Option<usize>, Option<usize>)> {
    let mut positions = Vec::with_capacity(lines.len());
    let mut old_line: Option<usize> = None;
    let mut new_line: Option<usize> = None;
    let mut in_hunk = false;

    for line in lines {
        if line.starts_with("@@ ") {
            let mut parts = line.split_whitespace().skip(1);
            old_line = parts.next().and_then(|part| part.trim_start_matches('-').split(',').next()?.parse().ok());
            new_line = parts.next().and_then(|part| part.trim_start_matches('+').split(',').next()?.parse().ok());
            in_hunk = true;
            positions.push((None, None));
            continue;
        }
        if line.starts_with("diff --git ") || line.starts_with("--- ") || line.starts_with("+++ ") {
            in_hunk = false;
            old_line = None;
            new_line = None;
            positions.push((None, None));
            continue;
        }
        if !in_hunk || line.starts_with("\\ No newline") {
            positions.push((None, None));
            continue;
        }

        let (old, new) = if line.starts_with('-') {
            (old_line, None)
        } else if line.starts_with('+') {
            (None, new_line)
        } else {
            (old_line, new_line)
        };
        positions.push((old, new));
        if old.is_some() { old_line = old_line.map(|number| number.saturating_add(1)); }
        if new.is_some() { new_line = new_line.map(|number| number.saturating_add(1)); }
    }
    positions
}

fn show_diff_row(
    ui: &mut eframe::egui::Ui,
    line: &str,
    old_line: Option<usize>,
    new_line: Option<usize>,
    color: eframe::egui::Color32,
    range: Option<&std::ops::Range<usize>>,
) -> eframe::egui::Response {
    let palette = ui::palette(ui);
    let fill = if line.starts_with('+') && !line.starts_with("+++") {
        ui::tint(palette.success, 22)
    } else if line.starts_with('-') && !line.starts_with("---") {
        ui::tint(palette.danger, 22)
    } else if line.starts_with("@@") {
        ui::tint(palette.accent, 18)
    } else {
        eframe::egui::Color32::TRANSPARENT
    };
    eframe::egui::Frame::new()
        .fill(fill)
        .inner_margin(eframe::egui::Margin::symmetric(4, 0))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.horizontal(|ui| {
                for number in [old_line, new_line] {
                    let label = number.map_or_else(String::new, |value| value.to_string());
                    ui.add_sized(
                        [30.0, 18.0],
                        eframe::egui::Label::new(
                            eframe::egui::RichText::new(label)
                                .monospace()
                                .small()
                                .color(ui.visuals().weak_text_color()),
                        ).halign(eframe::egui::Align::RIGHT),
                    );
                }
                show_diff_line(ui, line, color, range);
            });
        })
        .response
}

#[derive(Default)]
struct SplitDiffRow {
    old: Option<usize>,
    new: Option<usize>,
}

fn flush_split_changes(rows: &mut Vec<SplitDiffRow>, removed: &mut Vec<usize>, added: &mut Vec<usize>) {
    let count = removed.len().max(added.len());
    for offset in 0..count {
        rows.push(SplitDiffRow {
            old: removed.get(offset).copied(),
            new: added.get(offset).copied(),
        });
    }
    removed.clear();
    added.clear();
}

fn split_diff_rows(lines: &[String]) -> Vec<SplitDiffRow> {
    let mut rows = Vec::new();
    let mut removed = Vec::new();
    let mut added = Vec::new();
    for (index, line) in lines.iter().enumerate() {
        if line.starts_with('-') && !line.starts_with("--- ") {
            removed.push(index);
        } else if line.starts_with('+') && !line.starts_with("+++ ") {
            added.push(index);
        } else {
            flush_split_changes(&mut rows, &mut removed, &mut added);
            if line.starts_with("--- ") {
                rows.push(SplitDiffRow { old: Some(index), new: None });
            } else if line.starts_with("+++ ") {
                rows.push(SplitDiffRow { old: None, new: Some(index) });
            } else {
                rows.push(SplitDiffRow { old: Some(index), new: Some(index) });
            }
        }
    }
    flush_split_changes(&mut rows, &mut removed, &mut added);
    rows
}

fn show_split_diff_pane(
    ui: &mut eframe::egui::Ui,
    lines: &[String],
    line_numbers: &[(Option<usize>, Option<usize>)],
    rows: &[SplitDiffRow],
    old_side: bool,
    wrap: bool,
    selected_match: Option<usize>,
    word_ranges: &HashMap<usize, std::ops::Range<usize>>,
) {
    let palette = ui::palette(ui);
    ui.style_mut().wrap_mode = Some(if wrap {
        eframe::egui::TextWrapMode::Wrap
    } else {
        eframe::egui::TextWrapMode::Extend
    });
    for row in rows {
        let line_index = if old_side { row.old } else { row.new };
        if let Some(index) = line_index {
            let line = &lines[index];
            let (old_line, new_line) = line_numbers.get(index).copied().unwrap_or_default();
            let color = match line.as_bytes().first() {
                Some(b'+') => palette.success,
                Some(b'-') => palette.danger,
                Some(b'@') => palette.accent,
                _ => ui.visuals().text_color(),
            };
            if selected_match == Some(index) {
                let response = show_diff_row(
                    ui,
                    line,
                    if old_side { old_line } else { None },
                    if old_side { None } else { new_line },
                    ui::palette(ui).warning,
                    word_ranges.get(&index),
                );
                ui.scroll_to_rect(response.rect, Some(eframe::egui::Align::Center));
            } else {
                show_diff_row(
                    ui,
                    line,
                    if old_side { old_line } else { None },
                    if old_side { None } else { new_line },
                    color,
                    word_ranges.get(&index),
                );
            }
        } else {
            show_diff_row(ui, "", None, None, ui.visuals().weak_text_color(), None);
        }
    }
}

fn is_supported_image_path(path: &str) -> bool {
    Path::new(path).extension().and_then(|extension| extension.to_str())
        .is_some_and(|extension| matches!(extension.to_ascii_lowercase().as_str(), "png" | "jpg" | "jpeg" | "gif" | "webp"))
}

fn decode_preview_image(bytes: &[u8]) -> Result<eframe::egui::ColorImage, String> {
    let limits = || {
        let mut limits = Limits::default();
        limits.max_image_width = Some(8192);
        limits.max_image_height = Some(8192);
        limits.max_alloc = Some(64 * 1024 * 1024);
        limits
    };
    let mut reader = ImageReader::new(Cursor::new(bytes))
        .with_guessed_format()
        .map_err(|error| error.to_string())?;
    reader.limits(limits());
    let (width, height) = reader.into_dimensions().map_err(|error| error.to_string())?;
    if u64::from(width) * u64::from(height) > 12_000_000 {
        return Err("Image preview limited to 12 megapixels".to_owned());
    }
    let mut reader = ImageReader::new(Cursor::new(bytes))
        .with_guessed_format()
        .map_err(|error| error.to_string())?;
    reader.limits(limits());
    let image = reader.decode().map_err(|error| error.to_string())?.to_rgba8();
    Ok(eframe::egui::ColorImage::from_rgba_unmultiplied(
        [width as usize, height as usize],
        image.as_raw(),
    ))
}

fn ensure_image_texture(
    ui: &mut eframe::egui::Ui,
    cache: &mut Option<(String, Result<eframe::egui::TextureHandle, String>)>,
    cache_key: &str,
    bytes: &[u8],
) {
    if cache.as_ref().is_none_or(|(key, _)| key != cache_key) {
        let texture = decode_preview_image(bytes).map(|image| {
            ui.ctx().load_texture(cache_key, image, eframe::egui::TextureOptions::LINEAR)
        });
        *cache = Some((cache_key.to_owned(), texture));
    }
}

fn show_image_preview(
    ui: &mut eframe::egui::Ui,
    cache: &mut Option<(String, Result<eframe::egui::TextureHandle, String>)>,
    cache_key: &str,
    bytes: &[u8],
) {
    ensure_image_texture(ui, cache, cache_key, bytes);
    if let Some((_, Ok(texture))) = cache.as_ref() {
        ui.add(
            eframe::egui::Image::new((texture.id(), texture.size_vec2()))
                .max_size(ui.available_size()),
        );
    } else if let Some((_, Err(error))) = cache.as_ref() {
        ui.colored_label(ui::palette(ui).danger, error);
    }
}

fn image_fit_rect(frame: eframe::egui::Rect, image_size: eframe::egui::Vec2) -> eframe::egui::Rect {
    let scale = (frame.width() / image_size.x).min(frame.height() / image_size.y);
    let size = image_size * scale;
    eframe::egui::Rect::from_center_size(frame.center(), size)
}

fn show_image_swipe(
    ui: &mut eframe::egui::Ui,
    before: &eframe::egui::TextureHandle,
    after: &eframe::egui::TextureHandle,
    position: &mut f32,
) {
    let available = ui.available_size().max(eframe::egui::vec2(1.0, 1.0));
    let (frame, response) = ui.allocate_exact_size(available, eframe::egui::Sense::drag());
    if response.dragged()
        && let Some(pointer) = response.interact_pointer_pos()
    {
        *position = ((pointer.x - frame.left()) / frame.width()).clamp(0.0, 1.0);
    }
    let painter = ui.painter_at(frame);
    painter.rect_filled(frame, 0.0, ui.visuals().faint_bg_color);
    let before_rect = image_fit_rect(frame, before.size_vec2());
    let after_rect = image_fit_rect(frame, after.size_vec2());
    painter.image(after.id(), after_rect, eframe::egui::Rect::EVERYTHING, eframe::egui::Color32::WHITE);
    let divider = frame.left() + frame.width() * *position;
    let old_clip = eframe::egui::Rect::from_min_max(frame.min, eframe::egui::pos2(divider, frame.bottom()));
    painter.with_clip_rect(old_clip).image(
        before.id(),
        before_rect,
        eframe::egui::Rect::EVERYTHING,
        eframe::egui::Color32::WHITE,
    );
    painter.line_segment(
        [eframe::egui::pos2(divider, frame.top()), eframe::egui::pos2(divider, frame.bottom())],
        eframe::egui::Stroke::new(2.0, eframe::egui::Color32::WHITE),
    );
}

fn build_line_patch(patch: &[u8], selected: &BTreeSet<usize>) -> Option<Vec<u8>> {
    let mut header = Vec::new();
    let mut hunk_header = None;
    let mut body = Vec::new();
    for line in patch.split_inclusive(|byte| *byte == b'\n') {
        if hunk_header.is_none() {
            if line.starts_with(b"@@ ") {
                hunk_header = Some(line.to_vec());
            } else {
                header.extend_from_slice(line);
            }
        } else {
            body.push(line.to_vec());
        }
    }
    let header_text = String::from_utf8_lossy(hunk_header.as_ref()?);
    let old_header = header_text.trim_end();
    let ranges = old_header.split_whitespace().collect::<Vec<_>>();
    if ranges.len() < 4 { return None; }
    let old_start = ranges[1].trim_start_matches('-').split(',').next()?.parse::<usize>().ok()?;
    let new_start = ranges[2].trim_start_matches('+').split(',').next()?.parse::<usize>().ok()?;
    let suffix = old_header.rfind("@@").map(|index| &old_header[index + 2..]).unwrap_or_default();
    let mut output = header;
    let mut result_body = Vec::new();
    let (mut old_count, mut new_count) = (0usize, 0usize);
    let mut change_index = 0usize;
    let mut has_selected = false;
    for line in body {
        match line.first().copied() {
            Some(b' ') => {
                result_body.extend_from_slice(&line);
                old_count += 1;
                new_count += 1;
            }
            Some(b'-') => {
                if selected.contains(&change_index) {
                    result_body.extend_from_slice(&line);
                    old_count += 1;
                    has_selected = true;
                } else {
                    result_body.push(b' ');
                    result_body.extend_from_slice(&line[1..]);
                    old_count += 1;
                    new_count += 1;
                }
                change_index += 1;
            }
            Some(b'+') => {
                if selected.contains(&change_index) {
                    result_body.extend_from_slice(&line);
                    new_count += 1;
                    has_selected = true;
                }
                change_index += 1;
            }
            Some(b'\\') => result_body.extend_from_slice(&line),
            _ => {}
        }
    }
    if !has_selected { return None; }
    output.extend_from_slice(format!("@@ -{old_start},{old_count} +{new_start},{new_count} @@{suffix}\n").as_bytes());
    output.extend_from_slice(&result_body);
    Some(output)
}

fn sparse_checkout_info(repo: &Repository) -> Result<SparseCheckoutInfo, git2::Error> {
    let config = repo.config()?;
    let enabled = config.get_bool("core.sparseCheckout").unwrap_or(false);
    let cone = config.get_bool("core.sparseCheckoutCone").unwrap_or(false);
    let top_level_dirs = repo.head().ok().and_then(|head| head.peel_to_tree().ok())
        .map(|tree| tree.iter()
            .filter(|entry| entry.kind() == Some(git2::ObjectType::Tree))
            .filter_map(|entry| entry.name().map(str::to_owned))
            .collect())
        .unwrap_or_default();
    let dirs = if enabled {
        let workdir = repo.workdir().ok_or_else(|| git2::Error::from_str("Sparse checkout requires a working tree"))?;
        let output = Command::new("git").arg("-C").arg(workdir)
            .args(["sparse-checkout", "list"]).output()
            .map_err(|error| git2::Error::from_str(&error.to_string()))?;
        if !output.status.success() {
            return Err(git2::Error::from_str(&String::from_utf8_lossy(&output.stderr)));
        }
        String::from_utf8_lossy(&output.stdout).lines()
            .map(|line| line.trim().trim_matches('/').to_owned())
            .filter(|line| !line.is_empty()).collect()
    } else { Vec::new() };
    Ok(SparseCheckoutInfo { enabled, cone, dirs, top_level_dirs })
}

fn parse_git_tool_help(output: &str) -> Vec<NativeDiffToolInfo> {
    let mut available = true;
    let mut tools = Vec::new();
    for line in output.lines() {
        if line.to_ascii_lowercase().contains("not currently available") {
            available = false;
            continue;
        }
        if !line.starts_with(char::is_whitespace) { continue; }
        let Some(id) = line.split_whitespace().next() else { continue };
        if !id.chars().all(|character| character.is_ascii_alphanumeric() || ".+-_".contains(character)) {
            continue;
        }
        let description = line.trim().strip_prefix(id).unwrap_or_default().trim().to_owned();
        tools.push(NativeDiffToolInfo { id: id.to_owned(), description, available });
    }
    tools.sort_by(|left, right| {
        right.available.cmp(&left.available).then_with(|| left.id.cmp(&right.id))
    });
    tools
}

fn git_global_config(key: &str) -> String {
    Command::new("git")
        .args(["config", "--global", "--get", key])
        .output()
        .ok()
        .filter(|output| output.status.success())
        .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_owned())
        .unwrap_or_default()
}

fn native_diff_tool_config() -> Result<NativeDiffToolConfig, String> {
    let help = |command: &str| {
        let output = Command::new("git").args([command, "--tool-help"]).output()
            .map_err(|error| error.to_string())?;
        let mut text = String::from_utf8_lossy(&output.stdout).into_owned();
        text.push_str(&String::from_utf8_lossy(&output.stderr));
        Ok::<_, String>(parse_git_tool_help(&text))
    };
    let diff_tools = help("difftool")?;
    let merge_tools = help("mergetool")?;
    let keep_backup = git_global_config("mergetool.keepBackup");
    Ok(NativeDiffToolConfig {
        diff_tool: git_global_config("diff.tool"),
        merge_tool: git_global_config("merge.tool"),
        keep_backup: keep_backup != "false",
        diff_tools,
        merge_tools,
    })
}

fn set_git_global_config(key: &str, value: &str) -> Result<(), String> {
    let output = if value.is_empty() {
        Command::new("git").args(["config", "--global", "--unset", key]).output()
    } else {
        Command::new("git").args(["config", "--global", key, value]).output()
    }.map_err(|error| error.to_string())?;
    if output.status.success() || value.is_empty() && output.status.code() == Some(5) {
        Ok(())
    } else {
        Err(String::from_utf8_lossy(&output.stderr).trim().to_owned())
    }
}

fn save_native_diff_tool_config(
    diff_tool: &str,
    merge_tool: &str,
    keep_backup: bool,
) -> Result<(), String> {
    set_git_global_config("diff.tool", diff_tool)?;
    set_git_global_config("merge.tool", merge_tool)?;
    set_git_global_config("mergetool.keepBackup", if keep_backup { "true" } else { "false" })
}

fn set_sparse_checkout(path: &Path, info: &SparseCheckoutInfo) -> Result<(), String> {
    let mut command = Command::new("git");
    command.arg("-C").arg(path).args(["sparse-checkout"]);
    if !info.enabled {
        command.arg("disable");
    } else {
        command.arg("set");
        command.arg(if info.cone { "--cone" } else { "--no-cone" });
        command.arg("--");
        command.args(&info.dirs);
    }
    let output = command.output().map_err(|error| error.to_string())?;
    if output.status.success() { Ok(()) }
    else { Err(redact_url_credentials(String::from_utf8_lossy(&output.stderr).trim())) }
}

fn local_git_config(path: &Path, key: &str) -> Result<Option<String>, git2::Error> {
    let output = Command::new("git").arg("-C").arg(path)
        .args(["config", "--local", "--get", key]).output()
        .map_err(|error| git2::Error::from_str(&error.to_string()))?;
    if output.status.success() {
        Ok(Some(String::from_utf8_lossy(&output.stdout).trim_end().to_owned()))
    } else if output.status.code() == Some(1) {
        Ok(None)
    } else {
        Err(git2::Error::from_str(&String::from_utf8_lossy(&output.stderr)))
    }
}

fn write_local_git_config(path: &Path, key: &str, value: Option<&str>) -> Result<(), git2::Error> {
    let mut command = Command::new("git");
    command.arg("-C").arg(path).args(["config", "--local"]);
    if let Some(value) = value {
        command.args(["--replace-all", key, value]);
    } else {
        command.args(["--unset-all", key]);
    }
    let output = command.output().map_err(|error| git2::Error::from_str(&error.to_string()))?;
    if output.status.success() || (value.is_none() && output.status.code() == Some(5)) { Ok(()) }
    else { Err(git2::Error::from_str(&String::from_utf8_lossy(&output.stderr))) }
}

fn lfs_state(repo: &Repository) -> LfsState {
    let Some(workdir) = repo.workdir() else { return LfsState::default() };
    let installed = Command::new("git").arg("-C").arg(workdir)
        .args(["lfs", "version"]).output()
        .is_ok_and(|output| output.status.success());
    if !installed { return LfsState::default(); }
    let attributes = std::fs::read_to_string(workdir.join(".gitattributes")).unwrap_or_default();
    let patterns = attributes.lines().map(str::trim)
        .filter(|line| !line.is_empty() && !line.starts_with('#') && line.contains("filter=lfs"))
        .filter_map(|line| line.split_whitespace().next().map(str::to_owned))
        .collect::<Vec<_>>();
    let files_output = Command::new("git").arg("-C").arg(workdir)
        .args(["lfs", "ls-files"]).output().ok()
        .filter(|output| output.status.success())
        .map(|output| String::from_utf8_lossy(&output.stdout).into_owned())
        .unwrap_or_default();
    let files = files_output.lines().filter_map(|line| {
        let line = line.trim();
        let first = line.find(char::is_whitespace)?;
        let oid = &line[..first];
        let remaining = line[first..].trim_start();
        let marker = remaining.chars().next()?;
        if marker != '*' && marker != '-' { return None; }
        let path = remaining[marker.len_utf8()..].trim_start();
        if path.is_empty() { return None; }
        Some(LfsFileRow { oid: oid.to_owned(), downloaded: marker == '*', path: path.to_owned() })
    }).collect::<Vec<_>>();
    LfsState { installed, enabled: !patterns.is_empty() || !files.is_empty(), patterns, files }
}

fn shell_quote(value: &str) -> String {
    #[cfg(windows)]
    let value = value.replace('\\', "/");
    format!("'{}'", value.replace('\'', "'\\''"))
}

fn read_bisect_status(repo: &Repository, output: &str) -> BisectStatus {
    let git_path = |name: &str| {
        let direct = repo.path().join(name);
        if direct.exists() { return direct; }
        repo.workdir().and_then(|workdir| Command::new("git").arg("-C").arg(workdir)
            .args(["rev-parse", "--git-path", name]).output().ok())
            .filter(|result| result.status.success())
            .map(|result| PathBuf::from(String::from_utf8_lossy(&result.stdout).trim()))
            .unwrap_or(direct)
    };
    let in_progress = git_path("BISECT_START").exists();
    if !in_progress { return BisectStatus { remaining_steps: -1, ..BisectStatus::default() }; }
    let log = std::fs::read_to_string(git_path("BISECT_LOG")).unwrap_or_default();
    let text = format!("{log}\n{output}").to_lowercase();
    let bad_marks = log.lines().filter(|line| line.starts_with("# bad:")).count();
    let good_marks = log.lines().filter(|line| line.starts_with("# good:")).count();
    let need_bad = bad_marks == 0;
    let need_good = bad_marks > 0 && good_marks == 0;
    let first_bad_sha = output.lines().find_map(|line| {
        let marker = " is the first bad commit";
        let end = line.find(marker)?;
        line[..end].split_whitespace().last().map(str::to_owned)
    }).unwrap_or_default();
    let finished = !first_bad_sha.is_empty();
    let remaining_steps = text.find("roughly ").and_then(|start| {
        let number = &text[start + 8..];
        let digits = number.chars().take_while(char::is_ascii_digit).collect::<String>();
        digits.parse().ok()
    }).unwrap_or(-1);
    let (current_sha, current_subject) = if !finished && !need_good && !need_bad {
        let head = repo.head().ok().and_then(|head| head.peel_to_commit().ok());
        head.map(|commit| (commit.id().to_string(), commit.summary().unwrap_or_default().to_owned()))
            .unwrap_or_default()
    } else { (String::new(), String::new()) };
    let first_bad_subject = if finished {
        git2::Oid::from_str(&first_bad_sha).ok()
            .and_then(|oid| repo.find_commit(oid).ok())
            .and_then(|commit| commit.summary().map(str::to_owned)).unwrap_or_default()
    } else { String::new() };
    BisectStatus {
        in_progress, need_good, need_bad, current_sha, current_subject,
        remaining_steps, finished, first_bad_sha, first_bad_subject,
    }
}

const KNOWN_HOOKS: &[&str] = &[
    "applypatch-msg", "pre-applypatch", "post-applypatch", "pre-commit", "pre-merge-commit",
    "prepare-commit-msg", "commit-msg", "post-commit", "pre-rebase", "post-checkout", "post-merge",
    "pre-push", "post-rewrite", "pre-auto-gc",
];

fn hooks_dir(repo: &Repository) -> Result<(PathBuf, bool), git2::Error> {
    let workdir = repo.workdir().ok_or_else(|| git2::Error::from_str("Hooks need a working tree"))?;
    if let Ok(custom) = repo.config()?.get_string("core.hooksPath") {
        let expanded = if custom == "~" || custom.starts_with("~/") {
            let home = dirs::home_dir().unwrap_or_default();
            if custom == "~" { home } else { home.join(custom.trim_start_matches("~/")) }
        } else {
            let path = PathBuf::from(&custom);
            if path.is_absolute() { path } else { workdir.join(path) }
        };
        return Ok((expanded, true));
    }
    let output = Command::new("git").arg("-C").arg(workdir)
        .args(["rev-parse", "--git-path", "hooks"]).output()
        .map_err(|error| git2::Error::from_str(&error.to_string()))?;
    if output.status.success() {
        let value = String::from_utf8_lossy(&output.stdout).trim().to_owned();
        let path = PathBuf::from(value);
        return Ok((if path.is_absolute() { path } else { workdir.join(path) }, false));
    }
    Ok((repo.path().join("hooks"), false))
}

fn hook_executable(metadata: &std::fs::Metadata) -> bool {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        metadata.permissions().mode() & 0o111 != 0
    }
    #[cfg(not(unix))]
    { !metadata.permissions().readonly() }
}

fn hook_mode(metadata: &std::fs::Metadata) -> u32 {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        metadata.permissions().mode()
    }
    #[cfg(not(unix))]
    { if metadata.permissions().readonly() { 0o444 } else { 0o755 } }
}

fn inspect_hooks(repo: &Repository) -> Result<HooksState, git2::Error> {
    let (dir, custom_path) = hooks_dir(repo)?;
    let hooks = KNOWN_HOOKS.iter().map(|name| {
        let path = dir.join(name);
        let metadata = std::fs::metadata(&path).ok().filter(|meta| meta.is_file());
        HookRow {
            name: (*name).to_owned(),
            exists: metadata.is_some(),
            executable: metadata.as_ref().is_some_and(hook_executable),
            sample: !path.exists() && path.with_extension("sample").exists(),
        }
    }).collect();
    let pre_commit_framework = repo.workdir().is_some_and(|workdir| {
        workdir.join(".pre-commit-config.yaml").exists()
            || workdir.join(".pre-commit-config.yml").exists()
    });
    Ok(HooksState { dir: Some(dir), custom_path, pre_commit_framework, hooks })
}

fn hook_snapshot(path: &Path) -> Result<HookSnapshot, git2::Error> {
    match std::fs::symlink_metadata(path) {
        Ok(metadata) if metadata.is_file() => Ok(HookSnapshot {
            path: path.to_path_buf(),
            contents: Some(std::fs::read(path).map_err(|error| git2::Error::from_str(&error.to_string()))?),
            mode: hook_mode(&metadata),
        }),
        Ok(_) => Err(git2::Error::from_str("Hook path is not a regular file")),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(HookSnapshot {
            path: path.to_path_buf(), contents: None, mode: 0,
        }),
        Err(error) => Err(git2::Error::from_str(&error.to_string())),
    }
}

fn restore_hook_snapshot(snapshot: &HookSnapshot) -> Result<(), git2::Error> {
    match &snapshot.contents {
        Some(contents) => {
            if let Some(parent) = snapshot.path.parent() {
                std::fs::create_dir_all(parent).map_err(|error| git2::Error::from_str(&error.to_string()))?;
            }
            std::fs::write(&snapshot.path, contents).map_err(|error| git2::Error::from_str(&error.to_string()))?;
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                std::fs::set_permissions(&snapshot.path, std::fs::Permissions::from_mode(snapshot.mode))
                    .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            }
            #[cfg(not(unix))]
            {
                let mut permissions = std::fs::metadata(&snapshot.path)
                    .map_err(|error| git2::Error::from_str(&error.to_string()))?.permissions();
                permissions.set_readonly(snapshot.mode & 0o222 == 0);
                std::fs::set_permissions(&snapshot.path, permissions)
                    .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            }
            Ok(())
        }
        None => match std::fs::remove_file(&snapshot.path) {
            Ok(()) => Ok(()),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(error) => Err(git2::Error::from_str(&error.to_string())),
        },
    }
}

fn set_hook_executable(path: &Path, enabled: bool) -> Result<(), git2::Error> {
    let metadata = std::fs::metadata(path).map_err(|error| git2::Error::from_str(&error.to_string()))?;
    let mut permissions = metadata.permissions();
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mode = permissions.mode();
        permissions.set_mode(if enabled { mode | 0o111 } else { mode & !0o111 });
    }
    #[cfg(not(unix))]
    permissions.set_readonly(!enabled);
    std::fs::set_permissions(path, permissions).map_err(|error| git2::Error::from_str(&error.to_string()))
}

