static WIP_SNAPSHOT_SEQUENCE: AtomicU64 = AtomicU64::new(0);
const COMMIT_NOTES_REF: &str = "refs/notes/commits";

fn write_wip_snapshot(path: &Path, kind: char) -> Result<Option<String>, String> {
    let git = |args: &[&str], index: Option<&Path>| {
        let mut command = Command::new("git");
        command.arg("-C").arg(path).args(args);
        if let Some(index) = index { command.env("GIT_INDEX_FILE", index); }
        command.output().map_err(|error| error.to_string())
    };
    let status = git(&["status", "--porcelain"], None)?;
    if !status.status.success() { return Err(String::from_utf8_lossy(&status.stderr).trim().into()); }
    if status.stdout.is_empty() { return Ok(None); }
    let git_dir = git(&["rev-parse", "--absolute-git-dir"], None)?;
    if !git_dir.status.success() { return Err(String::from_utf8_lossy(&git_dir.stderr).trim().into()); }
    let index = PathBuf::from(String::from_utf8_lossy(&git_dir.stdout).trim()).join(format!(
        "gitcito-snapshot-{}-{}-{}", std::process::id(),
        std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis(),
        WIP_SNAPSHOT_SEQUENCE.fetch_add(1, Ordering::Relaxed)
    ));
    let head = git(&["rev-parse", "--verify", "HEAD"], None).ok().filter(|out| out.status.success())
        .map(|out| String::from_utf8_lossy(&out.stdout).trim().to_owned()).unwrap_or_default();
    let seed = if head.is_empty() { "--empty".to_owned() } else { head.clone() };
    let operation = (|| -> Result<Option<String>, String> {
        for args in [vec!["read-tree", seed.as_str()], vec!["add", "-A"], vec!["write-tree"]] {
            let output = git(&args, Some(&index))?;
            if !output.status.success() { return Err(String::from_utf8_lossy(&output.stderr).trim().into()); }
            if args[0] == "write-tree" {
                let tree = String::from_utf8_lossy(&output.stdout).trim().to_owned();
                let head_tree = if head.is_empty() { String::new() } else {
                    let output = git(&["rev-parse", &format!("{head}^{{tree}}")], None)?;
                    String::from_utf8_lossy(&output.stdout).trim().to_owned()
                };
                if tree == head_tree { return Ok(None); }
                if kind != 'm' {
                    let latest = git(&["for-each-ref", "--sort=-creatordate", "--format=%(objectname)", "refs/gitcito/wip"], None)?;
                    if latest.status.success() {
                        if let Some(previous) = String::from_utf8_lossy(&latest.stdout).lines().next() {
                            let previous_tree = git(&["rev-parse", &format!("{previous}^{{tree}}")], None)?;
                            if previous_tree.status.success() && String::from_utf8_lossy(&previous_tree.stdout).trim() == tree {
                                return Ok(None);
                            }
                        }
                    }
                }
                let mut args = vec!["commit-tree".to_owned(), tree, "-m".to_owned(), "gitcito WIP snapshot".to_owned()];
                if !head.is_empty() { args.extend(["-p".to_owned(), head.clone()]); }
                let output = git(&args.iter().map(String::as_str).collect::<Vec<_>>(), None)?;
                if !output.status.success() { return Err(String::from_utf8_lossy(&output.stderr).trim().into()); }
                let oid = String::from_utf8_lossy(&output.stdout).trim().to_owned();
                let millis = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis();
                let reference = format!("refs/gitcito/wip/{millis}-{kind}");
                let update = git(&["update-ref", &reference, &oid], None)?;
                if !update.status.success() { return Err(String::from_utf8_lossy(&update.stderr).trim().into()); }
                let refs = git(&["for-each-ref", "--sort=-creatordate", "--format=%(refname)", "refs/gitcito/wip"], None)?;
                if refs.status.success() {
                    for old in String::from_utf8_lossy(&refs.stdout).lines().skip(50) {
                        let _ = git(&["update-ref", "-d", old], None);
                    }
                }
                return Ok(Some(oid));
            }
        }
        Ok(None)
    })();
    let _ = std::fs::remove_file(index);
    operation
}

