fn github_notification_browser_url(notification: &serde_json::Value) -> String {
    let repository_url = notification.pointer("/repository/html_url")
        .and_then(serde_json::Value::as_str).unwrap_or_default().trim_end_matches('/');
    let subject_url = notification.pointer("/subject/url")
        .and_then(serde_json::Value::as_str).unwrap_or_default();
    let subject_type = notification.pointer("/subject/type")
        .and_then(serde_json::Value::as_str).unwrap_or_default();
    let tail = subject_url.rsplit('/').next().unwrap_or_default();
    let number = tail.parse::<u64>().ok();
    match subject_type {
        "PullRequest" => number.map(|number| format!("{repository_url}/pull/{number}")),
        "Issue" => number.map(|number| format!("{repository_url}/issues/{number}")),
        "Discussion" => number.map(|number| format!("{repository_url}/discussions/{number}")),
        "Release" => Some(format!("{repository_url}/releases")),
        "Commit" if tail.len() == 40 && tail.chars().all(|character| character.is_ascii_hexdigit()) => {
            Some(format!("{repository_url}/commit/{tail}"))
        }
        _ => None,
    }.unwrap_or_else(|| repository_url.to_owned())
}

fn github_notification_reason(language: &str, reason: &str) -> String {
    let key = match reason {
        "assign" => "notif.reason.assign",
        "author" => "notif.reason.author",
        "comment" => "notif.reason.comment",
        "invitation" => "notif.reason.invitation",
        "manual" => "notif.reason.manual",
        "mention" => "notif.reason.mention",
        "push" => "notif.reason.push",
        "security_alert" => "notif.reason.security_alert",
        "state_change" => "notif.reason.state_change",
        "team_mention" => "notif.reason.team_mention",
        "ci_activity" => "notif.ciActivity",
        "review_requested" => "notif.reviewRequested",
        _ => return reason.replace('_', " "),
    };
    translate(language, key).to_owned()
}

fn show_github_desktop_notification(language: &str, notification: serde_json::Value) {
    let reason = notification.get("reason").and_then(serde_json::Value::as_str).unwrap_or_default();
    let heading_key = match reason {
        "review_requested" => "notif.reviewRequested",
        "ci_activity" => "notif.ciActivity",
        _ => return,
    };
    let summary = format!(
        "{} · {}",
        translate(language, heading_key),
        notification.pointer("/repository/full_name")
            .and_then(serde_json::Value::as_str).unwrap_or_default(),
    );
    let body = notification.pointer("/subject/title")
        .and_then(serde_json::Value::as_str).unwrap_or_default().to_owned();
    let url = github_notification_browser_url(&notification);
    let open_label = translate(language, "notif.openBrowser").to_owned();
    std::thread::spawn(move || {
        let Ok(handle) = notify_rust::Notification::new()
            .appname("Gitcito")
            .summary(&summary)
            .body(&body)
            .action("default", &open_label)
            .show()
        else {
            return;
        };
        handle.wait_for_action(|action| {
            if action == "default" {
                let _ = open_web_url(&url);
            }
        });
    });
}

