fn parse_native_conflict_hunks(content: &str) -> (Vec<NativeConflictHunk>, String, String) {
    let lines = content.split('\n').map(str::to_owned).collect::<Vec<_>>();
    let mut hunks = Vec::new();
    let mut ours_lines = Vec::new();
    let mut theirs_lines = Vec::new();
    let mut cursor = 0;
    while cursor < lines.len() {
        if !lines[cursor].starts_with("<<<<<<<") {
            ours_lines.push(lines[cursor].clone());
            theirs_lines.push(lines[cursor].clone());
            cursor += 1;
            continue;
        }
        let marker_start = cursor;
        let ours_label = lines[cursor][7..].trim().to_owned();
        cursor += 1;
        let ours_start = cursor;
        while cursor < lines.len()
            && !lines[cursor].starts_with("=======")
            && !lines[cursor].starts_with("|||||||")
        {
            cursor += 1;
        }
        if cursor == lines.len() {
            ours_lines.extend(lines[marker_start..].iter().cloned());
            theirs_lines.extend(lines[marker_start..].iter().cloned());
            break;
        }
        let ours = lines[ours_start..cursor].to_vec();
        if lines[cursor].starts_with("|||||||") {
            while cursor < lines.len() && !lines[cursor].starts_with("=======") {
                cursor += 1;
            }
            if cursor == lines.len() {
                ours_lines.extend(lines[marker_start..].iter().cloned());
                theirs_lines.extend(lines[marker_start..].iter().cloned());
                break;
            }
        }
        cursor += 1;
        let theirs_start = cursor;
        while cursor < lines.len() && !lines[cursor].starts_with(">>>>>>>") {
            cursor += 1;
        }
        if cursor == lines.len() {
            ours_lines.extend(lines[marker_start..].iter().cloned());
            theirs_lines.extend(lines[marker_start..].iter().cloned());
            break;
        }
        let theirs = lines[theirs_start..cursor].to_vec();
        let theirs_label = lines[cursor][7..].trim().to_owned();
        let hunk = NativeConflictHunk {
            ours_start: ours_lines.len(),
            ours,
            theirs,
            ours_label: if ours_label.is_empty() { "ours".into() } else { ours_label },
            theirs_label: if theirs_label.is_empty() { "theirs".into() } else { theirs_label },
        };
        ours_lines.extend(hunk.ours.iter().cloned());
        theirs_lines.extend(hunk.theirs.iter().cloned());
        hunks.push(hunk);
        cursor += 1;
    }
    (hunks, ours_lines.join("\n"), theirs_lines.join("\n"))
}

fn assemble_native_conflict_output(
    ours_content: &str,
    hunks: &[NativeConflictHunk],
    selected: &BTreeSet<(usize, NativeConflictLineSide, usize)>,
) -> String {
    let lines = ours_content.split('\n').collect::<Vec<_>>();
    let mut output = Vec::new();
    let mut cursor = 0;
    for (index, hunk) in hunks.iter().enumerate() {
        while cursor < hunk.ours_start && cursor < lines.len() {
            output.push(lines[cursor].to_owned());
            cursor += 1;
        }
        for (line_index, line) in hunk.ours.iter().enumerate() {
            if selected.contains(&(index, NativeConflictLineSide::Ours, line_index)) {
                output.push(line.clone());
            }
        }
        for (line_index, line) in hunk.theirs.iter().enumerate() {
            if selected.contains(&(index, NativeConflictLineSide::Theirs, line_index)) {
                output.push(line.clone());
            }
        }
        cursor += hunk.ours.len();
    }
    while cursor < lines.len() {
        output.push(lines[cursor].to_owned());
        cursor += 1;
    }
    output.join("\n")
}

fn native_conflict_side_fully_selected(
    hunks: &[NativeConflictHunk],
    selected: &BTreeSet<(usize, NativeConflictLineSide, usize)>,
    side: NativeConflictLineSide,
) -> bool {
    let has_lines = hunks.iter().any(|hunk| match side {
        NativeConflictLineSide::Ours => !hunk.ours.is_empty(),
        NativeConflictLineSide::Theirs => !hunk.theirs.is_empty(),
    });
    !hunks.is_empty() && has_lines && hunks.iter().enumerate().all(|(hunk_index, hunk)| {
        let lines = match side {
            NativeConflictLineSide::Ours => &hunk.ours,
            NativeConflictLineSide::Theirs => &hunk.theirs,
        };
        lines.iter().enumerate()
            .all(|(line_index, _)| selected.contains(&(hunk_index, side, line_index)))
    })
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum FileDetailSection {
    Preview,
    Blame,
    History,
}

fn summary_card(ui: &mut eframe::egui::Ui, count: usize, label: &str, color: eframe::egui::Color32) {
    egui_components::Card::new()
        .outline()
        .padding(8.0)
        .show(ui, |ui| {
            ui.horizontal(|ui| {
                let (dot, _) = ui.allocate_exact_size(
                    eframe::egui::vec2(8.0, 8.0),
                    eframe::egui::Sense::hover(),
                );
                ui.painter().circle_filled(dot.center(), 4.0, color);
                ui.vertical(|ui| {
                    ui.label(eframe::egui::RichText::new(count.to_string()).strong().size(16.0).color(color));
                    ui.label(eframe::egui::RichText::new(label).small().weak());
                });
            });
        });
}

fn relative_commit_age(language: &str, timestamp: i64) -> String {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64;
    let seconds = now.saturating_sub(timestamp).max(0) as u64;
    if seconds < 5 {
        return translate(language, "time.justNow").to_owned();
    }
    let (key, value) = if seconds < 60 {
        ("time.secondsAgo", seconds)
    } else if seconds < 60 * 60 {
        ("time.minutesAgo", seconds / 60)
    } else if seconds < 24 * 60 * 60 {
        ("time.hoursAgo", seconds / (60 * 60))
    } else {
        ("time.daysAgo", seconds / (24 * 60 * 60))
    };
    translate_interpolated(language, key, &[("n", value.to_string())])
}

fn compact_ref_label(name: &str, max_chars: usize) -> String {
    if name.chars().count() <= max_chars {
        return name.to_owned();
    }
    let take = max_chars.saturating_sub(1);
    format!("{}…", name.chars().take(take).collect::<String>())
}

struct TerminalTab {
    id: u64,
    session: TerminalSession,
}

fn terminal_control_code(key: eframe::egui::Key) -> Option<u8> {
    use eframe::egui::Key::*;
    match key {
        A => Some(1), B => Some(2), C => Some(3), D => Some(4), E => Some(5), F => Some(6),
        G => Some(7), H => Some(8), I => Some(9), J => Some(10), K => Some(11), L => Some(12),
        M => Some(13), N => Some(14), O => Some(15), P => Some(16), Q => Some(17), R => Some(18),
        S => Some(19), T => Some(20), U => Some(21), V => Some(22), W => Some(23), X => Some(24),
        Y => Some(25), Z => Some(26),
        _ => None,
    }
}

