    fn start_diff_tool_config_load(&mut self) {
        if self.diff_tool_load_started { return; }
        let (sender, receiver) = mpsc::channel();
        self.diff_tool_config_receiver = Some(receiver);
        self.diff_tool_load_started = true;
        std::thread::spawn(move || { let _ = sender.send(native_diff_tool_config()); });
    }

    fn save_diff_tool_config(&mut self) {
        if self.diff_tool_save_receiver.is_some() { return; }
        let diff_tool = self.diff_tool_draft.clone();
        let merge_tool = self.merge_tool_draft.clone();
        let keep_backup = self.merge_tool_keep_backup;
        let (sender, receiver) = mpsc::channel();
        self.diff_tool_save_receiver = Some(receiver);
        std::thread::spawn(move || {
            let _ = sender.send(save_native_diff_tool_config(&diff_tool, &merge_tool, keep_backup));
        });
    }

    fn poll_diff_tool_config(&mut self) {
        let result = self.diff_tool_config_receiver.as_ref().and_then(|receiver| match receiver.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Disconnected) => Some(Err("Could not load Git diff tools".into())),
            Err(TryRecvError::Empty) => None,
        });
        if let Some(result) = result {
            self.diff_tool_config_receiver = None;
            match result {
                Ok(config) => {
                    self.diff_tool_config_error = None;
                    self.diff_tool_draft.clone_from(&config.diff_tool);
                    self.merge_tool_draft.clone_from(&config.merge_tool);
                    self.merge_tool_keep_backup = config.keep_backup;
                    self.diff_tool_config = Some(config);
                }
                Err(error) => {
                    self.diff_tool_config_error = Some(error.clone());
                    self.error = Some(error);
                }
            }
        }

        let save_result = self.diff_tool_save_receiver.as_ref().and_then(|receiver| match receiver.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Disconnected) => Some(Err("Could not save Git diff tool settings".into())),
            Err(TryRecvError::Empty) => None,
        });
        if let Some(result) = save_result {
            self.diff_tool_save_receiver = None;
            match result {
                Ok(()) => {
                    if let Some(config) = &mut self.diff_tool_config {
                        config.diff_tool.clone_from(&self.diff_tool_draft);
                        config.merge_tool.clone_from(&self.merge_tool_draft);
                        config.keep_backup = self.merge_tool_keep_backup;
                    }
                    self.error = None;
                }
                Err(error) => self.error = Some(error),
            }
        }
    }

    fn run_external_tool(&mut self, kind: ExternalToolKind, file: &str) {
        if self.external_tool_receiver.is_some() { return; }
        let (Some(repo_path), Some(config)) = (self.repo_path.clone(), self.diff_tool_config.as_ref()) else { return };
        let tool = match kind {
            ExternalToolKind::Diff => config.diff_tool.clone(),
            ExternalToolKind::Merge => config.merge_tool.clone(),
        };
        if tool.is_empty() { return; }
        let file = file.to_owned();
        let worker_file = file.clone();
        let (sender, receiver) = mpsc::channel();
        self.external_tool_busy = Some((kind, file.clone()));
        self.external_tool_receiver = Some(receiver);
        std::thread::spawn(move || {
            let command = match kind {
                ExternalToolKind::Diff => "difftool",
                ExternalToolKind::Merge => "mergetool",
            };
            let output = Command::new("git")
                .arg("-C").arg(repo_path)
                .args([command, "--no-prompt"])
                .arg(format!("--tool={tool}"))
                .arg("--").arg(&worker_file)
                .output()
                .map_err(|error| error.to_string())
                .and_then(|output| {
                    if output.status.success() { Ok(()) } else {
                        let detail = if output.stderr.is_empty() { &output.stdout } else { &output.stderr };
                        Err(String::from_utf8_lossy(detail).trim().to_owned())
                    }
                });
            let _ = sender.send((kind, worker_file, output));
        });
    }

    fn poll_external_tool(&mut self, context: &eframe::egui::Context) {
        let result = self.external_tool_receiver.as_ref().and_then(|receiver| match receiver.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Disconnected) => Some((ExternalToolKind::Diff, String::new(), Err("External Git tool stopped unexpectedly".into()))),
            Err(TryRecvError::Empty) => None,
        });
        if let Some((kind, file, result)) = result {
            self.external_tool_receiver = None;
            self.external_tool_busy = None;
            match result {
                Ok(()) => {
                    match kind {
                        ExternalToolKind::Diff => self.error = None,
                        ExternalToolKind::Merge => {
                            self.refresh();
                            self.notice = Some(translate_interpolated(
                                &self.preferences.language,
                                "difftool.merged",
                                &[("file", file)],
                            ));
                        }
                    }
                }
                Err(error) => self.error = Some(error),
            }
        }
        if self.external_tool_receiver.is_some() {
            context.request_repaint_after(std::time::Duration::from_millis(120));
        }
    }

    fn start_history_purge_job(
        &mut self,
        work: impl FnOnce(PathBuf) -> HistoryPurgeEvent + Send + 'static,
    ) {
        let Some(path) = self.repo_path.clone() else { return; };
        let (sender, receiver) = mpsc::channel();
        std::thread::spawn(move || { let _ = sender.send(work(path)); });
        self.history_purge_receiver = Some(receiver);
        self.history_purge_busy = true;
    }

    fn open_history_purge(&mut self) {
        self.history_purge_open = true;
        self.error = None;
        self.notice = None;
        self.history_purge_path.clear();
        self.history_purge_filter.clear();
        self.history_purge_preview = None;
        self.history_purge_paths.clear();
        self.history_purge_paths_loaded = false;
        self.history_purge_browsing = false;
        self.history_purge_backups.clear();
        self.start_history_purge_job(|path| HistoryPurgeEvent::Backups(history_purge::history_purge_backups(&path)));
    }

    fn measure_history_purge(&mut self) {
        let path = self.history_purge_path.trim().to_owned();
        if path.is_empty() || self.history_purge_busy { return; }
        self.history_purge_preview = None;
        self.start_history_purge_job(move |repo| {
            HistoryPurgeEvent::Preview(history_purge::history_purge_preview(&repo, &[path]))
        });
    }

    fn load_history_purge_paths(&mut self) {
        if self.history_purge_busy || self.history_purge_paths_loaded { return; }
        self.start_history_purge_job(|path| HistoryPurgeEvent::Paths(Ok(history_purge::history_paths(&path, 400))));
    }

    fn confirm_history_purge_action(&mut self) {
        let Some(action) = self.pending_history_purge_action.take() else { return; };
        if self.repo_path.is_none() { return; }
        self.history_purge_mutating = true;
        self.start_history_purge_job(move |repo| match action {
            HistoryPurgeAction::Rewrite { path, preview } => HistoryPurgeEvent::Purged(
                history_purge::history_purge(&repo, &[path], &preview),
            ),
            HistoryPurgeAction::Restore(prefix) => HistoryPurgeEvent::Restored(
                history_purge::history_purge_restore(&repo, &prefix),
            ),
            HistoryPurgeAction::Drop(prefix) => HistoryPurgeEvent::Dropped(
                history_purge::history_purge_drop_backup(&repo, &prefix),
            ),
        });
    }

    fn poll_history_purge(&mut self) {
        let event = self.history_purge_receiver.as_ref().and_then(|receiver| match receiver.try_recv() {
            Ok(event) => Some(event),
            Err(TryRecvError::Empty) => None,
            Err(TryRecvError::Disconnected) => Some(HistoryPurgeEvent::Preview(Err("History operation stopped unexpectedly".into()))),
        });
        let Some(event) = event else { return; };
        self.history_purge_receiver = None;
        self.history_purge_busy = false;
        self.history_purge_mutating = false;
        match event {
            HistoryPurgeEvent::Paths(result) => match result {
                Ok(paths) => { self.history_purge_paths = paths; self.history_purge_paths_loaded = true; }
                Err(error) => self.error = Some(history_purge_error(&self.preferences.language, error)),
            },
            HistoryPurgeEvent::Preview(result) => match result {
                Ok(preview) => self.history_purge_preview = Some(preview),
                Err(error) => self.error = Some(history_purge_error(&self.preferences.language, error)),
            },
            HistoryPurgeEvent::Backups(result) => match result {
                Ok(backups) => self.history_purge_backups = backups,
                Err(error) => self.error = Some(history_purge_error(&self.preferences.language, error)),
            },
            HistoryPurgeEvent::Purged(result) => match result {
                Ok(history_purge::HistoryPurgeOutcome::PreviewChanged(preview)) => {
                    self.history_purge_preview = Some(preview);
                    self.notice = Some(translate(&self.preferences.language, "purge.previewChanged").to_owned());
                }
                Ok(history_purge::HistoryPurgeOutcome::Applied(result)) => {
                    self.notice = Some(translate_interpolated(
                        &self.preferences.language,
                        "purge.done",
                        &[("refs", result.rewritten.to_string())],
                    ));
                    if !self.history_purge_backups.iter().any(|backup| backup.prefix == result.backup.prefix) {
                        self.history_purge_backups.push(result.backup.clone());
                    }
                    self.history_purge_preview = None;
                    self.refresh();
                    self.load_history_purge_backups();
                }
                Err(error) => {
                    self.error = Some(history_purge_error(&self.preferences.language, error));
                    self.refresh();
                    self.load_history_purge_backups();
                }
            },
            HistoryPurgeEvent::Restored(result) => match result {
                Ok(()) => {
                    self.notice = Some(translate(&self.preferences.language, "purge.restored").to_owned());
                    self.refresh();
                    self.load_history_purge_backups();
                }
                Err(error) => self.error = Some(history_purge_error(&self.preferences.language, error)),
            },
            HistoryPurgeEvent::Dropped(result) => match result {
                Ok(()) => {
                    self.notice = Some(translate(&self.preferences.language, "purge.dropped").to_owned());
                    self.load_history_purge_backups();
                }
                Err(error) => self.error = Some(history_purge_error(&self.preferences.language, error)),
            },
        }
    }

    fn load_history_purge_backups(&mut self) {
        if self.history_purge_busy { return; }
        self.start_history_purge_job(|path| HistoryPurgeEvent::Backups(history_purge::history_purge_backups(&path)));
    }

    fn with_repo<T>(&self, action: impl FnOnce(&mut Repository) -> Result<T, git2::Error>) -> Result<T, String> {
        let path = self.repo_path.as_ref().ok_or("Could not determine repository path")?;
        let mut repo = Repository::discover(path).map_err(|error| error.message().to_owned())?;
        action(&mut repo).map_err(|error| redact_url_credentials(error.message()))
    }

    fn refresh(&mut self) {
        self.refresh_wip_snapshots();
        self.branch = None;
        self.branches.clear();
        self.remote_branches.clear();
        self.worktrees.clear();
        self.submodules.clear();
        self.conflicts.clear();
        self.remotes.clear();
        self.tags.clear();
        self.stashes.clear();
        self.history.clear();
        self.changes.clear();
        self.files.clear();

        let Some(path) = self.repo_path.as_ref() else {
            self.error = Some("Could not determine current directory".into());
            return;
        };

        let mut repo = match Repository::discover(path) {
            Ok(repo) => repo,
            Err(error) => {
                self.error = Some(error.message().to_owned());
                return;
            }
        };
        let common_dir = repo.commondir().to_path_buf();
        if self.rerere_repo_path.as_ref() != Some(&common_dir) {
            self.rerere_replayed.clear();
            self.rerere_repo_path = Some(common_dir.clone());
        }
        if let Ok(config) = repo.config() {
            self.rerere_enabled = config.get_bool("rerere.enabled").unwrap_or(false);
            self.rerere_auto_update = config.get_bool("rerere.autoUpdate").unwrap_or(false);
            self.rerere_per_repo = config.open_level(ConfigLevel::Local)
                .ok()
                .is_some_and(|local| local.get_entry("rerere.enabled").is_ok());
        }
        self.rerere_recorded = std::fs::read_dir(common_dir.join("rr-cache"))
            .map(|entries| entries.filter_map(Result::ok)
                .filter(|entry| !entry.file_name().to_string_lossy().starts_with('.'))
                .count())
            .unwrap_or(0);
        self.merge_in_progress = repo.state() == git2::RepositoryState::Merge;
        self.rebase_in_progress = matches!(
            repo.state(),
            git2::RepositoryState::Rebase
                | git2::RepositoryState::RebaseMerge
                | git2::RepositoryState::RebaseInteractive
        );
        if !self.rebase_in_progress && repo.path().join("gitcito-rebase-tempfiles").exists() {
            self.cleanup_interactive_rebase_tempfiles();
        }
        self.rebase_edit_paused = if self.rebase_in_progress {
            std::fs::read_to_string(repo.path().join("rebase-merge").join("done")).ok()
                .and_then(|done| done.lines().last().map(str::to_owned))
                .is_some_and(|line| line.starts_with("edit "))
        } else { false };
        self.bisect_status = read_bisect_status(&repo, &self.bisect_output);
        if self.rebase_edit_paused && !self.amend_commit && self.commit_message.is_empty() {
            if let Ok(message) = repo.head().and_then(|head| head.peel_to_commit())
                .map(|commit| commit.message().unwrap_or_default().to_owned())
            {
                self.commit_message = message;
                self.amend_commit = true;
            }
        }
        self.cherry_pick_in_progress = repo.state() == git2::RepositoryState::CherryPick;
        self.revert_in_progress = repo.state() == git2::RepositoryState::Revert;
        if self.merge_in_progress || self.rebase_in_progress || self.cherry_pick_in_progress || self.revert_in_progress {
            if let Ok(index) = repo.index() {
                if let Ok(conflicts) = index.conflicts() {
                    self.conflicts = conflicts
                        .filter_map(Result::ok)
                        .filter_map(|conflict| {
                            conflict
                                .our
                                .or(conflict.their)
                                .or(conflict.ancestor)
                                .and_then(|entry| String::from_utf8(entry.path).ok())
                                .map(|path| ConflictFile { path })
                        })
                        .collect();
                }
            }
        }
        if self.conflicts.is_empty() {
            self.rerere_replayed.clear();
        } else if self.rerere_enabled {
            let workdir = repo.workdir().unwrap_or(path);
            self.rerere_replayed.extend(run_rerere(workdir));
        }
        self.repo_path = repo.workdir().map(PathBuf::from).or_else(|| Some(path.clone()));
        if let Some(workdir) = repo.workdir() {
            if let Ok(output) = Command::new("git")
                .arg("-C")
                .arg(workdir)
                .args(["worktree", "list", "--porcelain"])
                .output()
            {
                if output.status.success() {
                    self.worktrees = parse_worktrees(&String::from_utf8_lossy(&output.stdout), workdir);
                }
            }
            if let Ok(output) = Command::new("git").arg("-C").arg(workdir)
                .args(["submodule", "status", "--recursive"]).output() {
                if output.status.success() {
                    self.submodules = parse_submodules(&String::from_utf8_lossy(&output.stdout));
                }
            }
        }
        self.sparse = sparse_checkout_info(&repo).unwrap_or_default();
        self.selected_sparse_dirs = if self.sparse.enabled {
            self.sparse.dirs.iter().cloned().collect()
        } else {
            self.sparse.top_level_dirs.iter().cloned().collect()
        };
        self.lfs = lfs_state(&repo);
        self.hooks = inspect_hooks(&repo).unwrap_or_default();
        if let Ok(config) = repo.config() {
            self.author_name = config.get_string("user.name").unwrap_or_default();
            self.author_email = config.get_string("user.email").unwrap_or_default();
        }
        if let Some(workdir) = repo.workdir() {
            self.signing_enabled = local_git_config(workdir, "commit.gpgsign").ok().flatten()
                .is_some_and(|value| matches!(value.to_ascii_lowercase().as_str(), "true" | "yes" | "on" | "1"));
            self.signing_format = local_git_config(workdir, "gpg.format").ok().flatten()
                .filter(|value| !value.is_empty()).unwrap_or_else(|| "openpgp".into());
            self.signing_key = local_git_config(workdir, "user.signingkey").ok().flatten().unwrap_or_default();
        }
        if let Some(path) = self.repo_path.clone() {
            self.preferences.remember_repository(path);
        }
        let previous_branch = self.branch.clone();
        self.branch = repo.head().ok().and_then(|head| head.shorthand().map(str::to_owned));
        self.branch_upstream = self.branch.as_deref().and_then(|name| {
            repo.find_branch(name, BranchType::Local).ok()?.upstream().ok()?
                .name().ok().flatten().map(str::to_owned)
        });
        self.branches = repo
            .branches(Some(BranchType::Local))
            .map(|branches| {
                branches
                    .filter_map(Result::ok)
                    .filter_map(|(branch, _)| branch.name().ok().flatten().map(str::to_owned))
                    .collect()
            })
            .unwrap_or_default();
        self.remotes = repo
            .remotes()
            .map(|remotes| remotes.iter().flatten().map(str::to_owned).collect())
            .unwrap_or_default();
        if previous_branch != self.branch {
            if let Some(upstream) = self.branch_upstream.as_deref() {
                if let Some(remote) = self.remotes.iter().filter(|remote| {
                    upstream.starts_with(&format!("{remote}/"))
                }).max_by_key(|remote| remote.len()) {
                    self.selected_remote = Some(remote.clone());
                }
            }
        }
        self.tags = repo
            .references_glob("refs/tags/*")
            .map(|references| {
                references
                    .filter_map(Result::ok)
                    .filter_map(|reference| {
                        let name = reference.shorthand()?.to_owned();
                        let target = reference.target()?.to_string();
                        let commit = reference
                            .peel_to_commit()
                            .map(|commit| commit.id().to_string())
                            .unwrap_or_else(|_| target.clone());
                        Some((name, target, commit))
                    })
                    .collect()
            })
            .unwrap_or_default();
        if self.selected_remote.as_ref().is_none_or(|remote| !self.remotes.contains(remote)) {
            self.selected_remote = self
                .remotes
                .iter()
                .find(|remote| remote.as_str() == "origin")
                .or_else(|| self.remotes.first())
                .cloned();
        }
        self.remote_branches = repo
            .branches(Some(BranchType::Remote))
            .map(|branches| {
                branches
                    .filter_map(Result::ok)
                    .filter_map(|(branch, _)| branch.name().ok().flatten().map(str::to_owned))
                    .filter(|name| !name.ends_with("/HEAD"))
                    .collect()
            })
            .unwrap_or_default();
        self.upstream_choice = self.branch_upstream.clone()
            .filter(|upstream| self.remote_branches.contains(upstream))
            .or_else(|| self.remote_branches.first().cloned())
            .unwrap_or_default();
        let _ = repo.stash_foreach(|index, message, oid| {
            self.stashes.push((index, message.to_owned(), *oid));
            true
        });
        if self.selected_stash_oid.is_some_and(|selected| !self.stashes.iter().any(|(_, _, oid)| *oid == selected)) {
            self.selected_stash_oid = None;
            self.stash_file_paths.clear();
            self.selected_stash_file_paths.clear();
            self.stash_file_selection_anchor = None;
            self.selected_stash_preview_path = None;
            self.stash_file_diff_lines.clear();
        }
        let head_reference = repo.head().ok().and_then(|reference| reference.name().map(str::to_owned));
        let mut decorations = HashMap::<git2::Oid, Vec<CommitRef>>::new();
        if let Ok(references) = repo.references() {
            for reference in references.flatten() {
                let raw_name = reference.name().unwrap_or_default().to_owned();
                if let (Ok(commit), Some(name)) = (reference.peel_to_commit(), reference.shorthand()) {
                    let kind = if raw_name.starts_with("refs/heads/") {
                        CommitRefKind::Local
                    } else if raw_name.starts_with("refs/remotes/") {
                        CommitRefKind::Remote
                    } else if raw_name.starts_with("refs/tags/") {
                        CommitRefKind::Tag
                    } else {
                        CommitRefKind::Other
                    };
                    decorations.entry(commit.id()).or_default().push(CommitRef {
                        name: name.to_owned(),
                        kind,
                        current: head_reference.as_deref() == Some(raw_name.as_str()),
                    });
                }
            }
        }
        for references in decorations.values_mut() {
            references.sort_by_key(|reference| {
                match (reference.current, reference.kind) {
                    (true, _) => 0,
                    (false, CommitRefKind::Local) => 1,
                    (false, CommitRefKind::Tag) => 2,
                    (false, CommitRefKind::Remote) => 3,
                    (false, CommitRefKind::Other) => 4,
                }
            });
        }
        let history_limit = self.history_limit;
        let notes = repo.notes(Some(COMMIT_NOTES_REF)).map(|notes| notes.filter_map(Result::ok).map(|(_, commit)| commit).collect::<BTreeSet<_>>()).unwrap_or_default();
        self.history = repo
            .revwalk()
            .and_then(|mut walk| {
                walk.set_sorting(git2::Sort::TOPOLOGICAL | git2::Sort::TIME)?;
                walk.push_head()?;
                Ok(walk
                    .take(history_limit)
                    .filter_map(Result::ok)
                    .filter_map(|id| repo.find_commit(id).ok())
                    .map(|commit| CommitRow {
                        id: commit.id().to_string()[..7].to_owned(),
                        oid: commit.id().to_string(),
                        parents: commit.parent_ids().map(|id| id.to_string()).collect(),
                        refs: decorations.get(&commit.id()).cloned().unwrap_or_default(),
                        summary: commit.summary().unwrap_or("(no message)").to_owned(),
                        author: commit.author().name().unwrap_or("Unknown").to_owned(),
                        timestamp: commit.time().seconds(),
                        has_note: notes.contains(&commit.id()),
                    })
                    .collect())
            })
            .unwrap_or_default();
        let previous_time_machine_commit = self.time_machine_commit.clone();
        self.time_machine_commits = self.history.iter().cloned().rev().collect();
        self.time_machine_index = previous_time_machine_commit
            .and_then(|oid| self.time_machine_commits.iter().position(|commit| commit.oid == oid))
            .unwrap_or_else(|| self.time_machine_index.min(self.time_machine_commits.len().saturating_sub(1)));

        let mut options = StatusOptions::new();
        options.include_untracked(true).recurse_untracked_dirs(true).renames_head_to_index(true);
        let mut files = BTreeSet::new();
        if let Ok(index) = repo.index() {
            for entry in index.iter() {
                if let Ok(path) = String::from_utf8(entry.path) {
                    files.insert(path);
                }
            }
        }
        match repo.statuses(Some(&mut options)) {
            Ok(statuses) => {
                for entry in statuses.iter() {
                    if entry.status().contains(Status::WT_NEW) {
                        if let Some(path) = entry.path() {
                            files.insert(path.to_owned());
                        }
                    }
                }
                self.changes = statuses
                    .iter()
                    .filter_map(|entry| {
                        let path = entry.path()?.to_owned();
                        let status = entry.status();
                        Some(FileChange {
                            path,
                            status: status_label(status).to_owned(),
                            staged: status.intersects(
                                Status::INDEX_NEW
                                    | Status::INDEX_MODIFIED
                                    | Status::INDEX_DELETED
                                    | Status::INDEX_RENAMED
                                    | Status::INDEX_TYPECHANGE,
                            ),
                        })
                    })
                    .collect();
            }
            Err(error) => self.error = Some(error.message().to_owned()),
        }
        self.files = files.into_iter().collect();
        if self.selected_file.is_some() {
            self.refresh_diff();
            self.refresh_preview();
            self.refresh_file_metadata();
        }
        if self.active_view == AppView::TimeMachine && !self.time_machine_commits.is_empty() {
            self.load_time_machine_commit();
        }
    }

    fn open_repository(&mut self) {
        let Some(path) = rfd::FileDialog::new().set_title("Open Git repository").pick_folder() else {
            return;
        };
        self.choose_repository(path);
    }

    fn initialize_repository(&mut self) {
        let Some(path) = rfd::FileDialog::new().set_title("Initialize Git repository in folder").pick_folder() else {
            return;
        };
        let initial_branch = git2::Config::open_default()
            .and_then(|config| config.get_string("init.defaultBranch"))
            .unwrap_or_default();
        let mut options = git2::RepositoryInitOptions::new();
        if !initial_branch.is_empty() { options.initial_head(&initial_branch); }
        match Repository::init_opts(&path, &options) {
            Ok(_) => self.choose_repository(path),
            Err(error) => self.error = Some(redact_url_credentials(error.message())),
        }
    }

    fn pick_clone_destination(&mut self) {
        let Some(parent) = rfd::FileDialog::new().set_title("Choose clone destination").pick_folder() else {
            return;
        };
        let leaf = self
            .clone_url
            .trim_end_matches('/')
            .rsplit(['/', ':'])
            .next()
            .unwrap_or_default()
            .trim_end_matches(".git");
        self.clone_destination = parent.join(leaf).display().to_string();
    }

    fn start_clone(&mut self) {
        let url = self.clone_url.trim().to_owned();
        let destination = PathBuf::from(self.clone_destination.trim());
        if url.is_empty() || self.clone_destination.trim().is_empty() {
            self.error = Some("Enter repository URL and destination".into());
            return;
        }
        if has_embedded_url_credentials(&url) {
            self.error = Some(
                "Remove credentials from URL; use Git credential helper or SSH agent".into(),
            );
            return;
        }
        let mut options = Vec::<String>::new();
        if self.clone_partial { options.push("--filter=blob:none".into()); }
        if self.clone_shallow {
            let Ok(depth) = self.clone_depth.trim().parse::<u32>() else {
                self.error = Some("Clone depth must be a positive number".into());
                return;
            };
            if depth == 0 {
                self.error = Some("Clone depth must be a positive number".into());
                return;
            }
            options.push(format!("--depth={depth}"));
        }
        match self.clone_branch_scope {
            1 => options.push("--single-branch".into()),
            2 if self.clone_shallow => options.push("--no-single-branch".into()),
            _ => {}
        }
        let branch = self.clone_branch.trim().to_owned();
        if !branch.is_empty() {
            options.push("--branch".into());
            options.push(branch);
        }
        if self.clone_submodules { options.push("--recurse-submodules".into()); }
        let clone_url = local_clone_url(&url, self.clone_shallow);
        let (sender, receiver) = mpsc::channel();
        self.clone_receiver = Some(receiver);
        self.clone_progress = Some(("Starting".into(), 0));
        self.error = None;
        std::thread::spawn(move || {
            let mut command = Command::new("git");
            command.arg("clone").arg("--progress");
            for option in &options { command.arg(option); }
            command.arg(&clone_url).arg(&destination)
                .env("GIT_TERMINAL_PROMPT", "0")
                .stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::piped());
            let result = match command.spawn() {
                Ok(mut child) => {
                    let mut stderr = Vec::new();
                    if let Some(pipe) = child.stderr.take() {
                        let mut reader = BufReader::new(pipe);
                        let mut bytes = Vec::new();
                        loop {
                            bytes.clear();
                            match reader.read_until(b'\r', &mut bytes) {
                                Ok(0) => break,
                                Ok(_) => {
                                    stderr.extend_from_slice(&bytes);
                                    let line = String::from_utf8_lossy(&bytes);
                                    if let Some((stage, percent)) = parse_clone_progress(&line) {
                                        let _ = sender.send(CloneEvent::Progress { stage, percent });
                                    }
                                }
                                Err(error) => {
                                    stderr.extend_from_slice(error.to_string().as_bytes());
                                    break;
                                }
                            }
                        }
                    }
                    match child.wait() {
                        Ok(status) if status.success() => Ok(destination),
                        Ok(_) => Err(redact_url_credentials(&String::from_utf8_lossy(&stderr))),
                        Err(error) => Err(format!("Could not wait for Git clone: {error}")),
                    }
                }
                Err(error) => Err(format!("Could not start Git clone: {error}")),
            };
            let _ = sender.send(CloneEvent::Finished(result));
        });
    }

    fn poll_clone(&mut self) {
        let mut finished = None;
        if let Some(receiver) = &self.clone_receiver {
            loop {
                match receiver.try_recv() {
                    Ok(CloneEvent::Progress { stage, percent }) => {
                        self.clone_progress = Some((stage, percent));
                    }
                    Ok(CloneEvent::Finished(result)) => {
                        finished = Some(result);
                        break;
                    }
                    Err(TryRecvError::Empty | TryRecvError::Disconnected) => break,
                }
            }
        }
        if let Some(result) = finished {
            self.clone_receiver = None;
            self.clone_progress = None;
            match result {
                Ok(path) => {
                    self.clone_dialog_open = false;
                    self.choose_repository(path);
                }
                Err(error) => self.error = Some(error),
            }
        }
        let listed = self.clone_branch_receiver.as_ref().and_then(|receiver| match receiver.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Empty | TryRecvError::Disconnected) => None,
        });
        if let Some(result) = listed {
            self.clone_branch_receiver = None;
            self.clone_branch_listing = false;
            match result {
                Ok(branches) => {
                    if !self.clone_branch.is_empty() && !branches.contains(&self.clone_branch) {
                        self.clone_branch.clear();
                    }
                    self.clone_branches = branches;
                    self.error = None;
                }
                Err(error) => self.error = Some(error),
            }
        }
    }

    fn list_clone_branches(&mut self) {
        let url = self.clone_url.trim().to_owned();
        if url.is_empty() {
            self.error = Some("Enter a repository URL first".into());
            return;
        }
        if has_embedded_url_credentials(&url) {
            self.error = Some("Remove credentials from URL; use Git credential helper or SSH agent".into());
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.clone_branch_receiver = Some(receiver);
        self.clone_branch_listing = true;
        std::thread::spawn(move || {
            let result = Command::new("git")
                .args(["ls-remote", "--heads", &url])
                .env("GIT_TERMINAL_PROMPT", "0")
                .stdin(Stdio::null())
                .output()
                .map_err(|error| format!("Could not start Git: {error}"))
                .and_then(|output| {
                    if !output.status.success() {
                        return Err(redact_url_credentials(&String::from_utf8_lossy(&output.stderr)));
                    }
                    let mut branches = String::from_utf8_lossy(&output.stdout).lines()
                        .filter_map(|line| line.split_once('\t').map(|(_, name)| name))
                        .filter_map(|name| name.strip_prefix("refs/heads/"))
                        .map(str::to_owned)
                        .collect::<Vec<_>>();
                    branches.sort();
                    Ok(branches)
                });
            let _ = sender.send(result);
        });
    }

    fn choose_repository(&mut self, path: PathBuf) {
        match Repository::discover(&path) {
            Ok(repo) => {
                let path = repo.workdir().map(PathBuf::from).unwrap_or(path);
                self.preferences.open_repository(path.clone());
                self.activate_repository(path);
            }
            Err(error) => self.error = Some(format!("Not a Git repository: {}", error.message())),
        }
    }

    fn start_repository_scan(&mut self, root: PathBuf, context: &eframe::egui::Context) {
        if self.repository_scan_busy { return; }
        let depth = self.preferences.repository_scan_roots.iter()
            .find(|scan_root| scan_root.path == root)
            .map_or(3, |scan_root| scan_root.depth);
        let (sender, receiver) = mpsc::channel();
        self.repository_scan_receiver = Some(receiver);
        self.repository_scan_origin = Some(root.clone());
        self.repository_scan_results.clear();
        self.repository_scan_busy = true;
        let repaint_context = context.clone();
        std::thread::spawn(move || {
            let found = scan_repository_root(&root, depth);
            let _ = sender.send((root, found));
            repaint_context.request_repaint();
        });
    }

    fn poll_repository_scan(&mut self) {
        let result = self.repository_scan_receiver.as_ref().and_then(|receiver| {
            match receiver.try_recv() {
                Ok(result) => Some(Some(result)),
                Err(mpsc::TryRecvError::Disconnected) => Some(None),
                Err(mpsc::TryRecvError::Empty) => None,
            }
        });
        match result {
            Some(Some((root, found))) => {
                if self.preferences.repository_scan_roots.iter().any(|scan_root| scan_root.path == root) {
                    self.preferences.remember_discovered_repositories(&found);
                    self.repository_scan_origin = Some(root);
                    self.repository_scan_results = found;
                    self.invalidate_repository_summaries();
                } else {
                    self.repository_scan_origin = None;
                    self.repository_scan_results.clear();
                }
                self.repository_scan_busy = false;
                self.repository_scan_receiver = None;
            }
            Some(None) => {
                self.repository_scan_busy = false;
                self.repository_scan_receiver = None;
            }
            None => {}
        }
    }

    fn invalidate_repository_summaries(&mut self) {
        self.repository_summaries_loaded = false;
        self.repository_summary_busy = false;
        self.repository_summary_receiver = None;
    }

    fn start_repository_summary_load(&mut self) {
        if self.repository_summary_busy { return; }
        let mut paths = BTreeSet::new();
        paths.extend(self.preferences.open_repositories.iter().cloned());
        paths.extend(self.preferences.favorite_repositories.iter().cloned());
        paths.extend(self.preferences.recent_repositories.iter().cloned());
        paths.extend(self.preferences.discovered_repositories.iter().cloned());
        for workspace in &self.preferences.workspaces {
            paths.extend(workspace.repositories.iter().cloned());
        }
        let (sender, receiver) = mpsc::channel();
        self.repository_summary_receiver = Some(receiver);
        self.repository_summary_busy = true;
        let include_wip = self.preferences.repository_wip_summary;
        std::thread::spawn(move || {
            let summaries = paths.into_iter().map(|path| {
                let summary = repository_summary(&path, include_wip);
                (path, summary)
            }).collect();
            let _ = sender.send(summaries);
        });
    }

    fn poll_repository_summary_load(&mut self) {
        let result = self.repository_summary_receiver.as_ref().and_then(|receiver| {
            match receiver.try_recv() {
                Ok(result) => Some(Some(result)),
                Err(mpsc::TryRecvError::Disconnected) => Some(None),
                Err(mpsc::TryRecvError::Empty) => None,
            }
        });
        match result {
            Some(Some(summaries)) => {
                self.repository_summaries = summaries;
                self.repository_summaries_loaded = true;
                self.repository_summary_busy = false;
                self.repository_summary_receiver = None;
            }
            Some(None) => {
                self.repository_summaries_loaded = true;
                self.repository_summary_busy = false;
                self.repository_summary_receiver = None;
            }
            None => {}
        }
    }

    fn start_group_sync(&mut self, kind: GroupSyncKind, paths: Vec<PathBuf>) {
        if self.group_sync_busy { return; }
        let mut seen = BTreeSet::new();
        let paths = paths.into_iter().filter(|path| seen.insert(path.clone())).collect::<Vec<_>>();
        let (sender, receiver) = mpsc::channel();
        self.group_sync_receiver = Some(receiver);
        self.group_sync_busy = true;
        self.group_sync_progress = None;
        self.group_sync_errors.clear();
        let pull_mode = self.preferences.repository_pull_mode;
        std::thread::spawn(move || {
            let total = paths.len();
            let mut succeeded = 0;
            let mut failed = 0;
            let mut skipped = 0;
            let mut errors = Vec::new();
            let mut pull_undo = Vec::new();
            for (index, path) in paths.into_iter().enumerate() {
                let _ = sender.send(GroupSyncEvent::Progress {
                    kind, current: index + 1, total, path: path.clone(),
                });
                if !path.is_dir() {
                    skipped += 1;
                    continue;
                }
                if matches!(kind, GroupSyncKind::Pull) {
                    match Command::new("git").arg("-C").arg(&path)
                        .args(["status", "--porcelain", "--untracked-files=all"]).output()
                    {
                        Ok(output) if !output.status.success() => {
                            failed += 1;
                            let error = redact_url_credentials(String::from_utf8_lossy(&output.stderr).trim());
                            errors.push((path.clone(), Some(error)));
                            continue;
                        }
                        Ok(output) if !output.stdout.is_empty() => {
                            failed += 1;
                            errors.push((path.clone(), None));
                            continue;
                        }
                        Err(error) => {
                            failed += 1;
                            errors.push((path.clone(), Some(error.to_string())));
                            continue;
                        }
                        _ => {}
                    }
                }
                let before_pull = if matches!(kind, GroupSyncKind::Pull) {
                    let reference = Command::new("git").arg("-C").arg(&path)
                        .args(["symbolic-ref", "--quiet", "HEAD"]).output().ok()
                        .filter(|output| output.status.success())
                        .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_owned());
                    let old_head = Command::new("git").arg("-C").arg(&path)
                        .args(["rev-parse", "--verify", "HEAD"]).output().ok()
                        .filter(|output| output.status.success())
                        .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_owned());
                    reference.zip(old_head).and_then(|(reference, old_head)| {
                        let branch = reference.strip_prefix("refs/heads/")?.to_owned();
                        Some((reference, branch, old_head))
                    })
                } else { None };
                let mut command = Command::new("git");
                command.arg("-C").arg(&path).env("GIT_TERMINAL_PROMPT", "0");
                match kind {
                    GroupSyncKind::Fetch => { command.args(["fetch", "--all"]); }
                    GroupSyncKind::Pull => match pull_mode {
                        PullMode::Default => { command.args(["pull"]); }
                        PullMode::FfOnly => { command.args(["pull", "--ff-only"]); }
                        PullMode::Rebase => { command.args(["pull", "--rebase"]); }
                    },
                }
                match command.output() {
                    Ok(output) if output.status.success() => {
                        succeeded += 1;
                    }
                    Ok(output) => {
                        failed += 1;
                        let detail = if output.stderr.is_empty() { output.stdout } else { output.stderr };
                        let error = redact_url_credentials(String::from_utf8_lossy(&detail).trim());
                        errors.push((path.clone(), Some(error)));
                    }
                    Err(error) => {
                        failed += 1;
                        errors.push((path.clone(), Some(error.to_string())));
                    }
                }
                if let Some((reference, branch, old_head)) = before_pull {
                    let new_head = Command::new("git").arg("-C").arg(&path)
                        .args(["rev-parse", "--verify", "HEAD"]).output().ok()
                        .filter(|output| output.status.success())
                        .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_owned());
                    if let Some(new_head) = new_head.filter(|new_head| new_head != &old_head) {
                        pull_undo.push(GroupPullUndo { path: path.clone(), reference, branch, old_head, new_head });
                    }
                }
            }
            let _ = sender.send(GroupSyncEvent::Finished { kind, succeeded, failed, skipped, errors, pull_undo });
        });
    }

    fn poll_group_sync(&mut self) {
        loop {
            let event = match self.group_sync_receiver.as_ref().map(|receiver| receiver.try_recv()) {
                Some(Ok(event)) => event,
                Some(Err(mpsc::TryRecvError::Empty)) | None => break,
                Some(Err(mpsc::TryRecvError::Disconnected)) => {
                    self.group_sync_receiver = None;
                    self.group_sync_busy = false;
                    self.group_sync_progress = None;
                    break;
                }
            };
            match event {
                GroupSyncEvent::Progress { kind, current, total, path } => {
                    self.group_sync_progress = Some((kind, current, total, path));
                }
                GroupSyncEvent::Finished { kind, succeeded, failed, skipped, errors, pull_undo } => {
                    let operation = translate(&self.preferences.language, match kind {
                        GroupSyncKind::Fetch => "toolbar.fetch",
                        GroupSyncKind::Pull => "toolbar.pull",
                    }).to_owned();
                    self.notice = Some(translate_interpolated(
                        &self.preferences.language,
                        "repos.groupSyncDone",
                        &[
                            ("operation", operation),
                            ("succeeded", succeeded.to_string()),
                            ("failed", failed.to_string()),
                            ("skipped", skipped.to_string()),
                        ],
                    ));
                    self.group_sync_errors = errors.into_iter().map(|(path, error)| {
                        let error = error.unwrap_or_else(|| translate(&self.preferences.language, "repos.groupSyncDirty").to_owned());
                        (path, error)
                    }).collect();
                    if matches!(kind, GroupSyncKind::Pull) {
                        let label = translate(&self.preferences.language, "toolbar.pull").to_owned();
                        for undo in pull_undo {
                            let parsed = (|| -> Result<UndoEntry, git2::Error> {
                                let old_head = git2::Oid::from_str(&undo.old_head)?;
                                let new_head = git2::Oid::from_str(&undo.new_head)?;
                                let repo = Repository::open(&undo.path)?;
                                let expected_tree = repo.find_commit(new_head)?.tree_id();
                                Ok(UndoEntry {
                                    label: label.clone(),
                                    repo_path: undo.path.clone(),
                                    branch: Some(undo.branch.clone()),
                                    action: UndoAction::MoveRef {
                                        reference: undo.reference,
                                        from: new_head,
                                        to: old_head,
                                        expected_tree,
                                    },
                                })
                            })();
                            if let Ok(entry) = parsed { self.undo_stack.push(entry); }
                        }
                    }
                    self.group_sync_receiver = None;
                    self.group_sync_busy = false;
                    self.group_sync_progress = None;
                    self.invalidate_repository_summaries();
                    if self.repo_path.as_ref().is_some_and(|path| self.preferences.open_repositories.contains(path)) {
                        self.refresh();
                    }
                }
            }
        }
    }

    fn activate_repository(&mut self, path: PathBuf) {
        self.invalidate_repository_summaries();
        self.branch_filter.clear();
        self.issue_filter.clear();
        match Repository::discover(&path) {
            Ok(repo) => {
                self.repo_path = repo.workdir().map(PathBuf::from).or(Some(path));
                if let Some(active) = self.repo_path.clone() {
                    self.preferences.activate_repository(active);
                }
                self.selected_file = None;
                self.diff_lines.clear();
                self.file_blame.clear();
                self.file_history.clear();
                self.selected_commit = None;
                self.commit_diff_lines.clear();
                self.selected_remote = None;
                self.error = None;
                self.notice = Some("Repository opened".into());
                self.refresh();
            }
            Err(error) => self.error = Some(format!("Not a Git repository: {}", error.message())),
        }
    }

    fn close_repository_tab(&mut self, path: PathBuf) {
        self.invalidate_repository_summaries();
        self.preferences.close_repository(&path);
        if self.repo_path.as_ref() == Some(&path) {
            if let Some(next) = self.preferences.active_repository.clone() {
                self.activate_repository(next);
            } else {
                self.repo_path = None;
                self.refresh();
            }
        }
    }

    fn forget_repository(&mut self, path: PathBuf) {
        self.invalidate_repository_summaries();
        let was_active = self.repo_path.as_ref() == Some(&path);
        self.preferences.forget_repository(&path);
        if self.repository_alias_edit_path.as_ref() == Some(&path) {
            self.repository_alias_edit_path = None;
            self.repository_alias_edit_value.clear();
        }
        if was_active {
            if let Some(next) = self.preferences.active_repository.clone() {
                self.activate_repository(next);
            } else {
                self.repo_path = None;
                self.refresh();
            }
        }
    }

    fn stage(&mut self, path: &str, stage: bool) {
        let path = path.to_owned();
        let result = self.with_repo(|repo| {
            let previous = repo.index()?.write_tree()?;
            set_stage(repo, &path, stage)?;
            let expected = repo.index()?.write_tree()?;
            Ok((previous, expected))
        });
        match result {
            Ok((previous, expected)) => {
                self.undo_stack.push(UndoEntry {
                    label: format!("{} {path}", if stage { "stage" } else { "unstage" }),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: self.branch.clone(),
                    action: UndoAction::IndexTree { previous, expected },
                });
                self.error = None;
                self.notice = Some("Index updated".into());
            }
            Err(error) => self.error = Some(error),
        }
        self.refresh();
    }

    fn stage_all(&mut self, stage: bool) {
        let result = self.with_repo(|repo| {
            let previous = repo.index()?.write_tree()?;
            if stage {
                let mut index = repo.index()?;
                index.add_all(["*"], IndexAddOption::DEFAULT, None)?;
                index.write()?;
            } else if let Ok(head) = repo.revparse_single("HEAD") {
                repo.reset(&head, ResetType::Mixed, None)?;
            } else {
                let mut index = repo.index()?;
                index.clear()?;
                index.write()?;
            }
            let expected = repo.index()?.write_tree()?;
            Ok((previous, expected))
        });
        match result {
            Ok((previous, expected)) => {
                self.undo_stack.push(UndoEntry {
                    label: if stage { "stage all" } else { "unstage all" }.to_owned(),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: self.branch.clone(),
                    action: UndoAction::IndexTree { previous, expected },
                });
                self.notice = Some("Index updated".into());
                self.error = None;
            }
            Err(error) => self.error = Some(error),
        }
        self.refresh();
    }

    fn request_discard(&mut self, path: &str) {
        self.pending_discard = vec![path.to_owned()];
    }

    fn confirm_discard(&mut self) {
        let paths = std::mem::take(&mut self.pending_discard);
        let guard_warning = if self.preferences.snapshot_guard {
            self.repo_path.as_ref().and_then(|path| write_wip_snapshot(path, 'g').err())
        } else { None };
        let result = self.with_repo(|repo| {
            for path in &paths {
                let relative = Path::new(path);
                if relative.as_os_str().is_empty()
                    || relative.is_absolute()
                    || relative.components().any(|component| !matches!(component, Component::Normal(_)))
                {
                    return Err(git2::Error::from_str("Unsafe repository path"));
                }
            }

            let workdir = repo.workdir().ok_or_else(|| git2::Error::from_str("Bare repositories have no working tree"))?;
            let root = workdir
                .canonicalize()
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            for path in &paths {
                let relative = Path::new(path);
                let mut ancestor = workdir.join(relative).parent().map(Path::to_path_buf)
                    .ok_or_else(|| git2::Error::from_str("Invalid repository path"))?;
                while !ancestor.exists() {
                    if !ancestor.pop() {
                        return Err(git2::Error::from_str("Invalid repository path"));
                    }
                }
                let resolved_ancestor = ancestor
                    .canonicalize()
                    .map_err(|error| git2::Error::from_str(&error.to_string()))?;
                if !resolved_ancestor.starts_with(&root) {
                    return Err(git2::Error::from_str("Path resolves outside repository"));
                }
                let head = repo.head().ok().and_then(|head| head.peel_to_commit().ok());
                let tracked_at_head = head
                    .as_ref()
                    .and_then(|commit| commit.tree().ok())
                    .and_then(|tree| tree.get_path(relative).ok())
                    .is_some();
                if let Some(head) = head.filter(|_| tracked_at_head) {
                    let mut checkout = CheckoutBuilder::new();
                    checkout.force().path(relative);
                    repo.checkout_tree(head.as_object(), Some(&mut checkout))?;
                    let head_object = head.as_object();
                    repo.reset_default(Some(&head_object), [relative])?;
                } else {
                    let full_path = workdir.join(relative);
                    if std::fs::symlink_metadata(&full_path).is_ok() {
                        std::fs::remove_file(&full_path)
                            .map_err(|error| git2::Error::from_str(&error.to_string()))?;
                    }
                    let mut index = repo.index()?;
                    index.remove_path(relative)?;
                    index.write()?;
                }
            }
            Ok(())
        });
        self.record_result(result, "Changes discarded", "Changes discarded");
        if let Some(warning) = guard_warning.filter(|_| self.error.is_none()) {
            self.notice = Some(format!("Changes discarded; recovery snapshot failed: {warning}"));
        }
        self.refresh();
    }

    fn select_file(&mut self, path: &str) {
        self.selected_file = Some(path.to_owned());
        self.file_reveal_line = None;
        self.file_detail_section = FileDetailSection::Preview;
        self.split_diff_old_offset = eframe::egui::Vec2::ZERO;
        self.split_diff_new_offset = eframe::egui::Vec2::ZERO;
        self.markdown_preview = Path::new(path).extension().is_some_and(|extension| {
            extension.eq_ignore_ascii_case("md") || extension.eq_ignore_ascii_case("markdown")
        });
        self.refresh_diff();
        self.refresh_preview();
        self.refresh_file_metadata();
    }

    fn search_file_contents(&mut self, context: &eframe::egui::Context) {
        let query = self.file_search.trim().to_owned();
        let Some(root) = self.repo_path.clone() else { return; };
        if query.is_empty() { return; }
        let pattern = if self.file_search_regex { query.clone() } else { regex::escape(&query) };
        let pattern = if self.file_search_whole_word {
            format!(r"\b(?:{pattern})\b")
        } else {
            pattern
        };
        let expression = match RegexBuilder::new(&pattern)
            .case_insensitive(!self.file_search_case_sensitive)
            .build()
        {
            Ok(expression) => expression,
            Err(error) => {
                self.file_search_error = Some(error.to_string());
                self.file_content_search_completed = false;
                self.file_content_hits.clear();
                return;
            }
        };
        self.cancel_file_content_search();
        self.file_search_error = None;
        let paths = self.files.clone();
        let (sender, receiver) = mpsc::channel();
        let cancel = Arc::new(AtomicBool::new(false));
        self.file_content_search_cancel = Some(cancel.clone());
        self.file_content_search_receiver = Some(receiver);
        self.file_content_searching = true;
        self.file_content_search_completed = false;
        self.file_content_hits.clear();
        let repaint_context = context.clone();
        std::thread::spawn(move || {
            let Ok(root) = root.canonicalize() else {
                let _ = sender.send((query, Vec::new()));
                repaint_context.request_repaint();
                return;
            };
            let mut hits = Vec::new();
            let mut bytes_scanned = 0_u64;
            for path in paths.into_iter().take(20_000) {
                if cancel.load(Ordering::Relaxed) { break; }
                if is_secret_file(&path) { continue; }
                let relative = Path::new(&path);
                if relative.is_absolute() || relative.components().any(|component| {
                    !matches!(component, Component::Normal(_))
                }) {
                    continue;
                }
                let full_path = root.join(relative);
                let Ok(canonical) = full_path.canonicalize() else { continue; };
                if !canonical.starts_with(&root) { continue; }
                let Ok(metadata) = std::fs::metadata(&canonical) else { continue; };
                if !metadata.is_file() || metadata.len() > 1_000_000 { continue; }
                bytes_scanned = bytes_scanned.saturating_add(metadata.len());
                if bytes_scanned > 128 * 1024 * 1024 { break; }
                let Ok(bytes) = std::fs::read(canonical) else { continue; };
                if bytes.contains(&0) { continue; }
                let Ok(contents) = String::from_utf8(bytes) else { continue; };
                for (line_index, line) in contents.lines().enumerate() {
                    if expression.is_match(line) {
                        hits.push(FileContentHit {
                            path: path.clone(),
                            line: line_index + 1,
                        });
                        if hits.len() == 500 { break; }
                    }
                }
                if hits.len() == 500 { break; }
            }
            let _ = sender.send((query, hits));
            repaint_context.request_repaint();
        });
    }

    fn search_history_text(&mut self, context: &eframe::egui::Context) {
        let query = self.file_search.trim().to_owned();
        let Some(root) = self.repo_path.clone() else { return; };
        if query.is_empty() { return; }
        self.cancel_history_search();
        self.file_search_error = None;
        self.history_searching = true;
        self.history_search_completed = false;
        self.history_search_hits.clear();
        let (sender, receiver) = mpsc::channel();
        let cancel = Arc::new(AtomicBool::new(false));
        self.history_search_cancel = Some(cancel.clone());
        self.history_search_receiver = Some(receiver);
        let repaint_context = context.clone();
        let regex_search = self.file_search_regex;
        std::thread::spawn(move || {
            let mut command = Command::new("git");
            command.arg("-C").arg(root).args([
                "log", "--all", "--max-count=500", "--format=%H%x1f%s",
            ]);
            if regex_search {
                command.arg("-E").arg(format!("-G{query}"));
            } else {
                command.arg(format!("-S{query}"));
            }
            let result = command.output().map_err(|error| error.to_string()).and_then(|output| {
                if !output.status.success() {
                    return Err(String::from_utf8_lossy(&output.stderr).trim().to_owned());
                }
                Ok(String::from_utf8_lossy(&output.stdout).lines().filter_map(|line| {
                    let (oid, subject) = line.split_once('\u{1f}')?;
                    Some(HistorySearchHit { oid: oid.to_owned(), subject: subject.to_owned() })
                }).collect())
            });
            if !cancel.load(Ordering::Relaxed) {
                let _ = sender.send((query, result));
                repaint_context.request_repaint();
            }
        });
    }

    fn cancel_history_search(&mut self) {
        if let Some(cancel) = self.history_search_cancel.take() {
            cancel.store(true, Ordering::Relaxed);
        }
        self.history_search_receiver = None;
        self.history_searching = false;
    }

    fn poll_history_search(&mut self) {
        let result = self.history_search_receiver.as_ref().and_then(|receiver| {
            match receiver.try_recv() {
                Ok(result) => Some(Some(result)),
                Err(mpsc::TryRecvError::Disconnected) => Some(None),
                Err(mpsc::TryRecvError::Empty) => None,
            }
        });
        match result {
            Some(Some((query, result))) => {
                self.history_searching = false;
                self.history_search_completed = true;
                self.history_search_receiver = None;
                self.history_search_cancel = None;
                if query == self.file_search.trim() {
                    match result {
                        Ok(hits) => self.history_search_hits = hits,
                        Err(error) => self.file_search_error = Some(error),
                    }
                }
            }
            Some(None) => {
                self.history_searching = false;
                self.history_search_completed = true;
                self.history_search_receiver = None;
                self.history_search_cancel = None;
            }
            None => {}
        }
    }

    fn cancel_file_content_search(&mut self) {
        if let Some(cancel) = self.file_content_search_cancel.take() {
            cancel.store(true, Ordering::Relaxed);
        }
        self.file_content_search_receiver = None;
        self.file_content_searching = false;
    }

    fn poll_file_content_search(&mut self) {
        let result = self.file_content_search_receiver.as_ref().and_then(|receiver| {
            match receiver.try_recv() {
                Ok(result) => Some(Some(result)),
                Err(mpsc::TryRecvError::Disconnected) => Some(None),
                Err(mpsc::TryRecvError::Empty) => None,
            }
        });
        match result {
            Some(Some((query, hits))) => {
                self.file_content_searching = false;
                self.file_content_search_completed = true;
                self.file_content_search_receiver = None;
                self.file_content_search_cancel = None;
                if query == self.file_search.trim() {
                    self.file_content_hits = hits;
                }
            }
            Some(None) => {
                self.file_content_searching = false;
                self.file_content_search_completed = true;
                self.file_content_search_receiver = None;
                self.file_content_search_cancel = None;
            }
            None => {}
        }
    }

    fn refresh_file_metadata(&mut self) {
        self.file_blame.clear();
        self.file_history.clear();
        let Some(path) = self.selected_file.clone() else {
            return;
        };
        if is_secret_file(&path) {
            return;
        }
        let result = self.with_repo(|repo| {
            let relative = Path::new(&path);
            let blame = repo.blame_file(relative, None).ok();
            let blame_rows = blame
                .as_ref()
                .map(|blame| {
                    blame
                        .iter()
                        .map(|hunk| BlameRow {
                            first_line: hunk.final_start_line(),
                            last_line: hunk.final_start_line() + hunk.lines_in_hunk().saturating_sub(1),
                            commit_id: hunk.final_commit_id().to_string()[..7].to_owned(),
                            author: hunk.final_signature().name().unwrap_or("Unknown").to_owned(),
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();

            let workdir = repo
                .workdir()
                .ok_or_else(|| git2::Error::from_str("Bare repositories have no working tree"))?;
            let output = Command::new("git")
                .arg("-C")
                .arg(workdir)
                .arg("--literal-pathspecs")
                .arg("log")
                .arg("--follow")
                .arg("--format=%H%x00%an%x00%s%x00")
                .arg("-n")
                .arg("200")
                .arg("--")
                .arg(relative)
                .output()
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            if !output.status.success() {
                return Err(git2::Error::from_str("Could not read file history"));
            }
            let history_output = String::from_utf8_lossy(&output.stdout);
            let mut fields = history_output.split('\0');
            let mut history = Vec::new();
            while let (Some(oid), Some(author), Some(summary)) =
                (fields.next(), fields.next(), fields.next())
            {
                let oid = oid.trim();
                if oid.is_empty() {
                    continue;
                }
                history.push(FileHistoryRow {
                    commit_id: oid.to_owned(),
                    summary: summary.trim_matches(['\n', '\r']).to_owned(),
                    author: author.to_owned(),
                });
            }
            Ok((blame_rows, history))
        });
        match result {
            Ok((blame, history)) => {
                self.file_blame = blame;
                self.file_history = history;
            }
            Err(error) => self.error = Some(error),
        }
    }

    fn refresh_preview(&mut self) {
        self.file_preview.clear();
        self.file_image_preview = None;
        self.file_image_head = None;
        self.file_image_texture = None;
        self.file_image_head_texture = None;
        let Some(path) = self.selected_file.clone() else {
            return;
        };
        if is_secret_file(&path) {
            self.file_preview = "Secret-looking file content hidden".to_owned();
            return;
        }
        let image_file = is_supported_image_path(&path);
        let file_has_changes = self.changes.iter().any(|change| change.path == path);
        let result = self.with_repo(|repo| {
            let relative = Path::new(&path);
            if relative.is_absolute()
                || relative.as_os_str().is_empty()
                || relative.components().any(|component| !matches!(component, Component::Normal(_)))
            {
                return Err(git2::Error::from_str("Unsafe repository path"));
            }
            let workdir = repo
                .workdir()
                .ok_or_else(|| git2::Error::from_str("Bare repositories have no working tree"))?;
            let root = workdir
                .canonicalize()
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            let full_path = workdir.join(relative);
            let canonical = full_path
                .canonicalize()
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            if !canonical.starts_with(&root) {
                return Err(git2::Error::from_str("Path resolves outside repository"));
            }
            let metadata = std::fs::metadata(&canonical)
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            if metadata.len() > 1_000_000 {
                return Ok(FilePreviewContent::Text("File preview limited to 1 MB".to_owned()));
            }
            let bytes = std::fs::read(canonical)
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            if image_file {
                let head = if file_has_changes {
                    repo.head().ok()
                        .and_then(|head| head.peel_to_tree().ok())
                        .and_then(|tree| tree.get_path(relative).ok())
                        .filter(|entry| entry.filemode() != 0o120000)
                        .and_then(|entry| repo.find_blob(entry.id()).ok())
                        .filter(|blob| blob.size() <= 1_000_000)
                        .map(|blob| blob.content().to_vec())
                } else {
                    None
                };
                return Ok(FilePreviewContent::Image { working: bytes, head });
            }
            if bytes.contains(&0) {
                return Ok(FilePreviewContent::Text("Binary file preview unavailable".to_owned()));
            }
            String::from_utf8(bytes)
                .map_err(|_| git2::Error::from_str("File is not valid UTF-8"))
                .map(FilePreviewContent::Text)
        });
        match result {
            Ok(FilePreviewContent::Text(contents)) => self.file_preview = contents,
            Ok(FilePreviewContent::Image { working, head }) => {
                self.file_image_preview = Some((path, working));
                self.file_image_head = head;
            }
            Err(error) => self.file_preview = error,
        }
    }

    fn refresh_diff(&mut self) {
        self.diff_lines.clear();
        self.unstaged_hunks.clear();
        let Some(path) = self.selected_file.clone() else {
            return;
        };
        if is_secret_file(&path) {
            self.diff_lines.push(format!("Secret-looking file; contents hidden: {path}"));
            return;
        }
        let ignore_whitespace = self.ignore_diff_whitespace;
        let result = self.with_repo(|repo| {
            let mut output = Vec::new();
            let mut unstaged_output = Vec::new();
            let pathspec = [std::path::Path::new(&path)];
            if let Ok(head) = repo.head().and_then(|head| head.peel_to_tree()) {
                let mut staged_options = DiffOptions::new();
                staged_options.pathspec(&path);
                staged_options.ignore_whitespace_change(ignore_whitespace);
                let staged = repo.diff_tree_to_index(Some(&head), None, Some(&mut staged_options))?;
                staged.print(DiffFormat::Patch, |_delta, _hunk, line| {
                    output.extend_from_slice(line.content());
                    true
                })?;
            }
            let mut worktree_options = DiffOptions::new();
            worktree_options.pathspec(pathspec[0]).include_untracked(true);
            worktree_options.ignore_whitespace_change(ignore_whitespace);
            let worktree = repo.diff_index_to_workdir(None, Some(&mut worktree_options))?;
            worktree.print(DiffFormat::Patch, |_delta, _hunk, line| {
                output.extend_from_slice(line.content());
                unstaged_output.extend_from_slice(line.content());
                true
            })?;
            Ok((
                String::from_utf8_lossy(&output).lines().map(str::to_owned).collect::<Vec<_>>(),
                parse_patch_hunks(&unstaged_output),
            ))
        });
        match result {
            Ok((lines, hunks)) => {
                self.diff_lines = lines;
                self.unstaged_hunks = hunks;
            }
            Err(error) => self.error = Some(error),
        }
    }

    fn stage_hunk(&mut self, patch: Vec<u8>) {
        let result = self.with_repo(|repo| {
            let previous = repo.index()?.write_tree()?;
            let diff = git2::Diff::from_buffer(&patch)?;
            repo.apply(&diff, ApplyLocation::Index, None)?;
            let mut index = repo.index()?;
            index.write()?;
            let expected = index.write_tree()?;
            Ok((previous, expected))
        });
        match result {
            Ok((previous, expected)) => {
                self.undo_stack.push(UndoEntry {
                    label: "stage hunk".into(),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: self.branch.clone(),
                    action: UndoAction::IndexTree { previous, expected },
                });
                self.error = None;
                self.notice = Some("Hunk staged".into());
                self.selected_hunk_lines.clear();
                self.refresh();
            }
            Err(error) => self.error = Some(error),
        }
    }

    fn stage_selected_lines(&mut self, hunk_index: usize) {
        let Some(patch) = self.unstaged_hunks.get(hunk_index) else { return };
        let selected = self.selected_hunk_lines.iter()
            .filter_map(|(hunk, line)| (*hunk == hunk_index).then_some(*line))
            .collect::<BTreeSet<_>>();
        let Some(patch) = build_line_patch(patch, &selected) else {
            self.error = Some("Select one or more added or removed lines".into());
            return;
        };
        self.stage_hunk(patch);
    }

    fn select_commit(&mut self, oid: &str) {
        self.selected_commit = Some(oid.to_owned());
        self.selected_commit_message.clear();
        let oid = oid.to_owned();
        let result = self.with_repo(|repo| {
            let commit = repo.find_commit(git2::Oid::from_str(&oid)?)?;
            let commit_tree = commit.tree()?;
            let parent_tree = commit.parent(0).ok().map(|parent| parent.tree()).transpose()?;
            let diff = repo.diff_tree_to_tree(parent_tree.as_ref(), Some(&commit_tree), None)?;
            Ok((patch_lines(diff)?, read_commit_note(repo, commit.id())?.unwrap_or_default(),
                commit.message().unwrap_or_default().to_owned()))
        });
        match result {
            Ok((lines, note, message)) => {
                self.commit_diff_lines = lines;
                self.commit_note = note;
                self.selected_commit_message = message;
            }
            Err(error) => self.error = Some(error),
        }
    }

    fn open_time_machine(&mut self) {
        if self.time_machine_commits.is_empty() { self.refresh(); }
        if !self.time_machine_commits.is_empty() {
            self.time_machine_index = self.time_machine_commits.len() - 1;
            self.time_machine_folder.clear();
            self.load_time_machine_commit();
        }
        self.active_view = AppView::TimeMachine;
    }

    fn load_time_machine_commit(&mut self) {
        let Some(commit) = self.time_machine_commits.get(self.time_machine_index).cloned() else {
            self.time_machine_commit = None;
            self.time_machine_files.clear();
            self.time_machine_touched.clear();
            return;
        };
        let result = self.with_repo(|repo| {
            let commit_object = repo.find_commit(git2::Oid::from_str(&commit.oid)?)?;
            let tree = commit_object.tree()?;
            let mut files = Vec::new();
            tree.walk(git2::TreeWalkMode::PreOrder, |root, entry| {
                if entry.kind() != Some(git2::ObjectType::Tree) {
                    if let Some(name) = entry.name() { files.push(format!("{root}{name}")); }
                }
                git2::TreeWalkResult::Ok
            })?;
            let parent_tree = commit_object.parent(0).ok().map(|parent| parent.tree()).transpose()?;
            let diff = repo.diff_tree_to_tree(parent_tree.as_ref(), Some(&tree), None)?;
            let mut touched = BTreeSet::new();
            for delta in diff.deltas() {
                if let Some(path) = delta.new_file().path().or_else(|| delta.old_file().path()) {
                    if let Some(path) = path.to_str() { touched.insert(path.to_owned()); }
                }
            }
            Ok((files, touched))
        });
        match result {
            Ok((files, touched)) => {
                self.time_machine_commit = Some(commit.oid);
                self.time_machine_files = files;
                self.time_machine_touched = touched;
                if !self.time_machine_folder.is_empty()
                    && !self.time_machine_files.iter().any(|path| path.starts_with(&format!("{}/", self.time_machine_folder)))
                {
                    self.time_machine_folder.clear();
                }
                if self.time_machine_file.as_ref().is_some_and(|path| self.time_machine_files.contains(path)) {
                    self.preview_time_machine_file();
                } else {
                    self.time_machine_preview.clear();
                }
            }
            Err(error) => { self.error = Some(error); self.time_machine_files.clear(); }
        }
    }

    fn preview_time_machine_file(&mut self) {
        self.time_machine_preview.clear();
        let (Some(oid), Some(path)) = (self.time_machine_commit.clone(), self.time_machine_file.clone()) else { return; };
        if is_secret_file(&path) {
            self.time_machine_preview = "Secret-looking file content hidden".into();
            return;
        }
        let result = self.with_repo(|repo| {
            let commit = repo.find_commit(git2::Oid::from_str(&oid)?)?;
            let entry = commit.tree()?.get_path(Path::new(&path))?;
            if entry.kind() != Some(git2::ObjectType::Blob) {
                return Ok("This entry is not a text file".to_owned());
            }
            let (size, kind) = repo.odb()?.read_header(entry.id())?;
            if kind != git2::ObjectType::Blob { return Ok("This entry is not a text file".to_owned()); }
            if size > 1_000_000 { return Ok("File preview limited to 1 MB".to_owned()); }
            let blob = repo.find_blob(entry.id())?;
            let bytes = blob.content();
            if bytes.contains(&0) { return Ok("Binary file preview unavailable".to_owned()); }
            String::from_utf8(bytes.to_vec()).map_err(|_| git2::Error::from_str("File is not valid UTF-8"))
        });
        self.time_machine_preview = result.unwrap_or_else(|error| error);
    }

    fn save_commit_note(&mut self) {
        let Some(selected) = self.selected_commit.clone() else { return; };
        let text = self.commit_note.trim_end().to_owned();
        let after = (!text.is_empty()).then_some(text);
        let result = self.with_repo(|repo| {
            let oid = git2::Oid::from_str(&selected)?;
            let before = read_commit_note(repo, oid)?;
            if before == after { return Ok(None); }
            write_commit_note(repo, oid, after.as_deref())?;
            Ok(Some((oid, before, after.clone())))
        });
        match result {
            Ok(Some((commit, before, after))) => {
                self.undo_stack.push(UndoEntry {
                    label: "edit commit note".into(),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: None,
                    action: UndoAction::CommitNote { commit, before, after },
                });
                self.commit_note = self.commit_note.trim_end().to_owned();
                self.notice = Some("Commit note saved".into());
                self.error = None;
                self.refresh();
                self.select_commit(&selected);
            }
            Ok(None) => self.notice = Some("Commit note is unchanged".into()),
            Err(error) => self.error = Some(error),
        }
    }

    fn request_notes_transfer(&mut self, kind: NotesTransferKind) {
        let Some(remote) = self.selected_remote.clone() else {
            self.error = Some("Select a remote first".into());
            return;
        };
        self.pending_notes_transfer = Some((remote, kind));
    }

    fn transfer_notes(&mut self, remote_name: String, kind: NotesTransferKind) {
        let result = self.with_repo(|repo| {
            let config = repo.config()?;
            let mut callbacks = RemoteCallbacks::new();
            callbacks.credentials(move |url, username, allowed| {
                if allowed.contains(git2::CredentialType::SSH_KEY) {
                    Cred::ssh_key_from_agent(username.unwrap_or("git"))
                } else if allowed.contains(git2::CredentialType::USER_PASS_PLAINTEXT) {
                    credential_helper_or_github(&config, url, username, allowed)
                } else if allowed.contains(git2::CredentialType::DEFAULT) {
                    Cred::default()
                } else {
                    Err(git2::Error::from_str("No supported Git credential available"))
                }
            });
            let mut remote = repo.find_remote(&remote_name)?;
            let before = reference_target(repo, COMMIT_NOTES_REF)?;
            let backup_ref = if matches!(kind, NotesTransferKind::Fetch) {
                before.map(|target| {
                    let serial = WIP_SNAPSHOT_SEQUENCE.fetch_add(1, Ordering::Relaxed);
                    let reference = format!("refs/gitcito/undo/notes/{}-{serial}",
                        std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis());
                    repo.reference(&reference, target, false, "Gitcito: preserve notes before fetch").map(|_| reference)
                }).transpose()?
            } else { None };
            match kind {
                NotesTransferKind::Fetch => {
                    let refspec = format!("+{COMMIT_NOTES_REF}:{COMMIT_NOTES_REF}");
                    let mut options = FetchOptions::new();
                    options.remote_callbacks(callbacks);
                    if let Err(error) = remote.fetch(&[&refspec], Some(&mut options), Some("Gitcito: fetch commit notes")) {
                        if let Some(reference) = &backup_ref { let _ = repo.find_reference(reference).and_then(|mut reference| reference.delete()); }
                        return Err(error);
                    }
                }
                NotesTransferKind::Push => {
                    let mut options = PushOptions::new();
                    options.remote_callbacks(callbacks);
                    remote.push(&[COMMIT_NOTES_REF], Some(&mut options))?;
                }
            }
            drop(remote);
            let after = reference_target(repo, COMMIT_NOTES_REF)?;
            Ok((before, after, backup_ref))
        });
        match result {
            Ok((before, after, backup_ref)) => {
                if matches!(kind, NotesTransferKind::Fetch) && before != after {
                    self.undo_stack.push(UndoEntry {
                        label: format!("fetch notes from {remote_name}"),
                        repo_path: self.repo_path.clone().unwrap_or_default(),
                        branch: None,
                        action: UndoAction::NotesRef { before, after, backup_ref },
                    });
                } else if let Some(reference) = backup_ref {
                    let _ = self.with_repo(|repo| match repo.find_reference(&reference) {
                        Ok(mut reference) => reference.delete(),
                        Err(error) if error.code() == git2::ErrorCode::NotFound => Ok(()),
                        Err(error) => Err(error),
                    });
                }
                self.error = None;
                self.notice = Some(match kind {
                    NotesTransferKind::Fetch => format!("Fetched notes from {remote_name}"),
                    NotesTransferKind::Push => format!("Pushed notes to {remote_name}"),
                });
                self.refresh();
                if let Some(commit) = self.selected_commit.clone() { self.select_commit(&commit); }
            }
            Err(error) => self.error = Some(error),
        }
    }


    fn load_reflog(&mut self) {
        let Some(path) = self.repo_path.clone() else { return };
        match Command::new("git").arg("-C").arg(path)
            .args(["reflog", "show", "--all", "--format=%H%x00%gD%x00%gs"]).output() {
            Ok(output) if output.status.success() => {
                self.reflog_rows = String::from_utf8_lossy(&output.stdout).lines().filter_map(|line| {
                    let mut fields = line.splitn(3, '\0');
                    Some(ReflogRow { oid: fields.next()?.to_owned(), selector: fields.next()?.to_owned(), message: fields.next()?.to_owned() })
                }).collect();
                self.reflog_open = true;
                self.error = None;
            }
            Ok(output) => self.error = Some(String::from_utf8_lossy(&output.stderr).into_owned()),
            Err(error) => self.error = Some(error.to_string()),
        }
    }

    fn recover_reflog_branch(&mut self, oid: &str) {
        let name = self.reflog_branch_input.trim().to_owned();
        if name.is_empty() { self.error = Some("Enter a branch name".into()); return; }
        let result = self.with_repo(|repo| {
            let reference = format!("refs/heads/{name}");
            if !git2::Reference::is_valid_name(&reference) {
                return Err(git2::Error::from_str("Invalid branch name"));
            }
            let target = git2::Oid::from_str(oid)?;
            let commit = repo.find_commit(target)?;
            repo.branch(&name, &commit, false)?;
            Ok(target)
        });
        match result {
            Ok(target) => {
                self.undo_stack.push(UndoEntry {
                    label: format!("create recovery branch {name}"),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: self.branch.clone(),
                    action: UndoAction::CreatedBranch { name: name.clone(), target },
                });
                self.reflog_branch_input.clear();
                self.notice = Some(format!("Recovery branch '{name}' created"));
                self.error = None;
                self.refresh();
            }
            Err(error) => self.error = Some(error),
        }
    }

    fn request_file_restore(&mut self) {
        let (Some(path), Some(commit)) = (self.selected_file.clone(), self.selected_commit.clone()) else {
            return;
        };
        self.request_file_restore_at(path, commit);
    }

    fn request_file_restore_at(&mut self, path: String, commit: String) {
        let symlink_target = self.with_repo(|repo| {
            let commit = repo.find_commit(git2::Oid::from_str(&commit)?)?;
            let tree = commit.tree()?;
            let entry = match tree.get_path(Path::new(&path)) {
                Ok(entry) if entry.filemode() == 0o120000 => entry,
                Ok(_) => return Ok(None),
                Err(error) if error.code() == git2::ErrorCode::NotFound => return Ok(None),
                Err(error) => return Err(error),
            };
            let blob = repo.find_blob(entry.id())?;
            Ok(Some(String::from_utf8_lossy(blob.content()).into_owned()))
        });
        match symlink_target {
            Ok(target) => self.pending_file_restore = Some((path, commit, target)),
            Err(error) => self.error = Some(error),
        }
    }

    fn confirm_file_restore(&mut self) {
        let Some((path, oid, _symlink_target)) = self.pending_file_restore.take() else {
            return;
        };
        let guard_warning = if self.preferences.snapshot_guard {
            self.repo_path.as_ref().and_then(|repo_path| write_wip_snapshot(repo_path, 'g').err())
        } else { None };
        let result = self.with_repo(|repo| {
            let before = snapshot_files(repo, std::slice::from_ref(&path))?;
            restore_file_from_commit(repo, &oid, &path)?;
            let after = snapshot_files(repo, std::slice::from_ref(&path))?;
            Ok((before, after))
        });
        match result {
            Ok((before, after)) => {
                self.undo_stack.push(UndoEntry {
                    label: format!("restore {path} from {}", &oid[..oid.len().min(7)]),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: self.branch.clone(),
                    action: UndoAction::Files { before, after },
                });
                self.error = None;
                self.notice = Some(format!("Restored {path} from {}", &oid[..oid.len().min(7)]));
                if let Some(warning) = guard_warning {
                    self.notice = Some(format!("Restored {path}; recovery snapshot failed: {warning}"));
                }
                self.selected_file = Some(path);
            }
            Err(error) => self.error = Some(error),
        }
        self.refresh();
    }

    fn load_older_commits(&mut self) {
        self.history_limit += 100;
        self.refresh();
    }

    fn load_range_tips(&mut self) {
        let Some(path) = self.repo_path.clone() else { return; };
        let new_ref = if self.range_new_revision.trim().is_empty() {
            self.branch.clone().unwrap_or_else(|| "HEAD".into())
        } else { self.range_new_revision.trim().to_owned() };
        let output = Command::new("git").arg("-C").arg(path).args([
            "reflog", "show", "--max-count=20", "--format=%H%x1f%gd%x1f%gs", "--", &new_ref,
        ]).output();
        match output {
            Ok(output) if output.status.success() => {
                self.range_tips = String::from_utf8_lossy(&output.stdout).lines().filter_map(|line| {
                    let mut fields = line.split('\x1f');
                    Some((fields.next()?.to_owned(), fields.next()?.to_owned(), fields.next()?.to_owned()))
                }).collect();
                self.range_error = None;
                if self.range_new_revision.trim().is_empty() { self.range_new_revision = new_ref; }
            }
            Ok(output) => self.range_error = Some(String::from_utf8_lossy(&output.stderr).trim().to_owned()),
            Err(error) => self.range_error = Some(format!("Could not read reflog: {error}")),
        }
    }

    fn compare_ranges(&mut self) {
        let Some(path) = self.repo_path.clone() else { return; };
        let old = self.range_old_revision.trim().to_owned();
        let new = self.range_new_revision.trim().to_owned();
        if old.is_empty() || new.is_empty() {
            self.range_error = Some("Enter both previous and current revisions".into());
            return;
        }
        let resolve = |revision: &str| -> Result<String, String> {
            let spec = format!("{revision}^{{commit}}");
            let output = Command::new("git").arg("-C").arg(&path)
                .args(["rev-parse", "--verify", "--end-of-options", &spec]).output()
                .map_err(|error| error.to_string())?;
            if !output.status.success() { return Err(String::from_utf8_lossy(&output.stderr).trim().to_owned()); }
            Ok(String::from_utf8_lossy(&output.stdout).trim().to_owned())
        };
        let result = (|| -> Result<Vec<RangeDiffEntry>, String> {
            let old_sha = resolve(&old)?;
            let new_sha = resolve(&new)?;
            let explicit_base = if self.range_base.trim().is_empty() { None } else { Some(resolve(self.range_base.trim())?) };
            let base = match explicit_base {
                Some(base) => Some(base),
                None => Command::new("git").arg("-C").arg(&path).args(["merge-base", &old_sha, &new_sha])
                    .output().ok().filter(|output| output.status.success())
                    .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_owned()),
            };
            let mut command = Command::new("git");
            command.arg("-C").arg(&path).args(["range-diff", "--creation-factor=85"]);
            if let Some(base) = base { command.args([base, old_sha, new_sha]); }
            else { command.arg(format!("{old_sha}...{new_sha}")); }
            let output = command.output().map_err(|error| error.to_string())?;
            if !output.status.success() { return Err(String::from_utf8_lossy(&output.stderr).trim().to_owned()); }
            Ok(parse_range_diff(&String::from_utf8_lossy(&output.stdout)))
        })();
        match result {
            Ok(entries) => { self.range_entries = Some(entries); self.range_error = None; }
            Err(error) => { self.range_entries = None; self.range_error = Some(error); }
        }
    }

    fn fetch(&mut self) {
        let Some(name) = self.selected_remote.clone() else {
            self.error = Some("No remote configured".into());
            return;
        };
        let result = self.with_repo(|repo| {
            let config = repo.config()?;
            let mut callbacks = RemoteCallbacks::new();
            callbacks.credentials(move |url, username, allowed| {
                if allowed.contains(git2::CredentialType::SSH_KEY) {
                    Cred::ssh_key_from_agent(username.unwrap_or("git"))
                } else if allowed.contains(git2::CredentialType::USER_PASS_PLAINTEXT) {
                    credential_helper_or_github(&config, url, username, allowed)
                } else if allowed.contains(git2::CredentialType::DEFAULT) {
                    Cred::default()
                } else {
                    Err(git2::Error::from_str("No supported Git credential available"))
                }
            });
            let mut options = FetchOptions::new();
            options.remote_callbacks(callbacks);
            repo.find_remote(&name)?.fetch(&[] as &[&str], Some(&mut options), None)
        });
        self.record_result(result, "Fetch complete", "Fetch complete");
        self.refresh();
    }

    fn pull(&mut self) {
        let Some(branch) = self.branch.clone() else {
            self.error = Some("Select a remote and local branch before pulling".into());
            return;
        };
        let upstream = self.branch_upstream.as_deref().and_then(|upstream| {
            self.remotes.iter().filter_map(|remote| {
                upstream.strip_prefix(&format!("{remote}/"))
                    .map(|branch| (remote.clone(), branch.to_owned()))
            }).max_by_key(|(remote, _)| remote.len())
        });
        let selected_remote = self.selected_remote.clone();
        let target = match (upstream, selected_remote) {
            (Some((upstream_remote, upstream_branch)), Some(selected)) if upstream_remote == selected => {
                Some((selected, upstream_branch))
            }
            (_, Some(selected)) => Some((selected, branch.clone())),
            (Some(upstream), None) => Some(upstream),
            (None, None) => None,
        };
        let Some((remote_name, remote_branch)) = target else {
            self.error = Some("Select a remote and local branch before pulling".into());
            return;
        };
        let clean = self.with_repo(|repo| {
            if repo.state() != git2::RepositoryState::Clean {
                return Err(git2::Error::from_str("Finish or abort current Git operation first"));
            }
            let mut options = StatusOptions::new();
            options.include_untracked(true).recurse_untracked_dirs(true);
            if !repo.statuses(Some(&mut options))?.is_empty() {
                return Err(git2::Error::from_str("Commit, stash, or discard changes before pulling"));
            }
            Ok(())
        });
        if let Err(error) = clean {
            self.error = Some(error);
            return;
        }
        let fetched = self.with_repo(|repo| {
            let config = repo.config()?;
            let mut callbacks = RemoteCallbacks::new();
            callbacks.credentials(move |url, username, allowed| {
                if allowed.contains(git2::CredentialType::SSH_KEY) {
                    Cred::ssh_key_from_agent(username.unwrap_or("git"))
                } else if allowed.contains(git2::CredentialType::USER_PASS_PLAINTEXT) {
                    credential_helper_or_github(&config, url, username, allowed)
                } else if allowed.contains(git2::CredentialType::DEFAULT) {
                    Cred::default()
                } else {
                    Err(git2::Error::from_str("No supported Git credential available"))
                }
            });
            let mut options = FetchOptions::new();
            options.remote_callbacks(callbacks);
            repo.find_remote(&remote_name)?.fetch(&[] as &[&str], Some(&mut options), None)
        });
        if let Err(error) = fetched {
            self.error = Some(error);
            return;
        }
        let source = format!("refs/remotes/{remote_name}/{remote_branch}");
        let exists = self.with_repo(|repo| repo.revparse_single(&source).map(|_| ()));
        if let Err(error) = exists {
            self.error = Some(format!("Fetched, but remote branch '{source}' is unavailable: {error}"));
            self.refresh();
            return;
        }
        self.pending_merge = Some(source);
        self.refresh();
    }

    fn add_remote(&mut self) {
        let name = self.remote_name_input.trim().to_owned();
        let url = self.remote_url_input.trim().to_owned();
        if name.is_empty() || url.is_empty() {
            self.error = Some("Enter a remote name and URL".into());
            return;
        }
        if has_embedded_url_credentials(&url) {
            self.error = Some("Remote URLs cannot contain embedded credentials".into());
            return;
        }
        let result = self.with_repo(|repo| {
            let before = remote_snapshot(repo, &name)?;
            if !before.is_empty() {
                return Err(git2::Error::from_str("Remote name already exists"));
            }
            repo.remote(&name, &url)?;
            let after = remote_snapshot(repo, &name)?;
            Ok((before, after))
        });
        match result {
            Ok((before, after)) => {
                self.remote_name_input.clear();
                self.remote_url_input.clear();
                self.selected_remote = Some(name.clone());
                self.undo_stack.push(UndoEntry {
                    label: "remote addition".to_owned(),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: self.branch.clone(),
                    action: UndoAction::RemoteConfig { name, before, after },
                });
                self.error = None;
                self.notice = Some("Remote added".into());
            }
            Err(error) => self.error = Some(error),
        }
        self.refresh();
    }

    fn edit_remote_url(&mut self) {
        let (Some(name), url, push_url) = (
            self.selected_remote.clone(),
            self.remote_url_edit_input.trim().to_owned(),
            self.remote_push_url_edit_input.trim().to_owned(),
        ) else {
            return;
        };
        if url.is_empty() {
            self.error = Some("Enter the new remote URL".into());
            return;
        }
        if has_embedded_url_credentials(&url) {
            self.error = Some("Remote URLs cannot contain embedded credentials".into());
            return;
        }
        if has_embedded_url_credentials(&push_url) {
            self.error = Some("Remote URLs cannot contain embedded credentials".into());
            return;
        }
        let result = self.with_repo(|repo| {
            let before = remote_snapshot(repo, &name)?;
            repo.remote_set_url(&name, &url)?;
            if let Err(error) = repo.remote_set_pushurl(&name, (!push_url.is_empty()).then_some(push_url.as_str())) {
                restore_remote_snapshot(repo, &name, &before)?;
                return Err(error);
            }
            let after = remote_snapshot(repo, &name)?;
            Ok((before, after))
        });
        match result {
            Ok((before, after)) => {
                self.remote_url_edit_input.clear();
                self.undo_stack.push(UndoEntry {
                    label: "remote URL update".to_owned(),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: self.branch.clone(),
                    action: UndoAction::RemoteConfig { name, before, after },
                });
                self.error = None;
                self.notice = Some("Remote URL updated".into());
            }
            Err(error) => self.error = Some(error),
        }
        self.refresh();
    }

    fn rename_remote(&mut self) {
        let Some(old_name) = self.selected_remote.clone() else { return };
        let new_name = self.remote_rename_input.trim().to_owned();
        if new_name.is_empty() || new_name == old_name { return; }
        let result = self.with_repo(|repo| {
            let before = remote_snapshot(repo, &old_name)?;
            if before.is_empty() {
                return Err(git2::Error::from_str("Remote no longer exists"));
            }
            if !remote_snapshot(repo, &new_name)?.is_empty() {
                return Err(git2::Error::from_str("Remote name already exists"));
            }
            let problems = repo.remote_rename(&old_name, &new_name)?;
            let skipped_refs = problems.iter().flatten().map(str::to_owned).collect::<Vec<_>>();
            let expected = remote_snapshot(repo, &new_name)?;
            Ok((expected, skipped_refs))
        });
        match result {
            Ok((expected, skipped_refs)) => {
                self.selected_remote = Some(new_name.clone());
                self.remote_rename_input = new_name.clone();
                self.remote_editor_loaded = None;
                self.undo_stack.push(UndoEntry {
                    label: translate(&self.preferences.language, "common.rename").to_owned(),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: self.branch.clone(),
                    action: UndoAction::RemoteRename {
                        old_name,
                        new_name,
                        expected,
                    },
                });
                self.error = None;
                self.notice = Some(if skipped_refs.is_empty() {
                    translate(&self.preferences.language, "remote.renamed").to_owned()
                } else {
                    translate_interpolated(
                        &self.preferences.language,
                        "remote.renamePartial",
                        &[("refs", skipped_refs.join(", "))],
                    )
                });
            }
            Err(error) => self.error = Some(error),
        }
        self.refresh();
    }

    fn load_remote_editor(&mut self) {
        if self.remote_editor_loaded == self.selected_remote { return; }
        self.remote_editor_loaded = self.selected_remote.clone();
        self.remote_rename_input = self.selected_remote.clone().unwrap_or_default();
        self.remote_url_edit_input.clear();
        self.remote_push_url_edit_input.clear();
        let Some(name) = self.selected_remote.clone() else { return; };
        if let Ok((url, push_url)) = self.with_repo(|repo| {
            let remote = repo.find_remote(&name)?;
            Ok((remote.url().unwrap_or_default().to_owned(), remote.pushurl().unwrap_or_default().to_owned()))
        }) {
            self.remote_url_edit_input = url;
            self.remote_push_url_edit_input = push_url;
        }
    }

    fn load_protected_branches(&mut self) {
        if self.protected_branches_loaded == self.repo_path { return; }
        self.protected_branches_loaded = self.repo_path.clone();
        self.protected_branches_input = self.with_repo(|repo| {
            let config = repo.config()?.open_level(ConfigLevel::Local)?;
            Ok(config.get_string("gitcito.protectedbranches")
                .unwrap_or_else(|_| "main,master".to_owned()))
        }).unwrap_or_else(|_| "main,master".to_owned());
    }

    fn load_repo_commit_rules(&mut self) {
        if self.repo_commit_rules_loaded == self.repo_path { return; }
        self.repo_commit_rules_loaded = self.repo_path.clone();
        let ((ticket_from_branch, trailers, scopes), ticket_links, file_requirements, hooks_paths, node_versions, git_features) = self.with_repo(|repo| {
            Ok((repo_config_commit_rules(repo), repo_config_ticket_links(repo),
                repo_config_file_requirements(repo),
                (repo_config_required_hooks_path(repo), normalize_hooks_path(repo,
                    repo.config().ok().and_then(|config| config.get_string("core.hookspath").ok()).as_deref())),
                (repo_config_required_node(repo), installed_node_version(repo)),
                repo_config_required_git_features(repo)))
        }).unwrap_or(((false, Vec::new(), Vec::new()), Vec::new(), Vec::new(), (None, None), (None, None), (false, false)));
        self.repo_commit_ticket_from_branch = ticket_from_branch;
        self.repo_commit_trailers = trailers;
        self.repo_commit_scopes = scopes;
        self.repo_ticket_links = ticket_links;
        self.repo_file_requirements = file_requirements;
        self.repo_required_hooks_path = hooks_paths.0;
        self.repo_actual_hooks_path = hooks_paths.1;
        self.repo_required_node = node_versions.0;
        self.repo_actual_node = node_versions.1;
        self.repo_requires_submodules = git_features.0;
        self.repo_requires_lfs = git_features.1;
    }

    fn copy_repo_requirement_file(&mut self, requirement: RepoFileRequirement) {
        let Some(from) = requirement.from.clone() else { return; };
        let result = self.with_repo(|repo| {
            if !safe_repo_relative_path(&requirement.path) || !safe_repo_relative_path(&from) {
                return Err(git2::Error::from_str("Unsafe repository file path"));
            }
            let (_, source) = validate_worktree_path(repo, Path::new(&from))?;
            let (_, destination) = validate_worktree_path(repo, Path::new(&requirement.path))?;
            let source_meta = std::fs::symlink_metadata(&source)
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            if source_meta.file_type().is_symlink() || !source_meta.is_file() {
                return Err(git2::Error::from_str("Requirement source must be a regular file"));
            }
            if source_meta.len() > 100 * 1024 * 1024 {
                return Err(git2::Error::from_str("Requirement copy exceeds the 100 MB undo limit"));
            }
            match std::fs::symlink_metadata(&destination) {
                Ok(_) => return Err(git2::Error::from_str("Target already exists; refusing to overwrite")),
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
                Err(error) => return Err(git2::Error::from_str(&error.to_string())),
            }
            let before = snapshot_files(repo, std::slice::from_ref(&requirement.path))?;
            let mut created = false;
            let copy_result = (|| -> Result<(), std::io::Error> {
                let mut input = std::fs::File::open(&source)?;
                let mut output = std::fs::OpenOptions::new().write(true).create_new(true).open(&destination)?;
                created = true;
                std::io::copy(&mut input, &mut output)?;
                std::fs::set_permissions(&destination, source_meta.permissions())?;
                Ok(())
            })();
            if let Err(error) = copy_result {
                if created { let _ = std::fs::remove_file(&destination); }
                return Err(git2::Error::from_str(&error.to_string()));
            }
            let after = match snapshot_files(repo, std::slice::from_ref(&requirement.path)) {
                Ok(after) => after,
                Err(error) => {
                    let _ = std::fs::remove_file(&destination);
                    return Err(error);
                }
            };
            Ok((before, after))
        });
        match result {
            Ok((before, after)) => {
                self.undo_stack.push(UndoEntry {
                    label: format!("copy {} to {}", from, requirement.path),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: self.branch.clone(),
                    action: UndoAction::Files { before, after },
                });
                self.error = None;
                self.notice = Some(format!("Copied {from} to {}", requirement.path));
                self.refresh();
            }
            Err(error) => self.error = Some(error),
        }
    }

    fn apply_repo_required_hooks_path(&mut self) {
        let Some(expected) = self.repo_required_hooks_path.clone() else { return; };
        if !safe_repo_relative_path(&expected) {
            self.error = Some("Unsafe required hooks path".into());
            return;
        }
        let result = self.repo_path.clone().ok_or_else(|| "No repository is open".to_owned())
            .and_then(|path| {
                let before = local_git_config(&path, "core.hooksPath").map_err(|error| error.message().to_owned())?;
                write_local_git_config(&path, "core.hooksPath", Some(&expected))
                    .map_err(|error| error.message().to_owned())?;
                Ok((path, before, Some(expected.clone())))
            });
        match result {
            Ok((path, before, after)) => {
                self.undo_stack.push(UndoEntry {
                    label: "repository hooks path".into(),
                    repo_path: path,
                    branch: self.branch.clone(),
                    action: UndoAction::GitConfig {
                        changes: vec![("core.hooksPath".into(), before, after)],
                    },
                });
                self.repo_actual_hooks_path = Some(expected);
                self.error = None;
                self.notice = Some("Repository hooks path updated".into());
                self.refresh();
            }
            Err(error) => self.error = Some(error),
        }
    }

    fn prefill_branch_ticket(&mut self) {
        let Some(context) = self.repo_path.clone().zip(self.branch.clone()) else {
            self.commit_ticket_prefill_context = None;
            return;
        };
        if self.commit_ticket_prefill_context.as_ref() == Some(&context) { return; }
        self.commit_ticket_prefill_context = Some(context.clone());
        if !self.repo_commit_ticket_from_branch || !self.commit_message.trim().is_empty() { return; }
        if let Some(ticket) = ticket_from_branch(&context.1) {
            self.commit_message = format!("{ticket}: ");
        }
    }

    fn current_branch_is_protected(&self) -> bool {
        let Some(branch) = self.branch.as_deref() else { return false; };
        let local_matches = self.protected_branches_input.split(',').map(str::trim)
            .filter(|pattern| !pattern.is_empty())
            .any(|pattern| branch_pattern_matches(pattern, branch));
        local_matches || self.with_repo(|repo| Ok(repo_config_protected_branches(repo))).unwrap_or_default()
            .iter().any(|pattern| branch_pattern_matches(pattern, branch))
    }

    fn save_protected_branches(&mut self) {
        let value = self.protected_branches_input.split(',').map(str::trim)
            .filter(|pattern| !pattern.is_empty()).collect::<Vec<_>>().join(",");
        let result = self.with_repo(|repo| {
            let mut config = repo.config()?.open_level(ConfigLevel::Local)?;
            let before = config.get_string("gitcito.protectedbranches").ok();
            config.set_str("gitcito.protectedbranches", &value)?;
            Ok((before, value.clone()))
        });
        match result {
            Ok((before, after)) => {
                self.undo_stack.push(UndoEntry {
                    label: "protected branch settings".into(),
                    repo_path: self.repo_path.clone().unwrap_or_default(),
                    branch: self.branch.clone(),
                    action: UndoAction::GitConfig {
                        changes: vec![("gitcito.protectedbranches".into(), before, Some(after))],
                    },
                });
                self.error = None;
                self.notice = Some("Protected branch settings saved".into());
            }
            Err(error) => self.error = Some(error),
        }
    }

    fn request_remote_delete(&mut self) {
        self.pending_remote_delete = self.selected_remote.clone();
    }

    fn open_remote_website(&mut self) {
        let Some(name) = self.selected_remote.clone().or_else(|| self.remotes.first().cloned()) else {
            self.error = Some("No Git remote configured".into());
            return;
        };
        let remote_url = self.with_repo(|repo| {
            repo.find_remote(&name)?.url().map(str::to_owned)
                .ok_or_else(|| git2::Error::from_str("Remote URL is unavailable"))
        });
        match remote_url.and_then(|remote| remote_web_url(&remote).ok_or_else(|| format!("Cannot open web page for remote: {remote}"))) {
            Ok(url) => match open_web_url(&url) {
                Ok(()) => { self.error = None; self.notice = Some(format!("Opened {url}")); }
                Err(error) => self.error = Some(error),
            },
            Err(error) => self.error = Some(error),
        }
    }

    fn load_pull_requests(&mut self) {
        let Some(repo_path) = self.repo_path.clone() else {
            self.pull_request_error = Some("Open a repository first".into());
            self.pull_requests_open = true;
            return;
        };
        let (sender, receiver) = mpsc::channel();
        self.pull_request_receiver = Some(receiver);
        self.pull_requests_loading = true;
        self.pull_request_error = None;
        self.pull_requests_open = true;
        std::thread::spawn(move || {
            let result = Command::new("gh")
                .args(["pr", "list", "--limit", "25", "--json", "number,title,state,url,headRefName,baseRefName"])
                .current_dir(&repo_path)
                .stdin(Stdio::null())
                .output()
                .map_err(|error| format!("Could not start GitHub CLI (gh): {error}"))
                .and_then(|output| {
                    if !output.status.success() {
                        return Err(redact_url_credentials(&String::from_utf8_lossy(&output.stderr)));
                    }
                    serde_json::from_slice::<Vec<PullRequestRow>>(&output.stdout)
                        .map_err(|error| format!("Could not read GitHub pull requests: {error}"))
                });
            let _ = sender.send(result);
        });
    }

    fn poll_pull_requests(&mut self) {
        let result = self.pull_request_receiver.as_ref().and_then(|receiver| match receiver.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Empty | TryRecvError::Disconnected) => None,
        });
            if let Some(result) = result {
            self.pull_request_receiver = None;
            self.pull_requests_loading = false;
            match result {
                Ok(pull_requests) => {
                    self.pull_requests = pull_requests;
                    self.pull_request_error = None;
                }
                Err(error) => self.pull_request_error = Some(error),
            }
        }
    }

    fn load_issues(&mut self) {
        let Some(repo_path) = self.repo_path.clone() else {
            self.issues_error = Some("Open a repository first".into());
            self.issues_open = true;
            return;
        };
        let (sender, receiver) = mpsc::channel();
        self.issues_receiver = Some(receiver);
        self.issues_loading = true;
        self.issues_error = None;
        self.issues_open = true;
        std::thread::spawn(move || {
            let result = Command::new("gh")
                .args([
                    "issue", "list", "--state", "all", "--limit", "50", "--json",
                    "number,title,state,author,labels,assignees,updatedAt,url",
                ])
                .current_dir(repo_path)
                .stdin(Stdio::null())
                .output()
                .map_err(|error| format!("Could not start GitHub CLI (gh): {error}"))
                .and_then(|output| {
                    if !output.status.success() {
                        return Err(redact_url_credentials(&String::from_utf8_lossy(&output.stderr)));
                    }
                    serde_json::from_slice::<Vec<serde_json::Value>>(&output.stdout)
                        .map_err(|error| format!("Could not read GitHub issues: {error}"))
                });
            let _ = sender.send(result);
        });
    }

    fn poll_issues(&mut self) {
        let result = match self.issues_receiver.as_ref() {
            Some(receiver) => match receiver.try_recv() {
                Ok(result) => Some(result),
                Err(TryRecvError::Empty) => None,
                Err(TryRecvError::Disconnected) => Some(Err("Issue list command stopped unexpectedly".into())),
            },
            None => None,
        };
        let Some(result) = result else { return; };
        self.issues_receiver = None;
        self.issues_loading = false;
        match result {
            Ok(issues) => {
                self.issues = issues;
                self.issues_error = None;
            }
            Err(error) => self.issues_error = Some(error),
        }
    }

    fn load_github_notifications(&mut self, context: &eframe::egui::Context) {
        if self.github_notifications_loading { return; }
        let all = self.github_notifications_show_all;
        let endpoint = format!("notifications?all={all}");
        let (sender, receiver) = mpsc::channel();
        self.github_notifications_receiver = Some(receiver);
        self.github_notifications_loading = true;
        self.github_notifications_error = None;
        self.github_notifications_last_refresh = Some(std::time::Instant::now());
        context.request_repaint_after(std::time::Duration::from_secs(300));
        let repaint_context = context.clone();
        std::thread::spawn(move || {
            let result = (|| {
                let account_output = Command::new("gh")
                    .args(["api", "user", "--jq", ".login"])
                    .stdin(Stdio::null())
                    .output()
                    .map_err(|error| format!("Could not start GitHub CLI (gh): {error}"))?;
                if !account_output.status.success() {
                    return Err(redact_url_credentials(&String::from_utf8_lossy(&account_output.stderr)));
                }
                let account = String::from_utf8_lossy(&account_output.stdout).trim().to_owned();
                if account.is_empty() { return Err("GitHub CLI returned an empty account name".to_owned()); }
                let output = Command::new("gh")
                    .args(["api", "--paginate", "--slurp", &endpoint])
                    .stdin(Stdio::null())
                    .output()
                    .map_err(|error| format!("Could not start GitHub CLI (gh): {error}"))?;
                if !output.status.success() {
                    return Err(redact_url_credentials(&String::from_utf8_lossy(&output.stderr)));
                }
                let pages = serde_json::from_slice::<Vec<Vec<serde_json::Value>>>(&output.stdout)
                    .map_err(|error| format!("Could not read GitHub notifications: {error}"))?;
                Ok((account, pages.into_iter().flatten().collect()))
            })();
            let _ = sender.send(result);
            repaint_context.request_repaint();
        });
    }

    fn poll_github_notifications(&mut self) {
        let result = self.github_notifications_receiver.as_ref().and_then(|receiver| match receiver.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Empty | TryRecvError::Disconnected) => None,
        });
        if let Some(result) = result {
            self.github_notifications_receiver = None;
            self.github_notifications_loading = false;
            match result {
                Ok((account, notifications)) => {
                    if self.github_notifications_account.as_ref().is_some_and(|current| current != &account) {
                        self.github_notification_seen.clear();
                        self.github_notification_poll_primed = false;
                        self.github_notification_selected = None;
                    }
                    self.github_notifications_account = Some(account);
                    let current_seen = notifications.iter().filter_map(|notification| {
                        notification.get("id").and_then(serde_json::Value::as_str)
                            .filter(|id| !id.is_empty()).map(str::to_owned)
                    }).collect::<BTreeSet<_>>();
                    for notification in &notifications {
                        let id = notification.get("id").and_then(serde_json::Value::as_str).unwrap_or_default();
                        if id.is_empty() || self.github_notification_seen.contains(id) {
                            continue;
                        }
                        if self.github_notification_poll_primed
                            && self.preferences.desktop_notifications
                            && matches!(notification.get("reason").and_then(serde_json::Value::as_str), Some("review_requested" | "ci_activity"))
                        {
                            show_github_desktop_notification(&self.preferences.language, notification.clone());
                        }
                    }
                    self.github_notification_seen = current_seen;
                    self.github_notification_poll_primed = true;
                    self.github_notifications = notifications;
                    self.github_notifications_error = None;
                    if self.github_notification_selected.as_ref().is_some_and(|selected| {
                        !self.github_notifications.iter().any(|notification| {
                            notification.get("id").and_then(serde_json::Value::as_str) == Some(selected)
                        })
                    }) {
                        self.github_notification_selected = None;
                    }
                }
                Err(error) => self.github_notifications_error = Some(error),
            }
        }

        let action_result = self.github_notification_action_receiver.as_ref().and_then(|receiver| match receiver.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Empty | TryRecvError::Disconnected) => None,
        });
        if let Some(result) = action_result {
            self.github_notification_action_receiver = None;
            self.github_notification_action_error = None;
            match result {
                Ok(()) => match self.github_notification_action.take() {
                    Some(NativeNotificationAction::MarkThreadRead(id)) => {
                        if self.github_notifications_show_all {
                            if let Some(notification) = self.github_notifications.iter_mut().find(|notification| {
                                notification.get("id").and_then(serde_json::Value::as_str) == Some(&id)
                            }) {
                                notification["unread"] = serde_json::Value::Bool(false);
                            }
                        } else {
                            self.github_notifications.retain(|notification| {
                                notification.get("id").and_then(serde_json::Value::as_str) != Some(id.as_str())
                            });
                            if self.github_notification_selected.as_deref() == Some(id.as_str()) {
                                self.github_notification_selected = None;
                            }
                        }
                    }
                    Some(NativeNotificationAction::MarkAllRead) => {
                        for notification in &mut self.github_notifications {
                            notification["unread"] = serde_json::Value::Bool(false);
                        }
                        if !self.github_notifications_show_all {
                            self.github_notification_selected = None;
                        }
                        self.notice = Some(translate(&self.preferences.language, "notif.markedAll").to_owned());
                    }
                    None => {}
                },
                Err(error) => {
                    self.github_notification_action = None;
                    self.github_notification_action_error = Some(error);
                }
            }
        }
    }

    fn mark_github_notification(
        &mut self,
        action: NativeNotificationAction,
        context: &eframe::egui::Context,
    ) {
        if self.github_notification_action_receiver.is_some() { return; }
        if let NativeNotificationAction::MarkThreadRead(id) = &action
            && (id.is_empty() || !id.chars().all(|character| character.is_ascii_digit()))
        {
            self.github_notification_action_error = Some("Invalid GitHub notification ID".into());
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.github_notification_action_receiver = Some(receiver);
        self.github_notification_action = Some(action.clone());
        self.github_notification_action_error = None;
        let repaint_context = context.clone();
        std::thread::spawn(move || {
            let mut command = Command::new("gh");
            match action {
                NativeNotificationAction::MarkThreadRead(id) => {
                    command.args(["api", "-X", "PATCH"])
                        .arg(format!("notifications/threads/{id}"));
                }
                NativeNotificationAction::MarkAllRead => {
                    command.args(["api", "-X", "PUT", "notifications", "-F", "read=true"]);
                }
            }
            let result = command.stdin(Stdio::null()).output()
                .map_err(|error| format!("Could not start GitHub CLI (gh): {error}"))
                .and_then(|output| {
                    if output.status.success() { Ok(()) }
                    else { Err(redact_url_credentials(&String::from_utf8_lossy(&output.stderr))) }
                });
            let _ = sender.send(result);
            repaint_context.request_repaint();
        });
    }

