    fn submit_issue_action(&mut self, action: NativeIssueAction) {
        if self.issue_action_receiver.is_some() { return; }
        let Some(number) = self.issue_detail_number else { return; };
        let Some(repo_path) = self.repo_path.clone() else { return; };
        let mut args = vec!["issue".to_owned()];
        match &action {
            NativeIssueAction::Close => args.extend(["close".into(), number.to_string()]),
            NativeIssueAction::Reopen => args.extend(["reopen".into(), number.to_string()]),
            NativeIssueAction::Comment(body) => args.extend([
                "comment".into(), number.to_string(), "--body".into(), body.clone(),
            ]),
        }
        let (sender, receiver) = mpsc::channel();
        self.issue_action_receiver = Some(receiver);
        self.issue_action = Some(action);
        self.issue_action_number = Some(number);
        self.issue_action_error = None;
        self.issue_action_notice = None;
        std::thread::spawn(move || {
            let result = Command::new("gh")
                .args(args)
                .current_dir(repo_path)
                .stdin(Stdio::null())
                .output()
                .map_err(|error| format!("Could not start GitHub CLI (gh): {error}"))
                .and_then(|output| {
                    if output.status.success() {
                        Ok(())
                    } else {
                        Err(redact_url_credentials(&String::from_utf8_lossy(&output.stderr)))
                    }
                });
            let _ = sender.send(result);
        });
    }

    fn poll_issue_action(&mut self) {
        let result = match self.issue_action_receiver.as_ref() {
            Some(receiver) => match receiver.try_recv() {
                Ok(result) => Some(result),
                Err(TryRecvError::Empty) => None,
                Err(TryRecvError::Disconnected) => Some(Err("Issue action command stopped unexpectedly".into())),
            },
            None => None,
        };
        let Some(result) = result else { return; };
        self.issue_action_receiver = None;
        let action = self.issue_action.take();
        let number = self.issue_action_number.take();
        match result {
            Ok(()) => {
                let key = match action {
                    Some(NativeIssueAction::Close) => "issue.closedToast",
                    Some(NativeIssueAction::Reopen) => "issue.reopenedToast",
                    Some(NativeIssueAction::Comment(_)) => "issue.commentPosted",
                    None => return,
                };
                self.issue_action_notice = Some(translate(&self.preferences.language, key).to_owned());
                self.load_issues();
                if let Some(number) = number.filter(|number| self.issue_detail_number == Some(*number)) {
                    self.load_issue_detail(number);
                }
                self.issue_comment_open = false;
                self.issue_comment_body.clear();
            }
            Err(error) => self.issue_action_error = Some(error),
        }
    }

    fn submit_issue_create(&mut self) {
        let title = self.issue_create_title.trim().to_owned();
        if title.is_empty() || self.issue_create_busy { return; }
        let Some(repo_path) = self.repo_path.clone() else {
            self.issue_create_error = Some("Open a repository first".into());
            return;
        };
        let body = self.issue_create_body.trim().to_owned();
        let (sender, receiver) = mpsc::channel();
        self.issue_create_receiver = Some(receiver);
        self.issue_create_busy = true;
        self.issue_create_error = None;
        self.issue_create_notice = None;
        std::thread::spawn(move || {
            let result = Command::new("gh")
                .args(["issue", "create", "--title", &title, "--body", &body])
                .current_dir(repo_path)
                .stdin(Stdio::null())
                .output()
                .map_err(|error| format!("Could not start GitHub CLI (gh): {error}"))
                .and_then(|output| {
                    if !output.status.success() {
                        return Err(redact_url_credentials(&String::from_utf8_lossy(&output.stderr)));
                    }
                    String::from_utf8_lossy(&output.stdout).trim().rsplit('/')
                        .next().and_then(|value| value.trim().parse::<u64>().ok())
                        .ok_or_else(|| "GitHub created the issue but did not return its number".into())
                });
            let _ = sender.send(result);
        });
    }

