    fn submit_pull_request_review(&mut self) {
        let Some(number) = self.pull_request_review_number else { return; };
        let Some(repo_path) = self.repo_path.clone() else {
            self.pull_request_review_error = Some("Open a repository first".into());
            return;
        };
        let body = self.pull_request_review_body.trim().to_owned();
        if self.pull_request_review_kind != PullRequestReviewKind::Approve && body.is_empty() {
            return;
        }

        let args = if let Some(thread_id) = &self.pull_request_reply_thread {
            const REPLY_QUERY: &str = "mutation($id: ID!, $body: String!) { addPullRequestReviewThreadReply(input: {pullRequestReviewThreadId: $id, body: $body}) { clientMutationId } }";
            let body_json = serde_json::to_string(&body).unwrap_or_else(|_| "\"\"".into());
            vec![
                "api".to_owned(), "graphql".to_owned(), "-F".to_owned(), format!("id={thread_id}"),
                "-F".to_owned(), format!("body:={body_json}"), "-f".to_owned(),
                format!("query={REPLY_QUERY}"),
            ]
        } else {
            let mut args = vec!["pr".to_owned(), "review".to_owned(), number.to_string()];
            match self.pull_request_review_kind {
                PullRequestReviewKind::Comment => args.push("--comment".into()),
                PullRequestReviewKind::Approve => args.push("--approve".into()),
                PullRequestReviewKind::RequestChanges => args.push("--request-changes".into()),
            }
            if !body.is_empty() {
                args.push("--body".into());
                args.push(body);
            }
            args
        };

        let (sender, receiver) = mpsc::channel();
        self.pull_request_review_receiver = Some(receiver);
        self.pull_request_review_busy = true;
        self.pull_request_review_error = None;
        self.pull_request_review_notice = None;
        std::thread::spawn(move || {
            let result = Command::new("gh")
                .args(args)
                .current_dir(repo_path)
                .stdin(Stdio::null())
                .output()
                .map_err(|error| format!("Could not start GitHub CLI (gh): {error}"))
                .and_then(|output| {
                    if output.status.success() {
                        Ok(())
                    } else {
                        Err(redact_url_credentials(&String::from_utf8_lossy(&output.stderr)))
                    }
                });
            let _ = sender.send(result);
        });
    }

    fn poll_pull_request_review(&mut self) {
        let result = match self.pull_request_review_receiver.as_ref() {
            Some(receiver) => match receiver.try_recv() {
                Ok(result) => Some(result),
                Err(TryRecvError::Empty) => None,
                Err(TryRecvError::Disconnected) => Some(Err("Review command stopped unexpectedly".into())),
            },
            None => None,
        };
        let Some(result) = result else { return; };
        self.pull_request_review_receiver = None;
        self.pull_request_review_busy = false;
        match result {
            Ok(()) => {
                let reply = self.pull_request_reply_thread.is_some();
                self.pull_request_review_notice = Some(translate(
                    &self.preferences.language,
                    if reply { "prDetail.replySubmitted" } else { "prDetail.reviewSubmitted" },
                ).to_owned());
                self.pull_request_review_open = false;
                self.pull_request_review_body.clear();
                self.pull_request_reply_thread = None;
                if let Some(number) = self.pull_request_review_number {
                    if self.pull_request_detail_number == Some(number) {
                        self.load_pull_request_detail(number);
                    }
                }
            }
            Err(error) => self.pull_request_review_error = Some(error),
        }
    }

