fn patch_lines(diff: git2::Diff<'_>) -> Result<Vec<String>, git2::Error> {
    let mut output = Vec::new();
    let mut secret_paths = std::collections::BTreeSet::new();
    diff.print(DiffFormat::Patch, |delta, _hunk, line| {
        let path = delta
            .new_file()
            .path()
            .or_else(|| delta.old_file().path())
            .and_then(|path| path.to_str())
            .unwrap_or_default();
        if is_secret_file(path) {
            secret_paths.insert(path.to_owned());
        } else {
            output.extend_from_slice(line.content());
        }
        true
    })?;
    let mut lines = String::from_utf8_lossy(&output)
        .lines()
        .map(str::to_owned)
        .collect::<Vec<_>>();
    lines.extend(secret_paths.into_iter().map(|path| {
        format!("Secret-looking file; contents hidden: {path}")
    }));
    Ok(lines)
}

fn command_error(prefix: &str, stderr: &[u8]) -> String {
    let message = String::from_utf8_lossy(stderr).trim().to_owned();
    if message.is_empty() { prefix.to_owned() } else { format!("{prefix}: {message}") }
}

fn secret_paths_to_push(
    repo: &Repository,
    remote_name: &str,
    branch_name: &str,
    remote_branch: &str,
) -> Result<Vec<String>, git2::Error> {
    let branch = repo.find_branch(branch_name, BranchType::Local)?;
    let local_tip = branch
        .get()
        .target()
        .ok_or_else(|| git2::Error::from_str("Branch has no commit to push"))?;
    let tracking_ref = format!("refs/remotes/{remote_name}/{remote_branch}");
    let upstream_tip = repo
        .find_reference(&tracking_ref)
        .ok()
        .and_then(|upstream| upstream.target());
    secret_paths_for_tip(repo, local_tip, upstream_tip)
}

fn secret_paths_for_tip(
    repo: &Repository,
    local_tip: git2::Oid,
    upstream_tip: Option<git2::Oid>,
) -> Result<Vec<String>, git2::Error> {
    let mut walk = repo.revwalk()?;
    walk.push(local_tip)?;
    if let Some(upstream_tip) = upstream_tip {
        walk.hide(upstream_tip)?;
    }
    let mut paths = std::collections::BTreeSet::new();
    for oid in walk {
        let commit = repo.find_commit(oid?)?;
        let current_tree = commit.tree()?;
        let parent_tree = commit.parent(0).ok().map(|parent| parent.tree()).transpose()?;
        let diff = repo.diff_tree_to_tree(parent_tree.as_ref(), Some(&current_tree), None)?;
        for delta in diff.deltas() {
            for path in [delta.new_file().path(), delta.old_file().path()].into_iter().flatten() {
                if let Some(path) = path.to_str().filter(|path| is_secret_file(path)) {
                    paths.insert(path.to_owned());
                }
            }
        }
    }
    Ok(paths.into_iter().collect())
}

fn remote_snapshot(repo: &Repository, name: &str) -> Result<Vec<(String, String)>, git2::Error> {
    let config = repo.config()?.open_level(ConfigLevel::Local)?;
    let pattern = format!("remote.{name}.*");
    let mut entries = config.entries(Some(&pattern))?;
    let mut values = Vec::new();
    while let Some(entry) = entries.next() {
        let entry = entry?;
        if let (Some(key), Some(value)) = (entry.name(), entry.value()) {
            values.push((key.to_owned(), value.to_owned()));
        }
    }
    values.sort();
    Ok(values)
}

fn validate_worktree_path(repo: &Repository, relative: &Path) -> Result<(PathBuf, PathBuf), git2::Error> {
    if relative.as_os_str().is_empty()
        || relative.is_absolute()
        || relative.components().any(|component| !matches!(component, Component::Normal(_)))
    {
        return Err(git2::Error::from_str("Unsafe repository path"));
    }
    let workdir = repo
        .workdir()
        .ok_or_else(|| git2::Error::from_str("Bare repositories have no working tree"))?;
    let root = workdir
        .canonicalize()
        .map_err(|error| git2::Error::from_str(&error.to_string()))?;
    let full_path = workdir.join(relative);
    if let Ok(metadata) = std::fs::symlink_metadata(&full_path) {
        if !metadata.file_type().is_symlink() && !metadata.is_file() {
            return Err(git2::Error::from_str("Restore target is not a regular file"));
        }
    }
    let mut ancestor = full_path
        .parent()
        .map(Path::to_path_buf)
        .ok_or_else(|| git2::Error::from_str("Invalid repository path"))?;
    while !ancestor.exists() {
        if !ancestor.pop() {
            return Err(git2::Error::from_str("Invalid repository path"));
        }
    }
    if !ancestor
        .canonicalize()
        .map_err(|error| git2::Error::from_str(&error.to_string()))?
        .starts_with(&root)
    {
        return Err(git2::Error::from_str("Path resolves outside repository"));
    }
    Ok((root, full_path))
}

fn snapshot_files(repo: &Repository, paths: &[String]) -> Result<Vec<FileSnapshot>, git2::Error> {
    let mut snapshots = Vec::with_capacity(paths.len());
    for path in paths {
        let relative = Path::new(path);
        let (_, full_path) = validate_worktree_path(repo, relative)?;
        let snapshot = match std::fs::symlink_metadata(&full_path) {
            Ok(metadata) => {
                if metadata.file_type().is_symlink() {
                    let link_target = std::fs::read_link(&full_path)
                        .map_err(|error| git2::Error::from_str(&error.to_string()))?;
                    FileSnapshot { path: path.clone(), contents: None, link_target: Some(link_target), mode: 0o120000 }
                } else {
                if metadata.len() > 100 * 1024 * 1024 {
                    return Err(git2::Error::from_str("Undo snapshot limited to 100 MB per file"));
                }
                let contents = std::fs::read(&full_path)
                    .map_err(|error| git2::Error::from_str(&error.to_string()))?;
                #[cfg(unix)]
                let mode = {
                    use std::os::unix::fs::PermissionsExt;
                    metadata.permissions().mode() & 0o777
                };
                #[cfg(not(unix))]
                let mode = 0o644;
                FileSnapshot { path: path.clone(), contents: Some(contents), link_target: None, mode }
                }
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => FileSnapshot {
                path: path.clone(),
                contents: None,
                link_target: None,
                mode: 0,
            },
            Err(error) => return Err(git2::Error::from_str(&error.to_string())),
        };
        snapshots.push(snapshot);
    }
    Ok(snapshots)
}

fn restore_file_from_commit(repo: &Repository, oid: &str, path: &str) -> Result<(), git2::Error> {
    let relative = Path::new(path);
    let (_, full_path) = validate_worktree_path(repo, relative)?;
    let commit = repo.find_commit(git2::Oid::from_str(oid)?)?;
    let tree = commit.tree()?;
    let target = match tree.get_path(relative) {
        Ok(entry) => {
            if entry.kind() != Some(git2::ObjectType::Blob) {
                return Err(git2::Error::from_str("Selected commit path is not a regular file"));
            }
            let blob = repo.find_blob(entry.id())?;
            if entry.filemode() == 0o120000 {
                Some((None, Some(path_from_git_bytes(blob.content())), 0o120000))
            } else {
                Some((Some(blob.content().to_vec()), None, if entry.filemode() == 0o100755 { 0o755 } else { 0o644 }))
            }
        }
        Err(error) if error.code() == git2::ErrorCode::NotFound => None,
        Err(error) => return Err(error),
    };
    match target {
        Some((contents, link_target, mode)) => {
            let parent = full_path
                .parent()
                .ok_or_else(|| git2::Error::from_str("Invalid repository path"))?;
            std::fs::create_dir_all(parent)
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            remove_existing_file(&full_path)?;
            if let Some(target) = link_target {
                create_symlink(&target, &full_path)?;
            } else if let Some(contents) = contents {
                std::fs::write(&full_path, contents)
                    .map_err(|error| git2::Error::from_str(&error.to_string()))?;
                set_file_mode(&full_path, mode)?;
            }
        }
        None => match std::fs::remove_file(&full_path) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(git2::Error::from_str(&error.to_string())),
        },
    }
    Ok(())
}

fn restore_snapshots(repo: &Repository, snapshots: &[FileSnapshot]) -> Result<(), git2::Error> {
    for snapshot in snapshots {
        let relative = Path::new(&snapshot.path);
        let (_, full_path) = validate_worktree_path(repo, relative)?;
        if let Some(target) = &snapshot.link_target {
            let parent = full_path
                .parent()
                .ok_or_else(|| git2::Error::from_str("Invalid repository path"))?;
            std::fs::create_dir_all(parent)
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            remove_existing_file(&full_path)?;
            create_symlink(target, &full_path)?;
        } else if let Some(contents) = &snapshot.contents {
            let parent = full_path
                .parent()
                .ok_or_else(|| git2::Error::from_str("Invalid repository path"))?;
            std::fs::create_dir_all(parent)
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            remove_existing_file(&full_path)?;
            std::fs::write(&full_path, contents)
                .map_err(|error| git2::Error::from_str(&error.to_string()))?;
            set_file_mode(&full_path, snapshot.mode)?;
        } else {
            match std::fs::remove_file(&full_path) {
                Ok(()) => {}
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
                Err(error) => return Err(git2::Error::from_str(&error.to_string())),
            }
        }
    }
    Ok(())
}

fn path_from_git_bytes(bytes: &[u8]) -> PathBuf {
    #[cfg(unix)]
    {
        use std::os::unix::ffi::OsStringExt;
        PathBuf::from(std::ffi::OsString::from_vec(bytes.to_vec()))
    }
    #[cfg(not(unix))]
    {
        PathBuf::from(String::from_utf8_lossy(bytes).into_owned())
    }
}

fn create_symlink(target: &Path, link: &Path) -> Result<(), git2::Error> {
    #[cfg(unix)]
    {
        std::os::unix::fs::symlink(target, link)
            .map_err(|error| git2::Error::from_str(&error.to_string()))
    }
    #[cfg(windows)]
    {
        std::os::windows::fs::symlink_file(target, link)
            .map_err(|error| git2::Error::from_str(&error.to_string()))
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = (target, link);
        Err(git2::Error::from_str("Symbolic links are unsupported on this platform"))
    }
}

fn set_file_mode(path: &Path, mode: u32) -> Result<(), git2::Error> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(mode))
            .map_err(|error| git2::Error::from_str(&error.to_string()))
    }
    #[cfg(not(unix))]
    {
        let _ = (path, mode);
        Ok(())
    }
}

fn remove_existing_file(path: &Path) -> Result<(), git2::Error> {
    match std::fs::symlink_metadata(path) {
        Ok(metadata) if metadata.is_dir() => Err(git2::Error::from_str("Restore target is a directory")),
        Ok(_) => std::fs::remove_file(path)
            .map_err(|error| git2::Error::from_str(&error.to_string())),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(git2::Error::from_str(&error.to_string())),
    }
}

fn restore_remote_snapshot(
    repo: &Repository,
    name: &str,
    snapshot: &[(String, String)],
) -> Result<(), git2::Error> {
    if !remote_snapshot(repo, name)?.is_empty() {
        repo.remote_delete(name)?;
    }
    if snapshot.is_empty() {
        return Ok(());
    }
    let prefix = format!("remote.{name}.");
    let url_key = format!("{prefix}url");
    let url = snapshot
        .iter()
        .find(|(key, _)| key.eq_ignore_ascii_case(&url_key))
        .map(|(_, value)| value.as_str())
        .ok_or_else(|| git2::Error::from_str("Cannot restore remote without a URL"))?;
    repo.remote(name, url)?;
    let mut config = repo.config()?.open_level(ConfigLevel::Local)?;
    let mut grouped = std::collections::BTreeMap::<String, Vec<String>>::new();
    for (key, value) in snapshot {
        grouped.entry(key.clone()).or_default().push(value.clone());
    }
    for (key, values) in grouped {
        config.set_str(&key, &values[0])?;
        for value in values.iter().skip(1) {
            config.set_multivar(&key, "^$", value)?;
        }
    }
    Ok(())
}

fn status_label(status: Status) -> &'static str {
    if status.intersects(Status::CONFLICTED) {
        "Conflict"
    } else if status.intersects(Status::INDEX_NEW | Status::WT_NEW) {
        "Added"
    } else if status.intersects(Status::INDEX_DELETED | Status::WT_DELETED) {
        "Deleted"
    } else if status.intersects(Status::INDEX_RENAMED | Status::WT_RENAMED) {
        "Renamed"
    } else if status.intersects(Status::INDEX_MODIFIED | Status::WT_MODIFIED) {
        "Modified"
    } else {
        "Changed"
    }
}

fn set_stage(repo: &mut Repository, path: &str, stage: bool) -> Result<(), git2::Error> {
    if stage {
        let mut index = repo.index()?;
        index.add_path(Path::new(path))?;
        index.write()
    } else if let Ok(head) = repo.revparse_single("HEAD") {
        repo.reset_default(Some(&head), [Path::new(path)])
    } else {
        let mut index = repo.index()?;
        index.remove_path(Path::new(path))?;
        index.write()
    }
}

fn root_ignore_pattern(path: &str) -> String {
    let mut escaped = path.replace('\\', "\\\\");
    if escaped.starts_with(['!', '#']) { escaped.insert(0, '\\'); }
    while escaped.ends_with(' ') { escaped.pop(); escaped.push_str("\\ "); }
    format!("/{escaped}")
}

fn has_embedded_url_credentials(url: &str) -> bool {
    if let Some((_, authority_and_path)) = url.split_once("://") {
        let authority = authority_and_path
            .split(['/', '?', '#'])
            .next()
            .unwrap_or_default();
        return authority.contains('@');
    }
    url.split_once('@')
        .is_some_and(|(userinfo, _)| userinfo.contains(':'))
}

fn remote_web_url(remote: &str) -> Option<String> {
    let (host, path) = if let Some(rest) = remote.strip_prefix("https://") {
        let (authority, path) = rest.split_once('/')?;
        if authority.contains('@') { return None; }
        (authority, path)
    } else if let Some(rest) = remote.strip_prefix("http://") {
        let (authority, path) = rest.split_once('/')?;
        if authority.contains('@') { return None; }
        (authority, path)
    } else if let Some(rest) = remote.strip_prefix("ssh://") {
        let (authority, path) = rest.split_once('/')?;
        let host = authority.rsplit('@').next()?;
        (host, path)
    } else {
        let without_user = remote.rsplit('@').next()?;
        let (host, path) = without_user.split_once(':')?;
        (host, path)
    };
    if host.is_empty() || !host.bytes().all(|byte| byte.is_ascii_alphanumeric() || b".-:[]".contains(&byte)) {
        return None;
    }
    let path = path.trim_matches('/').strip_suffix(".git").unwrap_or(path.trim_matches('/'));
    if path.is_empty() { return None; }
    let encoded_path = path.bytes().map(|byte| {
        if byte.is_ascii_alphanumeric() || b"/-._~".contains(&byte) {
            (byte as char).to_string()
        } else {
            format!("%{byte:02X}")
        }
    }).collect::<String>();
    Some(format!("https://{host}/{encoded_path}"))
}

fn repository_github_url(path: &Path) -> Option<String> {
    let repository = Repository::discover(path).ok()?;
    let remotes = repository.remotes().ok()?;
    let names = remotes.iter().flatten().collect::<Vec<_>>();
    let ordered = names.iter().copied().filter(|name| *name == "origin")
        .chain(names.iter().copied().filter(|name| *name != "origin"));
    ordered.filter_map(|name| {
        repository.find_remote(name).ok()?.url().and_then(remote_web_url)
    }).find(|url| {
        url.strip_prefix("https://").and_then(|host_path| host_path.split('/').next())
            .is_some_and(|host| host.eq_ignore_ascii_case("github.com"))
    })
}

fn local_clone_url(url: &str, shallow: bool) -> String {
    if !shallow || url.contains("://") || url.contains('@') {
        return url.to_owned();
    }
    let Ok(path) = Path::new(url).canonicalize() else { return url.to_owned() };
    let path = path.to_string_lossy().replace('\\', "/");
    #[cfg(windows)]
    let path = if path.as_bytes().get(1) == Some(&b':') { format!("/{path}") } else { path };
    let encoded = path.bytes().map(|byte| {
        if byte.is_ascii_alphanumeric() || b"/-._~:".contains(&byte) {
            (byte as char).to_string()
        } else {
            format!("%{byte:02X}")
        }
    }).collect::<String>();
    format!("file://{encoded}")
}

fn parse_clone_progress(line: &str) -> Option<(String, u8)> {
    let line = line.trim_matches(['\r', '\n']).trim();
    let line = line.strip_prefix("remote: ").unwrap_or(line);
    let stage = line.split(':').next()?.trim();
    if stage.is_empty() { return None; }
    let percent = line.split_once('%').and_then(|(prefix, _)| {
        let digits = prefix.chars().rev().take_while(char::is_ascii_digit).collect::<String>();
        digits.chars().rev().collect::<String>().parse::<u8>().ok()
    }).unwrap_or(0).min(100);
    Some((stage.to_owned(), percent))
}

fn open_web_url(url: &str) -> Result<(), String> {
    let parsed = url::Url::parse(url).map_err(|_| "Invalid web URL".to_owned())?;
    if !matches!(parsed.scheme(), "http" | "https")
        || parsed.host_str().is_none()
        || !parsed.username().is_empty()
        || parsed.password().is_some()
    {
        return Err("Only HTTP and HTTPS links can open in the browser".into());
    }
    #[cfg(target_os = "macos")]
    let mut command = Command::new("open");
    #[cfg(target_os = "windows")]
    let mut command = {
        let mut command = Command::new("rundll32.exe");
        command.arg("url.dll,FileProtocolHandler");
        command
    };
    #[cfg(target_os = "linux")]
    let mut command = Command::new("xdg-open");
    command.arg(parsed.as_str()).spawn().map(|_| ()).map_err(|error| format!("Could not open remote website: {error}"))
}

fn editor_arguments(
    template: &str,
    path: &Path,
    repo: &Path,
    line: Option<usize>,
    col: Option<usize>,
) -> Result<Vec<std::ffi::OsString>, String> {
    let template = if template.trim().is_empty() { "{path}" } else { template };
    let tokens = shlex::split(template).ok_or_else(|| "Invalid quoting in editor arguments".to_owned())?;
    let mut args = Vec::new();
    for token in tokens {
        let needs_line = token.contains("{line}") && line.is_none();
        let needs_col = token.contains("{col}") && col.is_none();
        if needs_line || needs_col {
            if !token.starts_with('-') && args.last().is_some_and(|arg: &std::ffi::OsString| {
                arg.to_string_lossy().starts_with('-')
            }) {
                args.pop();
            }
            continue;
        }
        if token == "{path}" {
            args.push(path.as_os_str().to_owned());
            continue;
        }
        let path_value = path.to_string_lossy();
        let repo_value = repo.to_string_lossy();
        let expanded = token
            .replace("{path}", &path_value)
            .replace("{repo}", &repo_value)
            .replace("{line}", &line.map_or_else(String::new, |value| value.to_string()))
            .replace("{col}", &col.map_or_else(String::new, |value| value.to_string()));
        args.push(expanded.into());
    }
    if args.is_empty() && template == "{path}" { args.push(path.as_os_str().to_owned()); }
    Ok(args)
}

fn discover_editors() -> Vec<(String, String)> {
        let candidates = [
            ("Visual Studio Code", "code"),
            ("VS Code Insiders", "code-insiders"),
            ("Cursor", "cursor"),
            ("Windsurf", "windsurf"),
            ("Zed", "zed"),
            ("Sublime Text", "subl"),
            ("IntelliJ IDEA", "idea"),
            ("WebStorm", "webstorm"),
            ("PyCharm", "pycharm"),
            ("RustRover", "rustrover"),
            ("GoLand", "goland"),
            ("CLion", "clion"),
            ("Rider", "rider"),
            ("PhpStorm", "phpstorm"),
            ("Xcode", "xed"),
        ];
        let paths = std::env::var_os("PATH").map(|path| std::env::split_paths(&path).collect::<Vec<_>>())
            .unwrap_or_default();
        candidates.into_iter().filter_map(|(name, command)| {
            paths.iter().any(|directory| executable_on_path(&directory.join(command)))
                .then(|| (name.to_owned(), command.to_owned()))
        }).collect()
}

fn executable_on_path(path: &Path) -> bool {
    #[cfg(windows)]
    {
        return path.is_file() || ["exe", "cmd", "bat"].iter().any(|extension| {
            let mut candidate = path.as_os_str().to_owned();
            candidate.push(format!(".{extension}"));
            PathBuf::from(candidate).is_file()
        });
    }
    #[cfg(unix)]
    let Ok(metadata) = std::fs::metadata(path) else { return false };
    #[cfg(unix)]
    if !metadata.is_file() { return false; }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        metadata.permissions().mode() & 0o111 != 0
    }
}

fn reveal_in_file_manager(path: &Path) -> Result<(), String> {
    #[cfg(target_os = "macos")]
    let mut command = {
        let mut command = Command::new("open");
        command.arg("-R");
        command
    };
    #[cfg(target_os = "windows")]
    let mut command = {
        let mut command = Command::new("explorer.exe");
        command.arg("/select,");
        command
    };
    #[cfg(target_os = "linux")]
    let mut command = {
        let mut command = Command::new("xdg-open");
        command.arg(path);
        return command.spawn().map(|_| ()).map_err(|error| format!("Could not reveal repository: {error}"));
    };
    #[cfg(any(target_os = "macos", target_os = "windows"))]
    command.arg(path).spawn().map(|_| ()).map_err(|error| format!("Could not reveal repository: {error}"))
}

fn redact_url_credentials(message: &str) -> String {
    let mut output = String::with_capacity(message.len());
    let mut rest = message;
    while let Some(scheme_end) = rest.find("://") {
        let authority_start = scheme_end + 3;
        output.push_str(&rest[..authority_start]);
        rest = &rest[authority_start..];
        let authority_end = rest
            .find(|character: char| character.is_whitespace() || "/?#\"'".contains(character))
            .unwrap_or(rest.len());
        let authority = &rest[..authority_end];
        if let Some(at) = authority.rfind('@') {
            output.push_str("[redacted]@");
            output.push_str(&authority[at + 1..]);
        } else {
            output.push_str(authority);
        }
        rest = &rest[authority_end..];
    }
    output.push_str(rest);
    output
}
